#[test]
fn cr_208_4_base_pt_excludes_modifiers_counters_and_switching() {
    use ironsmith::continuous::{EffectTarget, Modification, PtSublayer};
    use ironsmith::effects::ApplyContinuousEffect;
    use ironsmith::{
        ChooseSpec, Comparison, CounterType, Effect, ObjectFilter, StackEntry, Until, Value, Zone,
    };
    let alice = PlayerId::from_index(0);
    for reverse_timestamps in [false, true] {
        for switches in 0..=2 {
            let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
            let id = counter_creature(&mut game, Zone::Battlefield);
            let mut ctx = EffectContext::new_default(id, alice);
            let mut modifications = vec![
                Modification::SetPowerToughness {
                    power: 2.into(),
                    toughness: 5.into(),
                    sublayer: PtSublayer::Setting,
                },
                Modification::ModifyPowerToughness {
                    power: 3,
                    toughness: -1,
                },
            ];
            for _ in 0..switches {
                modifications.push(Modification::SwitchPowerToughness);
            }
            if reverse_timestamps {
                modifications.reverse();
            }
            for modification in modifications {
                ApplyContinuousEffect::new(
                    EffectTarget::Specific(id),
                    modification,
                    Until::EndOfTurn,
                )
                .execute(&mut game, &mut ctx)
                .unwrap();
            }
            game.add_counters(id, CounterType::PlusOnePlusOne, 2);
            let chars = game.current_characteristics(id).unwrap();
            assert_eq!(
                (chars.base_power, chars.base_toughness),
                (Some(2), Some(5)),
                "CR 208.4b: reverse={reverse_timestamps}, switches={switches}"
            );
            let expected = if switches % 2 == 0 {
                (Some(7), Some(6))
            } else {
                (Some(6), Some(7))
            };
            assert_eq!(
                (chars.power, chars.toughness),
                expected,
                "CR 208.4a / 613.4b-d: sublayers apply regardless of timestamps between sublayers"
            );
            // Exercise effect resolution as well as the calculated fields: numeric
            // readers and filters must use the same definition of base power.
            let mut exact_base = ObjectFilter::creature().with_base_power(Comparison::Equal(2));
            exact_base.specific = Some(id);
            let mut wrong_base =
                ObjectFilter::creature().with_base_power(Comparison::Equal(expected.0.unwrap()));
            wrong_base.specific = Some(id);
            let mut larger = ObjectFilter::creature();
            larger.specific = Some(id);
            larger.power_greater_than_base_power = true;
            for (value, required) in [
                (
                    Value::BasePowerOf(Box::new(ChooseSpec::SpecificObject(id))),
                    2,
                ),
                (Value::BasePowerOf(Box::new(ChooseSpec::Source)), 2),
                (Value::SourcePower, expected.0.unwrap()),
                (
                    Value::PowerOf(Box::new(ChooseSpec::SpecificObject(id))),
                    expected.0.unwrap(),
                ),
                (Value::Count(exact_base), 1),
                (Value::Count(wrong_base), 0),
                (Value::Count(larger), 1),
            ] {
                game.player_mut(alice).unwrap().life = 20;
                game.stack.push(StackEntry::ability(
                    id,
                    alice,
                    vec![Effect::gain_life(value.clone())],
                ));
                ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                assert_eq!(
                    game.player(alice).unwrap().life - 20,
                    required,
                    "CR 208.4b / 608.2h: value={value:?}, reverse={reverse_timestamps}, switches={switches}"
                );
            }
        }
    }
}

