#[test]
fn cr_121_8_a_card_drawn_during_announcement_cannot_pay_a_creature_discard_cost() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::costs::Cost;
    use ironsmith::decisions::context::DecisionContext;
    use ironsmith::events::life::matchers::WouldGainLifeMatcher;
    use ironsmith::mana_payment::{ManaPaymentResponse, manual_mana_abilities};
    use ironsmith::replacement::{ReplacementAction, ReplacementEffect};
    use ironsmith::{
        Ability, CardId, CardType, CastingMethod, Effect, GameProgress, LegalAction, ManaCost,
        ManaSymbol, Phase, PriorityLoopState, PriorityResponse, TotalCost, Zone,
    };
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for spell_parent in [false, true] {
            for during in [false, true] {
                for filtered in [false, true] {
                    let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                    game.turn.active_player = actor;
                    game.turn.priority_player = Some(actor);
                    game.turn.phase = Phase::FirstMain;
                    let green_definition = CardDefinitionBuilder::new(
                        CardId::new(),
                        "Mana with externally replaced life gain",
                    )
                    .card_types(vec![CardType::Artifact])
                    .with_ability(Ability::mana_with_effects(
                        TotalCost::free(),
                        vec![
                            Effect::add_mana(vec![ManaSymbol::Green]),
                            Effect::gain_life(2),
                        ],
                    ))
                    .build();
                    let green = game.create_object_from_definition(
                        &green_definition,
                        actor,
                        Zone::Battlefield,
                    );
                    let red_definition = CardDefinitionBuilder::new(
                        CardId::new(),
                        "Red funding for discard announcement",
                    )
                    .card_types(vec![CardType::Artifact])
                    .with_ability(Ability::mana(TotalCost::free(), vec![ManaSymbol::Red]))
                    .build();
                    game.create_object_from_definition(&red_definition, actor, Zone::Battlefield);
                    let replacement_definition =
                        CardDefinitionBuilder::new(CardId::new(), "Replace life gain with draw")
                            .card_types(vec![CardType::Enchantment])
                            .build();
                    let replacement_source = game.create_object_from_definition(
                        &replacement_definition,
                        actor,
                        Zone::Battlefield,
                    );
                    game.effect_store.replacement_effects.add_resolution_effect(
                        ReplacementEffect::with_matcher(
                            replacement_source,
                            actor,
                            WouldGainLifeMatcher::you(),
                            ReplacementAction::Instead(vec![Effect::draw(1)]),
                        ),
                    );
                    let creature_definition = CardDefinitionBuilder::new(
                        CardId::new(),
                        "Creature for characteristic-specific discard",
                    )
                    .card_types(vec![CardType::Creature])
                    .power_toughness(ironsmith::PowerToughness::fixed(2, 3))
                    .build();
                    let mut old_cards = Vec::new();
                    for _ in 0..2 {
                        old_cards.push(game.create_object_from_definition(
                            &creature_definition,
                            actor,
                            Zone::Hand,
                        ));
                    }
                    for _ in 0..3 {
                        game.create_object_from_definition(
                            &creature_definition,
                            actor,
                            Zone::Library,
                        );
                    }
                    let top = *game.player(actor).unwrap().library.last().unwrap();
                    let drawn_stable = game.object(top).unwrap().stable_id;
                    let discard = Cost::discard(1, filtered.then_some(CardType::Creature));
                    let mana =
                        ManaCost::from_symbols(vec![ManaSymbol::Red, ManaSymbol::Generic(1)]);
                    let action = if spell_parent {
                        let definition =
                            CardDefinitionBuilder::new(CardId::new(), "Spell with discard cost")
                                .card_types(vec![CardType::Instant])
                                .mana_cost(mana)
                                .additional_cost(TotalCost::from_cost(discard))
                                .with_spell_effect(vec![Effect::gain_life(10)])
                                .build();
                        let id = game.create_object_from_definition(&definition, actor, Zone::Hand);
                        LegalAction::CastSpell {
                            spell_id: id,
                            from_zone: Zone::Hand,
                            casting_method: CastingMethod::Normal,
                        }
                    } else {
                        let definition = CardDefinitionBuilder::new(
                            CardId::new(),
                            "Activation with discard cost",
                        )
                        .card_types(vec![CardType::Artifact])
                        .with_ability(Ability::activated(
                            TotalCost::from_costs(vec![Cost::mana(mana), discard]),
                            vec![Effect::gain_life(10)],
                        ))
                        .build();
                        let id = game.create_object_from_definition(
                            &definition,
                            actor,
                            Zone::Battlefield,
                        );
                        LegalAction::ActivateAbility {
                            source: id,
                            ability_index: 0,
                        }
                    };
                    let mut state = PriorityLoopState::new(game.players_in_game());
                    let mut queue = ironsmith::triggers::TriggerQueue::new();
                    let mut dm = ironsmith::decision::SelectFirstDecisionMaker;
                    if !during {
                        ironsmith::game_loop::apply_priority_response_with_dm(
                            &mut game,
                            &mut queue,
                            &mut state,
                            &PriorityResponse::PriorityAction(LegalAction::ActivateManaAbility {
                                source: green,
                                ability_index: 0,
                            }),
                            &mut dm,
                        )
                        .unwrap();
                    }
                    assert!(
                        ironsmith::compute_legal_actions(&game, actor)
                            .unwrap()
                            .contains(&action)
                    );
                    let mut progress = ironsmith::game_loop::apply_priority_response_with_dm(
                        &mut game,
                        &mut queue,
                        &mut state,
                        &PriorityResponse::PriorityAction(action),
                        &mut dm,
                    )
                    .unwrap();
                    if during {
                        let payment = state
                            .pending_cast
                            .as_ref()
                            .and_then(|p| p.pending_mana_payment.as_ref())
                            .or_else(|| {
                                state
                                    .pending_activation
                                    .as_ref()
                                    .and_then(|p| p.pending_mana_payment.as_ref())
                            })
                            .unwrap();
                        assert!(
                            manual_mana_abilities(&game, &payment.request).contains(&(green, 0))
                        );
                        progress = ironsmith::game_loop::apply_priority_response_with_dm(
                            &mut game,
                            &mut queue,
                            &mut state,
                            &PriorityResponse::ManaPaymentPlan(ManaPaymentResponse::Activate {
                                source: green,
                                ability_index: 0,
                            }),
                            &mut dm,
                        )
                        .unwrap();
                    }
                    assert_eq!(game.player(actor).unwrap().library.len(), 2);
                    let drawn = game.find_object_by_stable_id(drawn_stable).unwrap();
                    assert_eq!(game.object(drawn).unwrap().zone, Zone::Hand);
                    let mut candidates = None;
                    for _ in 0..5 {
                        let response = match &progress {
                            GameProgress::NeedsDecisionCtx(DecisionContext::SelectObjects(ctx)) => {
                                candidates = Some(ctx.candidates.clone());
                                break;
                            }
                            GameProgress::NeedsDecisionCtx(DecisionContext::ManaPayment(ctx)) => {
                                PriorityResponse::ManaPaymentPlan(ManaPaymentResponse::Confirm {
                                    plan_id: ctx.plan.id,
                                    request_hash: ctx.plan.request_hash,
                                })
                            }
                            GameProgress::NeedsDecisionCtx(DecisionContext::SelectOptions(_)) => {
                                PriorityResponse::NextCostChoice(0)
                            }
                            other => panic!(
                                "expected actual mana/cost/discard decision, got {other:?};cast={:?};activation={:?}",
                                state.pending_cast, state.pending_activation
                            ),
                        };
                        progress = ironsmith::game_loop::apply_priority_response_with_dm(
                            &mut game, &mut queue, &mut state, &response, &mut dm,
                        )
                        .unwrap();
                    }
                    let candidates =
                        candidates.expect("native announcement must reach its discard choice");
                    for old in &old_cards {
                        assert!(
                            candidates.iter().any(|c| c.id == *old && c.legal),
                            "preexisting creatures remain legal"
                        );
                    }
                    let offered = candidates.iter().any(|c| c.id == drawn && c.legal);
                    let required = !(during && filtered);
                    if offered != required {
                        discrepancies.push(format!("actor={actor:?},spell={spell_parent},during={during},filtered={filtered}:newly drawn card offered={offered},required={required}"));
                    }
                    // Follow the offered choice through the authoritative payer,
                    // so an illegal menu entry is backed by actual cost acceptance.
                    let selected = if offered { drawn } else { old_cards[0] };
                    ironsmith::game_loop::apply_priority_response_with_dm(
                        &mut game,
                        &mut queue,
                        &mut state,
                        &PriorityResponse::CardCostChoice(selected),
                        &mut dm,
                    )
                    .unwrap();
                    assert!(state.pending_cast.is_none() && state.pending_activation.is_none());
                    assert_eq!(game.stack.len(), 1);
                    let drawn = game.find_object_by_stable_id(drawn_stable).unwrap();
                    assert_eq!(
                        game.object(drawn).unwrap().zone,
                        if offered { Zone::Graveyard } else { Zone::Hand }
                    );
                    if offered && !required {
                        discrepancies.push(format!("actor={actor:?},spell={spell_parent}:the prohibited newly drawn creature was actually discarded and the parent entered the stack"));
                    }
                    cases += 1;
                }
            }
        }
    }
    assert_eq!(cases, 16);
    assert!(
        discrepancies.is_empty(),
        "CR121.8: {} illegal cost-domain/actual-payment observations across16 draw timing/discard filter/native parent fixtures:\n{}",
        discrepancies.len(),
        discrepancies.join("\n")
    );
}

#[test]
fn cr_121_2a_616_1g_draw_instruction_modifiers_precede_individual_draw_replacements() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::events::cards::matchers::WouldDrawCardMatcher;
    use ironsmith::replacement::{ReplacementAction, ReplacementEffect};
    use ironsmith::{Ability, CardId, CardType, Effect, ObjectId, StackEntry, StaticAbility, Zone};
    struct PreferReplacement {
        preferred: ObjectId,
        quantity: Option<ObjectId>,
        individual: ObjectId,
        competing: usize,
    }
    impl DecisionMaker for PreferReplacement {
        fn decide_options(&mut self, _game: &GameState, ctx: &SelectOptionsContext) -> Vec<usize> {
            let legal: Vec<_> = ctx.options.iter().filter(|o| o.legal).collect();
            if self
                .quantity
                .is_some_and(|id| legal.iter().any(|o| o.object_id == Some(id)))
                && legal.iter().any(|o| o.object_id == Some(self.individual))
            {
                self.competing += 1;
            }
            vec![
                legal
                    .iter()
                    .find(|o| o.object_id == Some(self.preferred))
                    .unwrap_or(&legal[0])
                    .index,
            ]
        }
    }
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for count in [2, 3, 5] {
            for empty in [false, true] {
                for quantity_modifier in [false, true] {
                    for prefer_quantity in [false, true] {
                        let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                        game.turn.active_player = actor;
                        let definition = CardDefinitionBuilder::new(
                            CardId::new(),
                            "Individual draw becomes life",
                        )
                        .card_types(vec![CardType::Enchantment])
                        .build();
                        let individual = game.create_object_from_definition(
                            &definition,
                            actor,
                            Zone::Battlefield,
                        );
                        game.effect_store.replacement_effects.add_resolution_effect(
                            ReplacementEffect::with_matcher(
                                individual,
                                actor,
                                WouldDrawCardMatcher::you(),
                                ReplacementAction::Instead(vec![Effect::gain_life(1)]),
                            ),
                        );
                        let quantity=quantity_modifier.then(||{
                            let definition=CardDefinitionBuilder::new(CardId::new(),"Whole draw instruction adds one")
                                .card_types(vec![CardType::Enchantment])
                                .with_ability(Ability::static_ability(StaticAbility::draw_extra_cards_replacement(1,"If you would draw one or more cards, draw that many plus one instead."))).build();
                            game.create_object_from_definition(&definition,actor,Zone::Battlefield)
                        });
                        if !empty {
                            let definition =
                                CardDefinitionBuilder::new(CardId::new(), "Undrawn physical card")
                                    .card_types(vec![CardType::Artifact])
                                    .build();
                            for _ in 0..16 {
                                game.create_object_from_definition(
                                    &definition,
                                    actor,
                                    Zone::Library,
                                );
                            }
                        }
                        let mut dm = PreferReplacement {
                            preferred: if prefer_quantity {
                                quantity.unwrap_or(individual)
                            } else {
                                individual
                            },
                            quantity,
                            individual,
                            competing: 0,
                        };
                        game.stack.push(StackEntry::ability(
                            individual,
                            actor,
                            vec![Effect::draw(count)],
                        ));
                        ironsmith::game_loop::resolve_stack_entry_with(&mut game, &mut dm).unwrap();
                        let actual = game.player(actor).unwrap().life - 20;
                        let required = count + i32::from(quantity_modifier);
                        if actual != required || dm.competing != 0 {
                            discrepancies.push(format!("actor={actor:?},count={count},empty={empty},modifier={quantity_modifier},prefer_quantity={prefer_quantity}:gain{actual},required{required},outer-vs-inner choice prompts{} (required0)",dm.competing));
                        }
                        assert!(game.player(actor).unwrap().hand.is_empty());
                        assert_eq!(
                            game.player(actor).unwrap().library.len(),
                            if empty { 0 } else { 16 }
                        );
                        assert!(
                            !game
                                .player(actor)
                                .unwrap()
                                .attempted_draw_from_empty_library
                        );
                        assert!(game.stack.is_empty());
                        cases += 1;
                    }
                }
            }
        }
    }
    assert_eq!(cases, 48);
    assert!(
        discrepancies.is_empty(),
        "CR121.2a/616.1g: {} wrong quantity/individual replacement results across48 native draw-instruction fixtures:\n{}",
        discrepancies.len(),
        discrepancies.join("\n")
    );
}

#[test]
fn cr_121_2a_draw_quantity_additions_apply_once_per_instruction_before_physical_draws() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::{Ability, CardId, CardType, Effect, StackEntry, StaticAbility, Zone};
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for count in [2, 3, 5] {
            for modifiers in 0..3 {
                let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                let definition =
                    CardDefinitionBuilder::new(CardId::new(), "Native draw instruction source")
                        .card_types(vec![CardType::Artifact])
                        .build();
                let source =
                    game.create_object_from_definition(&definition, actor, Zone::Battlefield);
                for extra in 1..=modifiers {
                    let definition = CardDefinitionBuilder::new(
                        CardId::new(),
                        format!("Draw instruction adds {extra}"),
                    )
                    .card_types(vec![CardType::Enchantment])
                    .with_ability(Ability::static_ability(
                        StaticAbility::draw_extra_cards_replacement(
                            extra,
                            "Draw that many plus extra instead",
                        ),
                    ))
                    .build();
                    game.create_object_from_definition(&definition, actor, Zone::Battlefield);
                }
                for i in 0..16 {
                    let definition = CardDefinitionBuilder::new(
                        CardId::new(),
                        format!("Physical draw-order card {i}"),
                    )
                    .card_types(vec![CardType::Artifact])
                    .build();
                    game.create_object_from_definition(&definition, actor, Zone::Library);
                }
                let required = (count + (modifiers * (modifiers + 1) / 2) as i32) as usize;
                let ordered: Vec<_> = game
                    .player(actor)
                    .unwrap()
                    .library
                    .iter()
                    .rev()
                    .take(required)
                    .map(|id| game.object(*id).unwrap().stable_id)
                    .collect();
                game.stack.push(StackEntry::ability(
                    source,
                    actor,
                    vec![Effect::draw(count)],
                ));
                ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                assert_eq!(game.player(actor).unwrap().library.len(), 16 - required);
                let actual: Vec<_> = game
                    .player(actor)
                    .unwrap()
                    .hand
                    .iter()
                    .map(|id| game.object(*id).unwrap().stable_id)
                    .collect();
                assert_eq!(
                    actual, ordered,
                    "actor={actor:?}, count={count},modifiers={modifiers}: quantity additions happen once and each actual card follows physical top order"
                );
                assert_eq!(game.player(actor).unwrap().life, 20);
                assert!(
                    !game
                        .player(actor)
                        .unwrap()
                        .attempted_draw_from_empty_library
                );
            }
        }
    }
}

fn cr_audit_replaced_draw_followups(reveal: bool) {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::{RevealTaggedEffect, TaggedEffect};
    use ironsmith::events::cards::matchers::WouldDrawCardMatcher;
    use ironsmith::replacement::{ReplacementAction, ReplacementEffect};
    use ironsmith::{CardId, CardType, ChooseSpec, Effect, StackEntry, Zone};
    #[derive(Default)]
    struct PublicViews(Vec<(PlayerId, ironsmith::ids::StableId)>);
    impl DecisionMaker for PublicViews {
        fn view_cards(
            &mut self,
            game: &GameState,
            viewer: PlayerId,
            cards: &[ironsmith::ObjectId],
            ctx: &ironsmith::decisions::context::ViewCardsContext,
        ) {
            if ctx.public {
                for id in cards {
                    self.0.push((viewer, game.object(*id).unwrap().stable_id));
                }
            }
        }
    }
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for count in [1, 3] {
            // 0: direct draws; 1: all draws replaced by draw2; 2: cascading
            // draw2/draw3 replacements; 3: only first draw replaced; 4: no draws.
            for mode in 0..5 {
                let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                let definition = CardDefinitionBuilder::new(
                    CardId::new(),
                    "Draw and follow-up instruction source",
                )
                .card_types(vec![CardType::Artifact])
                .build();
                let source =
                    game.create_object_from_definition(&definition, actor, Zone::Battlefield);
                if mode != 0 {
                    let definition =
                        CardDefinitionBuilder::new(CardId::new(), "Replace original card draw")
                            .card_types(vec![CardType::Enchantment])
                            .build();
                    let replacement_source =
                        game.create_object_from_definition(&definition, actor, Zone::Battlefield);
                    let replacement = ReplacementEffect::with_matcher(
                        replacement_source,
                        actor,
                        WouldDrawCardMatcher::you(),
                        ReplacementAction::Instead(vec![if mode == 4 {
                            Effect::gain_life(1)
                        } else {
                            Effect::draw(2)
                        }]),
                    );
                    if mode == 3 {
                        game.effect_store
                            .replacement_effects
                            .add_one_shot_effect(replacement);
                    } else {
                        game.effect_store
                            .replacement_effects
                            .add_resolution_effect(replacement);
                    }
                    if mode == 2 {
                        let definition =
                            CardDefinitionBuilder::new(CardId::new(), "Further replacement draw")
                                .card_types(vec![CardType::Enchantment])
                                .build();
                        let second = game.create_object_from_definition(
                            &definition,
                            actor,
                            Zone::Battlefield,
                        );
                        game.effect_store.replacement_effects.add_resolution_effect(
                            ReplacementEffect::with_matcher(
                                second,
                                actor,
                                WouldDrawCardMatcher::you(),
                                ReplacementAction::Instead(vec![Effect::draw(3)]),
                            ),
                        );
                    }
                }
                for i in 0..24 {
                    let definition = CardDefinitionBuilder::new(
                        CardId::new(),
                        format!("Follow-up physical card {i}"),
                    )
                    .card_types(vec![CardType::Artifact])
                    .build();
                    game.create_object_from_definition(&definition, actor, Zone::Library);
                }
                let ordered: Vec<_> = game
                    .player(actor)
                    .unwrap()
                    .library
                    .iter()
                    .rev()
                    .map(|id| game.object(*id).unwrap().stable_id)
                    .collect();
                let followup = if reveal {
                    Effect::new(RevealTaggedEffect::new("original_draws"))
                } else {
                    Effect::for_each_tagged(
                        "original_draws",
                        vec![Effect::exile(ChooseSpec::Tagged("__it__".into()))],
                    )
                };
                game.stack.push(StackEntry::ability(
                    source,
                    actor,
                    vec![
                        Effect::new(TaggedEffect::new("original_draws", Effect::draw(count))),
                        followup,
                    ],
                ));
                let mut dm = PublicViews::default();
                ironsmith::game_loop::resolve_stack_entry_with(&mut game, &mut dm).unwrap();
                let total = match mode {
                    0 => count,
                    1 => 2 * count,
                    2 => 6 * count,
                    3 => count + 1,
                    _ => 0,
                } as usize;
                assert_eq!(
                    game.player(actor).unwrap().library.len(),
                    24 - total,
                    "fixture must produce the real expected draw count"
                );
                assert_eq!(
                    game.player(actor).unwrap().life,
                    20 + if mode == 4 { count } else { 0 }
                );
                let mut expected_followups = 0;
                for (index, stable) in ordered.iter().enumerate() {
                    let original = match mode {
                        0 => index < count as usize,
                        3 => index >= 2 && index < total,
                        _ => false,
                    };
                    expected_followups += usize::from(original);
                    let id = game.find_object_by_stable_id(*stable).unwrap();
                    let required = if index >= total {
                        Zone::Library
                    } else if !reveal && original {
                        Zone::Exile
                    } else {
                        Zone::Hand
                    };
                    let actual = game.object(id).unwrap().zone;
                    if actual != required {
                        discrepancies.push(format!("actor={actor:?},count={count},mode={mode},reveal={reveal},physical_top_index={index}:zone{actual:?},required{required:?};original_draw={original}"));
                    }
                    if reveal {
                        for viewer in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                            let seen =
                                dm.0.iter()
                                    .filter(|(p, s)| *p == viewer && s == stable)
                                    .count();
                            let required = usize::from(original);
                            if seen != required {
                                discrepancies.push(format!("actor={actor:?},count={count},mode={mode},physical_top_index={index},viewer={viewer:?}:public views{seen},required{required};original_draw={original}"));
                            }
                        }
                    }
                }
                if reveal && dm.0.len() != 2 * expected_followups {
                    discrepancies.push(format!(
                        "actor={actor:?},count={count},mode={mode}:total public views{},required{}",
                        dm.0.len(),
                        2 * expected_followups
                    ));
                }
                assert!(game.stack.is_empty());
                assert!(
                    !game
                        .player(actor)
                        .unwrap()
                        .attempted_draw_from_empty_library
                );
                cases += 1;
            }
        }
    }
    assert_eq!(cases, 20);
    assert!(
        discrepancies.is_empty(),
        "CR121.6c: {} wrong follow-up subjects across20 direct/replaced/cascaded/partially-replaced draw fixtures (reveal={reveal}):\n{}",
        discrepancies.len(),
        discrepancies.join("\n")
    );
}

#[test]
fn cr_121_6c_exile_after_drawing_does_not_apply_to_replacement_draws() {
    cr_audit_replaced_draw_followups(false);
}

#[test]
fn cr_121_6c_reveal_after_drawing_does_not_apply_to_replacement_draws() {
    cr_audit_replaced_draw_followups(true);
}

#[test]
fn cr_121_7_unreplaced_simultaneous_damage_happens_before_replacement_and_prevention_draws() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::DealDamageEffect;
    use ironsmith::events::damage::matchers::DamageToPlayerMatcher;
    use ironsmith::replacement::{ReplacementAction, ReplacementEffect};
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, Effect, StackEntry, StaticAbility, Zone,
    };
    struct DrawObserver {
        actor: PlayerId,
        required: Vec<i32>,
        observed: Vec<Vec<i32>>,
    }
    impl DecisionMaker for DrawObserver {
        fn view_cards(
            &mut self,
            game: &GameState,
            _viewer: PlayerId,
            cards: &[ironsmith::ObjectId],
            ctx: &ironsmith::decisions::context::ViewCardsContext,
        ) {
            if ctx.public && ctx.subject == self.actor && !cards.is_empty() {
                self.observed.push(
                    (0..3)
                        .map(|i| game.player(PlayerId::from_index(i)).unwrap().life)
                        .collect(),
                );
            }
        }
    }
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for actor_index in 0..3 {
        let actor = PlayerId::from_index(actor_index);
        for prevention in [false, true] {
            for unpreventable in [false, true] {
                for count in [1, 3] {
                    let mut game =
                        GameState::new(vec!["Alice".into(), "Bob".into(), "Carol".into()], 20);
                    let definition = CardDefinitionBuilder::new(
                        CardId::new(),
                        "Partial damage replacement and draw observer",
                    )
                    .card_types(vec![CardType::Enchantment])
                    .with_ability(Ability::static_ability(
                        StaticAbility::reveal_first_card_you_draw_each_turn(false, false),
                    ))
                    .build();
                    let source =
                        game.create_object_from_definition(&definition, actor, Zone::Battlefield);
                    let draw = Effect::draw(count);
                    let action = if prevention {
                        ReplacementAction::PreventDamageThen(vec![draw])
                    } else {
                        ReplacementAction::Instead(vec![draw])
                    };
                    game.effect_store.replacement_effects.add_resolution_effect(
                        ReplacementEffect::with_matcher(
                            source,
                            actor,
                            DamageToPlayerMatcher::to_you(),
                            action,
                        ),
                    );
                    let definition = CardDefinitionBuilder::new(
                        CardId::new(),
                        "Card drawn after original damage",
                    )
                    .card_types(vec![CardType::Artifact])
                    .build();
                    for _ in 0..32 {
                        game.create_object_from_definition(&definition, actor, Zone::Library);
                    }
                    let required: Vec<_> = (0..3)
                        .map(|i| {
                            if i == actor_index && !(prevention && unpreventable) {
                                20
                            } else {
                                17
                            }
                        })
                        .collect();
                    let mut dm = DrawObserver {
                        actor,
                        required,
                        observed: Vec::new(),
                    };
                    let damage =
                        DealDamageEffect::new(3, ChooseSpec::EachPlayer(PlayerFilter::Any))
                            .with_unpreventable(unpreventable);
                    game.stack.push(StackEntry::ability(
                        source,
                        actor,
                        vec![Effect::new(damage)],
                    ));
                    ironsmith::game_loop::resolve_stack_entry_with(&mut game, &mut dm).unwrap();
                    assert_eq!(
                        dm.observed.len(),
                        3,
                        "the first replacement draw is genuinely published to all three players"
                    );
                    for lives in &dm.observed {
                        if lives != &dm.required {
                            discrepancies.push(format!("actor={actor:?},prevention={prevention},unpreventable={unpreventable},count={count}:at draw reveal lives{lives:?},required{:?}",dm.required));
                        }
                    }
                    let actual: Vec<_> = (0..3)
                        .map(|i| game.player(PlayerId::from_index(i)).unwrap().life)
                        .collect();
                    assert_eq!(actual, dm.required);
                    assert_eq!(game.player(actor).unwrap().hand.len(), count as usize);
                    assert_eq!(
                        game.player(actor).unwrap().library.len(),
                        32 - count as usize
                    );
                    assert!(
                        !game
                            .player(actor)
                            .unwrap()
                            .attempted_draw_from_empty_library
                    );
                    for i in 0..3 {
                        if i != actor_index {
                            assert!(
                                game.player(PlayerId::from_index(i))
                                    .unwrap()
                                    .hand
                                    .is_empty()
                            );
                        }
                    }
                    cases += 1;
                }
            }
        }
    }
    assert_eq!(cases, 24);
    assert!(
        discrepancies.is_empty(),
        "CR121.7: {} premature replacement/prevention draw observations across24 native simultaneous damage fixtures:\n{}",
        discrepancies.len(),
        discrepancies.join("\n")
    );
}

#[test]
fn cr_121_7_a_draw_prohibition_destroyed_in_the_original_event_cannot_block_the_replacement_draw() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::events::zones::matchers::WouldChangeZoneMatcher;
    use ironsmith::replacement::{ReplacementAction, ReplacementEffect};
    use ironsmith::{
        Ability, CardId, CardType, Effect, ObjectFilter, PowerToughness, StackEntry, StaticAbility,
        Zone,
    };
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for same_controller in [false, true] {
            for blocker_first in [false, true] {
                for retained in [false, true] {
                    for count in [1, 3] {
                        let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                        let controller = if same_controller {
                            actor
                        } else {
                            PlayerId::from_index(1 - actor.0)
                        };
                        let mut blocker = None;
                        let mut protected = None;
                        for step in 0..2 {
                            if (step == 0) == blocker_first {
                                let mut builder = CardDefinitionBuilder::new(
                                    CardId::new(),
                                    "Original-event draw prohibition",
                                )
                                .card_types(vec![if retained {
                                    CardType::Enchantment
                                } else {
                                    CardType::Creature
                                }])
                                .with_ability(
                                    Ability::static_ability(StaticAbility::restriction(
                                        ironsmith::effect::Restriction::DrawCards(
                                            PlayerFilter::Specific(actor),
                                        ),
                                        "The drawing player can't draw cards".into(),
                                    )),
                                );
                                if !retained {
                                    builder = builder.power_toughness(PowerToughness::fixed(2, 3));
                                }
                                blocker = Some(game.create_object_from_definition(
                                    &builder.build(),
                                    controller,
                                    Zone::Battlefield,
                                ));
                            } else {
                                let definition = CardDefinitionBuilder::new(
                                    CardId::new(),
                                    "Destruction replaced by drawing",
                                )
                                .card_types(vec![CardType::Creature])
                                .power_toughness(PowerToughness::fixed(2, 3))
                                .build();
                                protected = Some(game.create_object_from_definition(
                                    &definition,
                                    actor,
                                    Zone::Battlefield,
                                ));
                            }
                        }
                        let blocker = blocker.unwrap();
                        let protected = protected.unwrap();
                        let blocker_stable = game.object(blocker).unwrap().stable_id;
                        let definition = CardDefinitionBuilder::new(
                            CardId::new(),
                            "Untouched destruction participant",
                        )
                        .card_types(vec![CardType::Creature])
                        .power_toughness(PowerToughness::fixed(2, 3))
                        .build();
                        let other = game.create_object_from_definition(
                            &definition,
                            controller,
                            Zone::Battlefield,
                        );
                        let other_stable = game.object(other).unwrap().stable_id;
                        let definition =
                            CardDefinitionBuilder::new(CardId::new(), "Zone replacement source")
                                .card_types(vec![CardType::Artifact])
                                .build();
                        let source = game.create_object_from_definition(
                            &definition,
                            actor,
                            Zone::Battlefield,
                        );
                        let mut filter = ObjectFilter::creature();
                        filter.specific = Some(protected);
                        game.effect_store.replacement_effects.add_resolution_effect(
                            ReplacementEffect::with_matcher(
                                source,
                                actor,
                                WouldChangeZoneMatcher::new(
                                    filter,
                                    Some(Zone::Battlefield),
                                    Some(Zone::Graveyard),
                                ),
                                ReplacementAction::Instead(vec![Effect::draw(count)]),
                            ),
                        );
                        let definition = CardDefinitionBuilder::new(
                            CardId::new(),
                            "Card waiting for draw prohibition to leave",
                        )
                        .card_types(vec![CardType::Artifact])
                        .build();
                        for _ in 0..8 {
                            game.create_object_from_definition(&definition, actor, Zone::Library);
                        }
                        game.refresh_continuous_state().unwrap();
                        assert!(!game.can_draw(actor));
                        game.stack.push(StackEntry::ability(
                            source,
                            actor,
                            vec![Effect::destroy_all(ObjectFilter::creature())],
                        ));
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        assert_eq!(
                            game.object(protected).unwrap().zone,
                            Zone::Battlefield,
                            "the replaced destruction never happens"
                        );
                        let current = game.find_object_by_stable_id(other_stable).unwrap();
                        assert_eq!(game.object(current).unwrap().zone, Zone::Graveyard);
                        let current = game.find_object_by_stable_id(blocker_stable).unwrap();
                        assert_eq!(
                            game.object(current).unwrap().zone,
                            if retained {
                                Zone::Battlefield
                            } else {
                                Zone::Graveyard
                            }
                        );
                        assert_eq!(game.can_draw(actor), !retained);
                        let actual = game.player(actor).unwrap().hand.len();
                        let required = if retained { 0 } else { count as usize };
                        if actual != required {
                            discrepancies.push(format!("actor={actor:?},same_controller={same_controller},blocker_first={blocker_first},retained={retained},count={count}:actual draw{actual},required{required};original destruction must remove the prohibition before the replacement draw"));
                        }
                        assert_eq!(game.player(actor).unwrap().library.len(), 8 - actual);
                        assert!(
                            !game
                                .player(actor)
                                .unwrap()
                                .attempted_draw_from_empty_library
                        );
                        cases += 1;
                    }
                }
            }
        }
    }
    assert_eq!(cases, 32);
    assert!(
        discrepancies.is_empty(),
        "CR121.7: {} wrong replacement draws across32 original-event prohibition removal/retention fixtures:\n{}",
        discrepancies.len(),
        discrepancies.join("\n")
    );
}

fn cr_audit_as_draw_reveal_decisions(check_timing: bool) {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::{Ability, CardId, CardType, Effect, StackEntry, StaticAbility, Zone};
    struct InspectBeforeReveal {
        actor: PlayerId,
        first: ironsmith::ids::StableId,
        first_name: String,
        accept: bool,
        decisions: Vec<(usize, usize)>,
        public: Vec<(PlayerId, ironsmith::ids::StableId)>,
    }
    impl DecisionMaker for InspectBeforeReveal {
        fn decide_boolean(&mut self, game: &GameState, ctx: &BooleanContext) -> bool {
            assert_eq!(ctx.player, self.actor);
            let first = game
                .find_object_by_stable_id(self.first)
                .expect("owner can identify the first drawn card before deciding");
            assert_eq!(game.object(first).unwrap().zone, Zone::Hand);
            assert_eq!(
                game.current_name(first).as_deref(),
                Some(self.first_name.as_str()),
                "CR121.9: inspect the actual drawn card before deciding"
            );
            assert!(game.player(self.actor).unwrap().hand.contains(&first));
            self.decisions.push((
                game.player(self.actor).unwrap().hand.len(),
                game.player(self.actor).unwrap().library.len(),
            ));
            self.accept
        }
        fn view_cards(
            &mut self,
            game: &GameState,
            viewer: PlayerId,
            cards: &[ironsmith::ObjectId],
            ctx: &ironsmith::decisions::context::ViewCardsContext,
        ) {
            if ctx.public {
                for id in cards {
                    self.public
                        .push((viewer, game.object(*id).unwrap().stable_id));
                }
            }
        }
    }
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for active_actor in [false, true] {
            for accept in [false, true] {
                for count in [0, 1, 3, 5] {
                    let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                    game.turn.active_player = if active_actor {
                        actor
                    } else {
                        PlayerId::from_index(1 - actor.0)
                    };
                    let definition = CardDefinitionBuilder::new(
                        CardId::new(),
                        "Optional reveal as first card is drawn",
                    )
                    .card_types(vec![CardType::Enchantment])
                    .with_ability(Ability::static_ability(
                        StaticAbility::reveal_first_card_you_draw_each_turn(true, false),
                    ))
                    .build();
                    let source =
                        game.create_object_from_definition(&definition, actor, Zone::Battlefield);
                    for i in 0..8 {
                        let definition = CardDefinitionBuilder::new(
                            CardId::new(),
                            format!("Private draw-order card {i}"),
                        )
                        .card_types(vec![CardType::Artifact])
                        .build();
                        game.create_object_from_definition(&definition, actor, Zone::Library);
                    }
                    let ordered: Vec<_> = game
                        .player(actor)
                        .unwrap()
                        .library
                        .iter()
                        .rev()
                        .map(|id| game.object(*id).unwrap().stable_id)
                        .collect();
                    let first = ordered[0];
                    let first_name = game
                        .object(*game.player(actor).unwrap().library.last().unwrap())
                        .unwrap()
                        .name
                        .to_string();
                    let mut dm = InspectBeforeReveal {
                        actor,
                        first,
                        first_name,
                        accept,
                        decisions: Vec::new(),
                        public: Vec::new(),
                    };
                    game.stack.push(StackEntry::ability(
                        source,
                        actor,
                        vec![Effect::draw(count)],
                    ));
                    ironsmith::game_loop::resolve_stack_entry_with(&mut game, &mut dm).unwrap();
                    assert_eq!(dm.decisions.len(), usize::from(count != 0));
                    for (hand, library) in &dm.decisions {
                        if check_timing && (*hand != 1 || *library != 7) {
                            discrepancies.push(format!("actor={actor:?},active_actor={active_actor},accept={accept},count={count}:at first-card as-draw reveal decision,hand{hand}/library{library},required1/7 before any later draw"));
                        }
                    }
                    if count != 0 && accept {
                        assert_eq!(dm.public.len(), 2);
                        for viewer in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                            assert_eq!(
                                dm.public
                                    .iter()
                                    .filter(|(p, s)| *p == viewer && *s == first)
                                    .count(),
                                1
                            );
                        }
                    } else {
                        assert!(dm.public.is_empty(), "declining keeps the card private");
                    }
                    let actual: Vec<_> = game
                        .player(actor)
                        .unwrap()
                        .hand
                        .iter()
                        .map(|id| game.object(*id).unwrap().stable_id)
                        .collect();
                    assert_eq!(actual, &ordered[..count as usize]);
                    assert_eq!(
                        game.player(actor).unwrap().library.len(),
                        8 - count as usize
                    );
                    assert!(
                        !game
                            .player(actor)
                            .unwrap()
                            .attempted_draw_from_empty_library
                    );
                    cases += 1;
                }
            }
        }
    }
    assert_eq!(cases, 32);
    assert!(
        discrepancies.is_empty(),
        "CR121.2: {} delayed as-draw reveal choices across32 native draw/optional-reveal fixtures:\n{}",
        discrepancies.len(),
        discrepancies.join("\n")
    );
}

#[test]
fn cr_121_9_owner_can_inspect_the_drawn_card_before_accepting_or_declining_its_reveal() {
    cr_audit_as_draw_reveal_decisions(false);
}

#[test]
fn cr_121_2_as_draw_reveal_choices_happen_before_drawing_the_next_card() {
    cr_audit_as_draw_reveal_decisions(true);
}

#[test]
fn cr_701_17c_728_1_radiation_counts_milled_nonlands_in_public_replacement_zones_only() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::events::zones::matchers::WouldChangeZoneMatcher;
    use ironsmith::object::CounterType;
    use ironsmith::replacement::{ReplacementAction, ReplacementEffect};
    use ironsmith::triggers::TriggerQueue;
    use ironsmith::{
        CardId, CardType, ObjectFilter, TurnAction, TurnRunner, TurnRunnerState, Zone,
    };
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for destination in [Zone::Graveyard, Zone::Exile, Zone::Command, Zone::Hand] {
            for composition in 0..3 {
                let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                game.turn.active_player = actor;
                let definition = CardDefinitionBuilder::new(
                    CardId::new(),
                    "Mill destination replacement source",
                )
                .card_types(vec![CardType::Artifact])
                .build();
                let source =
                    game.create_object_from_definition(&definition, actor, Zone::Battlefield);
                if destination != Zone::Graveyard {
                    game.effect_store.replacement_effects.add_resolution_effect(
                        ReplacementEffect::with_matcher(
                            source,
                            actor,
                            WouldChangeZoneMatcher::new(
                                ObjectFilter::default(),
                                Some(Zone::Library),
                                Some(Zone::Graveyard),
                            ),
                            ReplacementAction::ChangeDestination(destination),
                        ),
                    );
                }
                for index in 0..5 {
                    let land = composition == 0 || (composition == 2 && index % 2 == 0);
                    let definition =
                        CardDefinitionBuilder::new(CardId::new(), format!("Rad mill card {index}"))
                            .card_types(vec![if land {
                                CardType::Land
                            } else {
                                CardType::Artifact
                            }])
                            .build();
                    game.create_object_from_definition(&definition, actor, Zone::Library);
                }
                let top: Vec<_> = game
                    .player(actor)
                    .unwrap()
                    .library
                    .iter()
                    .rev()
                    .take(3)
                    .map(|id| {
                        (
                            game.object(*id).unwrap().stable_id,
                            game.object(*id)
                                .unwrap()
                                .card_types
                                .contains(&CardType::Land),
                        )
                    })
                    .collect();
                game.add_player_counters_with_source(
                    actor,
                    CounterType::Rad,
                    3,
                    Some(source),
                    Some(actor),
                )
                .unwrap();
                let mut queue = TriggerQueue::new();
                let mut runner = TurnRunner::from_state_for_sync(TurnRunnerState::FirstMain);
                let mut priority = false;
                for _ in 0..10 {
                    match runner.advance(&mut game, &mut queue).unwrap() {
                        TurnAction::Continue => {}
                        TurnAction::RunPriority => {
                            priority = true;
                            break;
                        }
                        other => panic!("unexpected first-main turn action {other:?}"),
                    }
                }
                assert!(priority);
                assert_eq!(queue.entries.len(), 1);
                assert_eq!(queue.entries[0].controller, actor);
                assert!(queue.entries[0].source_snapshot.is_none());
                assert!(game.object(queue.entries[0].source).is_none());
                ironsmith::game_loop::put_triggers_on_stack(&mut game, &mut queue).unwrap();
                assert_eq!(game.stack.len(), 1);
                ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                assert_eq!(game.player(actor).unwrap().library.len(), 2);
                for (stable, _) in &top {
                    let id = game.find_object_by_stable_id(*stable).unwrap();
                    assert_eq!(
                        game.object(id).unwrap().zone,
                        destination,
                        "actual original library cards use the replacement destination"
                    );
                }
                let nonlands = if destination.is_public() {
                    top.iter().filter(|(_, land)| !*land).count()
                } else {
                    0
                };
                let actual = (
                    game.player(actor).unwrap().life,
                    game.player(actor).unwrap().counter_count(CounterType::Rad),
                );
                let required = (20 - nonlands as i32, 3 - nonlands as u32);
                if actual != required {
                    discrepancies.push(format!("actor={actor:?},destination={destination:?},composition={composition}:life/rad{actual:?},required{required:?};nonland cards in public destination remain milled-this-way subjects; hidden cards do not"));
                }
                assert!(game.stack.is_empty());
                cases += 1;
            }
        }
    }
    assert_eq!(cases, 24);
    assert!(
        discrepancies.is_empty(),
        "CR701.17c/728.1: {} wrong public/hidden milled-card lookups across24 native rad-trigger fixtures:\n{}",
        discrepancies.len(),
        discrepancies.join("\n")
    );
}

fn cr_audit_radiation_replacement_mill_subjects(movement_replacement: bool) {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::MillEffect;
    use ironsmith::events::zones::matchers::WouldChangeZoneMatcher;
    use ironsmith::object::CounterType;
    use ironsmith::replacement::{ReplacementAction, ReplacementEffect};
    use ironsmith::triggers::TriggerQueue;
    use ironsmith::{
        CardId, CardType, Effect, ObjectFilter, TurnAction, TurnRunner, TurnRunnerState, Zone,
    };
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for amount in [1i32, 2, 3] {
            for composition in 0..3 {
                let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                game.turn.active_player = actor;
                let definition = CardDefinitionBuilder::new(
                    CardId::new(),
                    "One milling move becomes several milled cards",
                )
                .card_types(vec![CardType::Artifact])
                .build();
                let source =
                    game.create_object_from_definition(&definition, actor, Zone::Battlefield);
                if amount > 1 {
                    if movement_replacement {
                        game.effect_store.replacement_effects.add_one_shot_effect(
                            ReplacementEffect::with_matcher(
                                source,
                                actor,
                                WouldChangeZoneMatcher::new(
                                    ObjectFilter::default(),
                                    Some(Zone::Library),
                                    Some(Zone::Graveyard),
                                ),
                                ReplacementAction::Instead(vec![Effect::new(MillEffect::new(
                                    amount,
                                    PlayerFilter::Specific(actor),
                                ))]),
                            ),
                        );
                    } else {
                        let modifier = ironsmith::static_abilities::EventAmountReplacement::new(
                            ironsmith_core::AmountEventSpec::KeywordAction {
                                action: ironsmith_core::KeywordActionKind::Mill,
                                performer: PlayerFilter::Specific(actor),
                            },
                            ironsmith_core::AmountModifierSpec::Multiply(amount as u32),
                            false,
                            "Multiply the original mill amount",
                        );
                        let definition = CardDefinitionBuilder::new(
                            CardId::new(),
                            "Mill quantity modifier control",
                        )
                        .card_types(vec![CardType::Enchantment])
                        .with_ability(ironsmith::Ability::static_ability(
                            ironsmith::StaticAbility::new(modifier),
                        ))
                        .build();
                        game.create_object_from_definition(&definition, actor, Zone::Battlefield);
                    }
                }
                for index in 0..5 {
                    let land = composition == 0 || (composition == 2 && index % 2 == 0);
                    let definition = CardDefinitionBuilder::new(
                        CardId::new(),
                        format!("Replacement-milled physical card {index}"),
                    )
                    .card_types(vec![if land {
                        CardType::Land
                    } else {
                        CardType::Artifact
                    }])
                    .build();
                    game.create_object_from_definition(&definition, actor, Zone::Library);
                }
                let top: Vec<_> = game
                    .player(actor)
                    .unwrap()
                    .library
                    .iter()
                    .rev()
                    .take(amount as usize)
                    .map(|id| {
                        (
                            game.object(*id).unwrap().stable_id,
                            game.object(*id)
                                .unwrap()
                                .card_types
                                .contains(&CardType::Land),
                        )
                    })
                    .collect();
                game.add_player_counters_with_source(
                    actor,
                    CounterType::Rad,
                    1,
                    Some(source),
                    Some(actor),
                )
                .unwrap();
                let mut queue = TriggerQueue::new();
                let mut runner = TurnRunner::from_state_for_sync(TurnRunnerState::FirstMain);
                let mut priority = false;
                for _ in 0..10 {
                    match runner.advance(&mut game, &mut queue).unwrap() {
                        TurnAction::Continue => {}
                        TurnAction::RunPriority => {
                            priority = true;
                            break;
                        }
                        other => panic!("unexpected main-phase action {other:?}"),
                    }
                }
                assert!(priority);
                assert_eq!(queue.entries.len(), 1);
                assert!(queue.entries[0].source_snapshot.is_none());
                ironsmith::game_loop::put_triggers_on_stack(&mut game, &mut queue).unwrap();
                ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                assert_eq!(
                    game.player(actor).unwrap().library.len(),
                    5 - amount as usize,
                    "real replacement mills the requested physical cards"
                );
                assert_eq!(game.player(actor).unwrap().graveyard.len(), amount as usize);
                for (stable, _) in &top {
                    let id = game.find_object_by_stable_id(*stable).unwrap();
                    assert_eq!(game.object(id).unwrap().zone, Zone::Graveyard);
                }
                let nonlands = top.iter().filter(|(_, land)| !*land).count();
                let actual = (
                    game.player(actor).unwrap().life,
                    game.player(actor).unwrap().counter_count(CounterType::Rad),
                );
                let required = (20 - nonlands as i32, 1u32.saturating_sub(nonlands as u32));
                if actual != required {
                    discrepancies.push(format!("actor={actor:?},amount={amount},composition={composition}:life/rad{actual:?},required{required:?};all{nonlands} replacement-milled nonlands supply the original radiation follow-up even when only one rad counter existed"));
                }
                cases += 1;
            }
        }
    }
    assert_eq!(cases, 18);
    assert!(
        discrepancies.is_empty(),
        "CR701.17d/728.1: {} wrong milled-card follow-ups across18 native rad/mill quantity replacement fixtures:\n{}",
        discrepancies.len(),
        discrepancies.join("\n")
    );
}

#[test]
fn cr_701_17d_728_1_radiation_counts_every_card_milled_by_a_replacement() {
    cr_audit_radiation_replacement_mill_subjects(true);
}

#[test]
fn cr_701_17d_728_1_radiation_counts_every_card_when_the_original_mill_quantity_is_modified() {
    cr_audit_radiation_replacement_mill_subjects(false);
}

#[test]
fn cr_701_17b_optional_milling_checks_the_actual_millers_library_even_when_another_player_chooses()
{
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::{MayEffect, MillEffect};
    use ironsmith::{CardId, CardType, Effect, StackEntry, Zone};
    struct ChooseMill {
        chooser: PlayerId,
        accept: bool,
        offers: Vec<bool>,
    }
    impl DecisionMaker for ChooseMill {
        fn decide_boolean(&mut self, _game: &GameState, ctx: &BooleanContext) -> bool {
            assert_eq!(ctx.player, self.chooser);
            self.offers.push(ctx.can_accept);
            self.accept && ctx.can_accept
        }
    }
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for chooser in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        let opponent = PlayerId::from_index(1 - chooser.0);
        for (own, other) in [(5, 0), (0, 5), (5, 5), (0, 0), (5, 1), (1, 5)] {
            for count in [1, 3] {
                for filter_kind in 0..3 {
                    for accept in [false, true] {
                        let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                        let definition =
                            CardDefinitionBuilder::new(CardId::new(), "Optional milling source")
                                .card_types(vec![CardType::Artifact])
                                .build();
                        let source = game.create_object_from_definition(
                            &definition,
                            chooser,
                            Zone::Battlefield,
                        );
                        for (player, available) in [(chooser, own), (opponent, other)] {
                            for index in 0..available {
                                let definition = CardDefinitionBuilder::new(
                                    CardId::new(),
                                    format!("Mill choice physical card {player:?}/{index}"),
                                )
                                .card_types(vec![CardType::Artifact])
                                .build();
                                game.create_object_from_definition(
                                    &definition,
                                    player,
                                    Zone::Library,
                                );
                            }
                        }
                        let (player, filter, available) = match filter_kind {
                            0 => (chooser, PlayerFilter::You, own),
                            1 => (opponent, PlayerFilter::Specific(opponent), other),
                            _ => (opponent, PlayerFilter::Opponent, other),
                        };
                        let legal = available >= count;
                        let expected_milled = if accept && legal { count } else { 0 };
                        let mut dm = ChooseMill {
                            chooser,
                            accept,
                            offers: Vec::new(),
                        };
                        game.stack.push(StackEntry::ability(
                            source,
                            chooser,
                            vec![Effect::new(MayEffect::new_for_player(
                                vec![
                                    Effect::new(MillEffect::new(count, filter)),
                                    Effect::gain_life(1),
                                ],
                                PlayerFilter::Specific(chooser),
                            ))],
                        ));
                        ironsmith::game_loop::resolve_stack_entry_with(&mut game, &mut dm).unwrap();
                        assert_eq!(dm.offers.len(), 1);
                        if dm.offers[0] != legal {
                            discrepancies.push(format!("chooser={chooser:?},own={own},other={other},count={count},filter={filter_kind},accept={accept}:offer{},required{legal};miller={player:?}",dm.offers[0]));
                        }
                        let remaining = game.player(player).unwrap().library.len();
                        let milled = game.player(player).unwrap().graveyard.len();
                        let life = game.player(chooser).unwrap().life;
                        let expected = (
                            available as usize - expected_milled as usize,
                            expected_milled as usize,
                            20 + i32::from(accept && legal),
                        );
                        if (remaining, milled, life) != expected {
                            discrepancies.push(format!("chooser={chooser:?},own={own},other={other},count={count},filter={filter_kind},accept={accept}:actual(remaining,milled,life)={:?},required{expected:?}",(remaining,milled,life)));
                        }
                        let untouched = if player == chooser { opponent } else { chooser };
                        let original = if untouched == chooser { own } else { other };
                        assert_eq!(
                            game.player(untouched).unwrap().library.len(),
                            original as usize
                        );
                        assert!(game.player(untouched).unwrap().graveyard.is_empty());
                        assert!(
                            !game
                                .player(player)
                                .unwrap()
                                .attempted_draw_from_empty_library
                        );
                        cases += 1;
                    }
                }
            }
        }
    }
    assert_eq!(cases, 144);
    assert!(
        discrepancies.is_empty(),
        "CR701.17b: {} illegal optional mill offer/execution results across144 chooser/miller/library/filter fixtures:\n{}",
        discrepancies.len(),
        discrepancies.join("\n")
    );
}

#[test]
fn cr_701_17a_b_mandatory_milling_uses_the_top_cards_and_caps_even_unsigned_maximum_requests() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::MillEffect;
    use ironsmith::{CardId, CardType, Effect, StackEntry, Zone};
    let mut cases = 0;
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for available in [0, 1, 2, 5] {
            for count in [0u32, 1, 3, u32::MAX] {
                for explicit in [false, true] {
                    let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                    let definition =
                        CardDefinitionBuilder::new(CardId::new(), "Mandatory mill instruction")
                            .card_types(vec![CardType::Artifact])
                            .build();
                    let source =
                        game.create_object_from_definition(&definition, actor, Zone::Battlefield);
                    for i in 0..available {
                        let definition = CardDefinitionBuilder::new(
                            CardId::new(),
                            format!("Mandatory top-card marker {i}"),
                        )
                        .card_types(vec![CardType::Artifact])
                        .build();
                        game.create_object_from_definition(&definition, actor, Zone::Library);
                    }
                    let required = (count as usize).min(available);
                    let original: Vec<_> = game
                        .player(actor)
                        .unwrap()
                        .library
                        .iter()
                        .rev()
                        .map(|id| game.object(*id).unwrap().stable_id)
                        .collect();
                    game.stack.push(StackEntry::ability(
                        source,
                        actor,
                        vec![Effect::new(MillEffect::new(
                            count,
                            if explicit {
                                PlayerFilter::Specific(actor)
                            } else {
                                PlayerFilter::You
                            },
                        ))],
                    ));
                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                    assert_eq!(
                        game.player(actor).unwrap().library.len(),
                        available - required
                    );
                    assert_eq!(game.player(actor).unwrap().graveyard.len(), required);
                    for (index, stable) in original.iter().enumerate() {
                        let id = game.find_object_by_stable_id(*stable).unwrap();
                        assert_eq!(
                            game.object(id).unwrap().zone,
                            if index < required {
                                Zone::Graveyard
                            } else {
                                Zone::Library
                            }
                        );
                    }
                    assert!(
                        !game
                            .player(actor)
                            .unwrap()
                            .attempted_draw_from_empty_library
                    );
                    assert_eq!(game.player(actor).unwrap().life, 20);
                    cases += 1;
                }
            }
        }
    }
    assert_eq!(cases, 64);
}

#[test]
fn cr_701_17b_a_milling_activation_cost_cannot_be_paid_with_a_partial_library() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::costs::Cost;
    use ironsmith::effects::MillEffect;
    use ironsmith::{Ability, CardId, CardType, Effect, LegalAction, Phase, TotalCost, Zone};
    let mut cases = 0;
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for available in [0, 1, 2, 5] {
            for count in [0u32, 1, 3, u32::MAX] {
                let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                game.turn.active_player = actor;
                game.turn.priority_player = Some(actor);
                game.turn.phase = Phase::FirstMain;
                let definition =
                    CardDefinitionBuilder::new(CardId::new(), "Milling payment source")
                        .card_types(vec![CardType::Artifact])
                        .with_ability(Ability::activated(
                            TotalCost::from_cost(Cost::effect(MillEffect::new(
                                count,
                                PlayerFilter::You,
                            ))),
                            vec![Effect::gain_life(1)],
                        ))
                        .build();
                let source =
                    game.create_object_from_definition(&definition, actor, Zone::Battlefield);
                for i in 0..available {
                    let definition =
                        CardDefinitionBuilder::new(CardId::new(), format!("Cost mill marker {i}"))
                            .card_types(vec![CardType::Artifact])
                            .build();
                    game.create_object_from_definition(&definition, actor, Zone::Library);
                }
                let legal = (available as u64) >= u64::from(count);
                let action = LegalAction::ActivateAbility {
                    source,
                    ability_index: 0,
                };
                assert_eq!(
                    ironsmith::compute_legal_actions(&game, actor)
                        .unwrap()
                        .contains(&action),
                    legal,
                    "actor={actor:?},available={available},count={count}:activation affordability needs the full mill cost"
                );
                let result = cr_audit_complete_priority_action(&mut game, actor, action);
                if legal {
                    result.unwrap();
                    assert_eq!(
                        game.stack.len(),
                        1,
                        "actual complete payment activates the ability"
                    );
                    assert_eq!(
                        game.player(actor).unwrap().library.len(),
                        available - count as usize
                    );
                    assert_eq!(game.player(actor).unwrap().graveyard.len(), count as usize);
                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                    assert_eq!(game.player(actor).unwrap().life, 21);
                } else {
                    // A forged action may be rejected or canceled, but cannot
                    // pay by milling only the available portion.
                    assert!(
                        game.stack.is_empty(),
                        "unpayable native attempt must not activate: {result:?}"
                    );
                    assert_eq!(game.player(actor).unwrap().library.len(), available);
                    assert!(game.player(actor).unwrap().graveyard.is_empty());
                    assert_eq!(game.player(actor).unwrap().life, 20);
                }
                assert!(
                    !game
                        .player(actor)
                        .unwrap()
                        .attempted_draw_from_empty_library
                );
                cases += 1;
            }
        }
    }
    assert_eq!(cases, 32);
}

#[test]
fn cr_118_11_123_3c_a_modified_ticket_payment_still_places_the_paid_sticker() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::PutStickerEffect;
    use ironsmith::events::KeywordActionKind;
    use ironsmith::events::counters::matchers::WouldRemovePlayerCountersMatcher;
    use ironsmith::replacement::{EventModification, ReplacementAction, ReplacementEffect};
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, CounterType, Effect, PowerToughness, StackEntry,
        StaticAbility, Zone,
    };
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for action in [
            KeywordActionKind::AbilitySticker,
            KeywordActionKind::PowerToughnessSticker,
        ] {
            for balance in [3u32, 4] {
                // Gain1/Gain3 are both valid replacements for the entire
                // payment action; their unrelated result count cannot decide
                // whether a two-ticket cost was paid.
                for mode in 0..5 {
                    let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                    let definition =
                        CardDefinitionBuilder::new(CardId::new(), "Paid sticker recipient")
                            .card_types(vec![CardType::Creature])
                            .power_toughness(PowerToughness::fixed(3, 4))
                            .build();
                    let target =
                        game.create_object_from_definition(&definition, actor, Zone::Battlefield);
                    let definition = CardDefinitionBuilder::new(
                        CardId::new(),
                        "Ticket payment replacement source",
                    )
                    .card_types(vec![CardType::Artifact])
                    .build();
                    let source =
                        game.create_object_from_definition(&definition, actor, Zone::Battlefield);
                    let ticket = CounterType::Named("ticket".into());
                    game.add_player_counters_with_source(
                        actor,
                        ticket,
                        balance,
                        Some(source),
                        Some(actor),
                    )
                    .unwrap();
                    if action == KeywordActionKind::AbilitySticker {
                        game.add_accessible_ability_sticker(
                            actor,
                            2,
                            vec![Ability::static_ability(StaticAbility::flying())],
                            "Flying",
                        );
                    } else {
                        game.add_accessible_pt_sticker(actor, 2, 6, 7);
                    }
                    let replacement = match mode {
                        1 => Some(ReplacementAction::Instead(vec![Effect::gain_life(1)])),
                        2 => Some(ReplacementAction::Instead(vec![Effect::gain_life(3)])),
                        3 => Some(ReplacementAction::Modify(EventModification::Subtract(1))),
                        4 => Some(ReplacementAction::Modify(EventModification::Add(1))),
                        _ => None,
                    };
                    if let Some(replacement) = replacement {
                        game.effect_store.replacement_effects.add_resolution_effect(
                            ReplacementEffect::with_matcher(
                                source,
                                actor,
                                WouldRemovePlayerCountersMatcher::new(
                                    PlayerFilter::Specific(actor),
                                    Some(ticket),
                                ),
                                replacement,
                            ),
                        );
                    }
                    game.stack.push(StackEntry::ability(
                        source,
                        actor,
                        vec![Effect::new(PutStickerEffect::new(
                            ChooseSpec::SpecificObject(target),
                            action,
                        ))],
                    ));
                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                    let spent = match mode {
                        1 | 2 => 0,
                        3 => 1,
                        4 => 3,
                        _ => 2,
                    };
                    assert_eq!(
                        game.player(actor).unwrap().counter_count(ticket),
                        balance - spent,
                        "the actual replacement payment action is performed"
                    );
                    assert_eq!(
                        game.player(actor).unwrap().life,
                        20 + match mode {
                            1 => 1,
                            2 => 3,
                            _ => 0,
                        }
                    );
                    let placed = game.sticker_count_on_object(target, action, None);
                    let visible = if action == KeywordActionKind::AbilitySticker {
                        game.object_has_ability(target, &StaticAbility::flying())
                    } else {
                        (game.current_power(target), game.current_toughness(target))
                            == (Some(6), Some(7))
                    };
                    if placed != 1 || !visible {
                        discrepancies.push(format!("actor={actor:?},action={action:?},balance={balance},mode={mode}:placed{placed},effect_visible{visible};required one effective paid sticker despite modified action"));
                    }
                    cases += 1;
                }
            }
        }
    }
    assert_eq!(cases, 40);
    assert!(
        discrepancies.is_empty(),
        "CR118.11/123.3c: {} missing paid stickers across40 original/replaced/reduced/increased ticket-payment fixtures:\n{}",
        discrepancies.len(),
        discrepancies.join("\n")
    );
}

#[test]
fn cr_123_3c_sticker_ticket_waivers_do_not_waive_maximum_cost_caps() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::PutStickerEffect;
    use ironsmith::events::KeywordActionKind;
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, CounterType, Effect, PowerToughness, StackEntry,
        StaticAbility, Zone,
    };
    let mut cases = 0;
    for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for action in [
            KeywordActionKind::AbilitySticker,
            KeywordActionKind::PowerToughnessSticker,
        ] {
            for balance in [0u32, 1, 2, 3] {
                for cap in [0i32, 1, 2, 3] {
                    for waiver in [false, true] {
                        let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                        let definition =
                            CardDefinitionBuilder::new(CardId::new(), "Capped sticker recipient")
                                .card_types(vec![CardType::Creature])
                                .power_toughness(PowerToughness::fixed(3, 4))
                                .build();
                        let target = game.create_object_from_definition(
                            &definition,
                            actor,
                            Zone::Battlefield,
                        );
                        let ticket = CounterType::Named("ticket".into());
                        game.add_player_counters_with_source(
                            actor,
                            ticket,
                            balance,
                            Some(target),
                            Some(actor),
                        )
                        .unwrap();
                        if action == KeywordActionKind::AbilitySticker {
                            game.add_accessible_ability_sticker(
                                actor,
                                2,
                                vec![Ability::static_ability(StaticAbility::flying())],
                                "Flying",
                            );
                        } else {
                            game.add_accessible_pt_sticker(actor, 2, 6, 7);
                        }
                        game.stack.push(StackEntry::ability(
                            target,
                            actor,
                            vec![Effect::new(
                                PutStickerEffect::new(ChooseSpec::SpecificObject(target), action)
                                    .with_ticket_terms(Some(cap.into()), waiver),
                            )],
                        ));
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        let placed = cap >= 2 && (waiver || balance >= 2);
                        assert_eq!(
                            game.sticker_count_on_object(target, action, None),
                            u32::from(placed)
                        );
                        assert_eq!(
                            game.player(actor).unwrap().counter_count(ticket),
                            balance - if placed && !waiver { 2 } else { 0 }
                        );
                        if action == KeywordActionKind::AbilitySticker {
                            assert_eq!(
                                game.object_has_ability(target, &StaticAbility::flying()),
                                placed
                            );
                        } else {
                            assert_eq!(
                                (game.current_power(target), game.current_toughness(target)),
                                if placed {
                                    (Some(6), Some(7))
                                } else {
                                    (Some(3), Some(4))
                                }
                            );
                        }
                        cases += 1;
                    }
                }
            }
        }
    }
    assert_eq!(cases, 128);
}

#[test]
fn cr_123_6a_b_name_stickers_preserve_existing_words_and_ignore_suggested_blanks() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::continuous::{EffectTarget, Modification};
    use ironsmith::effects::{ApplyContinuousEffect, PutStickerEffect};
    use ironsmith::events::KeywordActionKind;
    use ironsmith::{
        CardId, CardType, ChooseSpec, Effect, ObjectFilter, StackEntry, Until, Value, Zone,
    };
    struct PlaceName {
        owner: PlayerId,
        controller: PlayerId,
        at_end: bool,
        words: usize,
        decisions: usize,
    }
    impl DecisionMaker for PlaceName {
        fn decide_options(&mut self, _game: &GameState, ctx: &SelectOptionsContext) -> Vec<usize> {
            self.decisions += 1;
            if ctx.description == "Choose a name sticker" {
                assert_eq!(ctx.player, self.owner);
                vec![ctx.options.iter().find(|o| o.legal).unwrap().index]
            } else {
                assert_eq!(ctx.description, "Choose the name sticker's position");
                assert_eq!(ctx.player, self.controller);
                assert_eq!(
                    ctx.options.len(),
                    self.words + 1,
                    "blank lines are not positions for extra words"
                );
                vec![if self.at_end {
                    ctx.options.iter().rev().find(|o| o.legal).unwrap().index
                } else {
                    ctx.options.iter().find(|o| o.legal).unwrap().index
                }]
            }
        }
    }
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for owner in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for other_controller in [false, true] {
            for (original, normalized, base_words) in [
                ("Wolf in ________ Clothing", "Wolf in Clothing", 3usize),
                ("________ Goblin", "Goblin", 1),
                ("________ Bird Gets the Worm", "Bird Gets the Worm", 4),
                ("Bear Cub", "Bear Cub", 2),
                ("Hyphen-name, Last", "Hyphen-name, Last", 2),
                ("", "", 0),
            ] {
                for at_end in [false, true] {
                    for stickers in [1, 2] {
                        let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                        let controller = if other_controller {
                            PlayerId::from_index(1 - owner.0)
                        } else {
                            owner
                        };
                        let definition = CardDefinitionBuilder::new(CardId::new(), original)
                            .card_types(vec![CardType::Artifact])
                            .build();
                        let target = game.create_object_from_definition(
                            &definition,
                            owner,
                            Zone::Battlefield,
                        );
                        let definition = CardDefinitionBuilder::new(
                            CardId::new(),
                            "Name-preserving sticker instruction",
                        )
                        .card_types(vec![CardType::Artifact])
                        .build();
                        let source = game.create_object_from_definition(
                            &definition,
                            owner,
                            Zone::Battlefield,
                        );
                        if other_controller {
                            ApplyContinuousEffect::new(
                                EffectTarget::Specific(target),
                                Modification::ChangeController(controller),
                                Until::EndOfTurn,
                            )
                            .execute(&mut game, &mut EffectContext::new_default(source, owner))
                            .unwrap();
                        }
                        assert_eq!(game.current_controller(target), Some(controller));
                        assert_eq!(game.current_name(target).as_deref(), Some(original));
                        game.add_accessible_name_sticker(owner, "Bright");
                        game.add_accessible_name_sticker(owner, "Calm");
                        let mut dm = PlaceName {
                            owner,
                            controller,
                            at_end,
                            words: base_words,
                            decisions: 0,
                        };
                        let mut required = normalized.to_string();
                        for step in 0..stickers {
                            dm.words = base_words + step;
                            game.stack.push(StackEntry::ability(
                                source,
                                owner,
                                vec![Effect::new(PutStickerEffect::new(
                                    ChooseSpec::SpecificObject(target),
                                    KeywordActionKind::NameSticker,
                                ))],
                            ));
                            ironsmith::game_loop::resolve_stack_entry_with(&mut game, &mut dm)
                                .unwrap();
                            let word = if step == 0 { "Bright" } else { "Calm" };
                            required = if required.is_empty() {
                                word.to_string()
                            } else if at_end {
                                format!("{required} {word}")
                            } else {
                                format!("{word} {required}")
                            };
                            let actual = game.current_name(target).unwrap();
                            let actual_words = actual
                                .split_whitespace()
                                .filter(|word| !word.chars().all(|ch| ch == '_'))
                                .collect::<Vec<_>>()
                                .join(" ");
                            if actual_words != required {
                                discrepancies.push(format!("owner={owner:?},other_controller={other_controller},original={original:?},at_end={at_end},step={step}:name{actual:?},required{required:?};insertion must preserve existing words; suggested blank lines are not words"));
                            }
                            let mut filter = ObjectFilter::default();
                            filter.name = Some(required.clone());
                            let before = game.player(owner).unwrap().life;
                            game.stack.push(StackEntry::ability(
                                source,
                                owner,
                                vec![Effect::gain_life(Value::Count(filter))],
                            ));
                            ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                            let gain = game.player(owner).unwrap().life - before;
                            if gain != 1 {
                                discrepancies.push(format!("owner={owner:?},other_controller={other_controller},original={original:?},at_end={at_end},step={step}:resolved expected-name count gain{gain},required1"));
                            }
                            assert_eq!(
                                game.sticker_count_on_object(
                                    target,
                                    KeywordActionKind::NameSticker,
                                    None
                                ),
                                (step + 1) as u32
                            );
                        }
                        assert_eq!(dm.decisions, stickers * 2);
                        cases += 1;
                    }
                }
            }
        }
    }
    assert_eq!(cases, 96);
    assert!(
        discrepancies.is_empty(),
        "CR123.6/123.6a/123.6b: {} name-text andactual exact-name query mismatches across96 blank-line/ordinary-name placement fixtures:\n{}",
        discrepancies.len(),
        discrepancies.join("\n")
    );
}

#[test]
fn cr_123_6b_two_name_stickers_allow_every_word_position_and_use_the_current_controller() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::continuous::{EffectTarget, Modification};
    use ironsmith::effects::{ApplyContinuousEffect, PutStickerEffect};
    use ironsmith::events::KeywordActionKind;
    use ironsmith::{CardId, CardType, ChooseSpec, Effect, StackEntry, Until, Zone};
    struct Positions {
        owner: PlayerId,
        controller: PlayerId,
        positions: [usize; 2],
        next: usize,
    }
    impl DecisionMaker for Positions {
        fn decide_options(&mut self, _game: &GameState, ctx: &SelectOptionsContext) -> Vec<usize> {
            if ctx.description == "Choose a name sticker" {
                assert_eq!(ctx.player, self.owner);
                vec![ctx.options.iter().find(|o| o.legal).unwrap().index]
            } else {
                assert_eq!(ctx.player, self.controller);
                assert_eq!(ctx.description, "Choose the name sticker's position");
                assert_eq!(ctx.options.len(), 4 + self.next);
                let chosen = self.positions[self.next];
                self.next += 1;
                assert!(ctx.options.iter().any(|o| o.legal && o.index == chosen));
                vec![chosen]
            }
        }
    }
    let rows = [
        (
            "Bright Wolf in Clothing",
            [
                "Calm Bright Wolf in Clothing",
                "Bright Calm Wolf in Clothing",
                "Bright Wolf Calm in Clothing",
                "Bright Wolf in Calm Clothing",
                "Bright Wolf in Clothing Calm",
            ],
        ),
        (
            "Wolf Bright in Clothing",
            [
                "Calm Wolf Bright in Clothing",
                "Wolf Calm Bright in Clothing",
                "Wolf Bright Calm in Clothing",
                "Wolf Bright in Calm Clothing",
                "Wolf Bright in Clothing Calm",
            ],
        ),
        (
            "Wolf in Bright Clothing",
            [
                "Calm Wolf in Bright Clothing",
                "Wolf Calm in Bright Clothing",
                "Wolf in Calm Bright Clothing",
                "Wolf in Bright Calm Clothing",
                "Wolf in Bright Clothing Calm",
            ],
        ),
        (
            "Wolf in Clothing Bright",
            [
                "Calm Wolf in Clothing Bright",
                "Wolf Calm in Clothing Bright",
                "Wolf in Calm Clothing Bright",
                "Wolf in Clothing Calm Bright",
                "Wolf in Clothing Bright Calm",
            ],
        ),
    ];
    let mut cases = 0;
    for owner in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for other_controller in [false, true] {
            let controller = if other_controller {
                PlayerId::from_index(1 - owner.0)
            } else {
                owner
            };
            for (first, (first_name, second_names)) in rows.iter().enumerate() {
                for (second, second_name) in second_names.iter().enumerate() {
                    let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                    let definition =
                        CardDefinitionBuilder::new(CardId::new(), "Wolf in ________ Clothing")
                            .card_types(vec![CardType::Artifact])
                            .build();
                    let target =
                        game.create_object_from_definition(&definition, owner, Zone::Battlefield);
                    let source_definition = CardDefinitionBuilder::new(
                        CardId::new(),
                        "Two-position sticker effect source",
                    )
                    .card_types(vec![CardType::Artifact])
                    .build();
                    let source = game.create_object_from_definition(
                        &source_definition,
                        owner,
                        Zone::Battlefield,
                    );
                    if other_controller {
                        ApplyContinuousEffect::new(
                            EffectTarget::Specific(target),
                            Modification::ChangeController(controller),
                            Until::EndOfTurn,
                        )
                        .execute(&mut game, &mut EffectContext::new_default(source, owner))
                        .unwrap();
                    }
                    game.add_accessible_name_sticker(owner, "Bright");
                    game.add_accessible_name_sticker(owner, "Calm");
                    let mut dm = Positions {
                        owner,
                        controller,
                        positions: [first, second],
                        next: 0,
                    };
                    for expected in [*first_name, *second_name] {
                        game.stack.push(StackEntry::ability(
                            source,
                            owner,
                            vec![Effect::new(PutStickerEffect::new(
                                ChooseSpec::SpecificObject(target),
                                KeywordActionKind::NameSticker,
                            ))],
                        ));
                        ironsmith::game_loop::resolve_stack_entry_with(&mut game, &mut dm).unwrap();
                        let actual = game.current_name(target).unwrap();
                        let words = actual
                            .split_whitespace()
                            .filter(|word| !word.chars().all(|ch| ch == '_'))
                            .collect::<Vec<_>>()
                            .join(" ");
                        assert_eq!(
                            words, expected,
                            "owner={owner:?},other_controller={other_controller},first={first},second={second}"
                        );
                    }
                    assert_eq!(dm.next, 2);
                    assert_eq!(
                        game.sticker_count_on_object(target, KeywordActionKind::NameSticker, None),
                        2
                    );
                    assert!(game.available_name_stickers(owner).is_empty());
                    cases += 1;
                }
            }
        }
    }
    assert_eq!(cases, 80);
}

fn cr_audit_oracle_face_name_restrictions(
    rows: &[(&'static str, &[ironsmith::CardType])],
    filters: &[Option<ironsmith::CardType>],
    rule: &str,
) {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::ChooseCardNameEffect;
    use ironsmith::{CardId, CardType, Effect, ObjectFilter, StackEntry, Zone};
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for (name, types) in rows {
        // Names and selected-face characteristics are independently checked
        // in the root Oracle dataset, not inferred from an unloaded registry.
        for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
            for required_type in filters {
                let legal = required_type.is_none_or(|kind| types.contains(&kind));
                let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                let definition = CardDefinitionBuilder::new(
                    CardId::new(),
                    "Oracle face-name restriction source",
                )
                .card_types(vec![CardType::Artifact])
                .build();
                let source =
                    game.create_object_from_definition(&definition, actor, Zone::Battlefield);
                game.stack.push(StackEntry::ability(
                    source,
                    actor,
                    vec![Effect::new(ChooseCardNameEffect::new(
                        PlayerFilter::You,
                        required_type.map(|kind| ObjectFilter::default().with_type(kind)),
                        "chosen face name",
                    ))],
                ));
                ironsmith::game_loop::resolve_stack_entry_with(
                    &mut game,
                    &mut SubmitCardName(name),
                )
                .unwrap();
                let actual = game.chosen_named_option(source);
                if actual != legal.then_some(*name) {
                    discrepancies.push(format!("rule={rule},name={name:?},types={types:?},actor={actor:?},required_type={required_type:?}:stored{actual:?},required{:?}",legal.then_some(*name)));
                }
                cases += 1;
            }
        }
    }
    assert_eq!(cases, rows.len() * filters.len() * 2);
    assert!(
        discrepancies.is_empty(),
        "CR{rule}: {} invalid face-name choices across{cases} Oracle selected-face/type fixtures:\n{}",
        discrepancies.len(),
        discrepancies.join("\n")
    );
}

#[test]
fn cr_201_4b_split_card_name_restrictions_use_only_the_chosen_half() {
    use ironsmith::CardType::*;
    cr_audit_oracle_face_name_restrictions(
        &[
            ("Discovery", &[Sorcery]),
            ("Dispersal", &[Instant]),
            ("Commit", &[Instant]),
            ("Memory", &[Sorcery]),
        ],
        &[None, Some(Instant), Some(Sorcery), Some(Land)],
        "201.4b",
    );
}

