#[test]
fn cr_608_2h_self_linked_counter_reads_use_live_values_after_counter_changes_in_exile() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::{ExileEffect, MoveToZoneEffect, PutCountersEffect, TapEffect};
    use ironsmith::resolution::ResolutionProgram;
    use ironsmith::triggers::Trigger;
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, CounterType, Effect, ObjectFilter, PowerToughness,
        StackEntry, TriggerQueue, Value, Zone,
    };
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for amount in 0usize..=3 {
        for charge in [1i32, 3] {
            for all in [false, true] {
                for movement in [false, true] {
                    for noise in [false, true] {
                        for holder in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                            for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                                let mut game =
                                    GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                                let instruction = game.create_object_from_definition(
                                    &CardDefinitionBuilder::new(
                                        CardId::new(),
                                        "Same-context counter instruction",
                                    )
                                    .card_types(vec![CardType::Enchantment])
                                    .build(),
                                    actor,
                                    Zone::Battlefield,
                                );
                                let resource_def = CardDefinitionBuilder::new(
                                    CardId::new(),
                                    "Same-context exile counter resource",
                                )
                                .card_types(vec![CardType::Creature])
                                .power_toughness(PowerToughness::fixed(2, 3))
                                .build();
                                let mut resources = Vec::new();
                                for _ in 0..amount {
                                    let id = game.create_object_from_definition(
                                        &resource_def,
                                        holder,
                                        Zone::Graveyard,
                                    );
                                    resources.push(game.object(id).unwrap().stable_id);
                                }
                                let other = PlayerId::from_index(1 - holder.index() as u8);
                                let foreign = game.create_object_from_definition(
                                    &resource_def,
                                    other,
                                    Zone::Graveyard,
                                );
                                let unrelated = game.create_object_from_definition(
                                    &CardDefinitionBuilder::new(
                                        CardId::new(),
                                        "Unrelated exile counter land",
                                    )
                                    .card_types(vec![CardType::Land])
                                    .build(),
                                    holder,
                                    Zone::Graveyard,
                                );
                                let unrelated_stable = game.object(unrelated).unwrap().stable_id;
                                let unrelated_program = vec![Effect::new(ExileEffect::all(
                                    ObjectFilter::land()
                                        .in_zone(Zone::Graveyard)
                                        .owned_by(PlayerFilter::You),
                                ))];
                                let pool = ObjectFilter::creature()
                                    .in_zone(Zone::Graveyard)
                                    .owned_by(PlayerFilter::You);
                                let producer = if movement {
                                    Effect::new(MoveToZoneEffect::new(
                                        ChooseSpec::all(pool),
                                        Zone::Exile,
                                        false,
                                    ))
                                } else {
                                    Effect::new(ExileEffect::all(pool))
                                };
                                let reference =
                                    || ChooseSpec::tagged(ironsmith_core::tag::SOURCE_EXILED_TAG);
                                let pair = ironsmith_core::LinkedExilePair {
                                    definition: ironsmith_core::LinkedExileDefinition(
                                        [200 + u8::from(movement) * 8
                                            + u8::from(all) * 4
                                            + charge as u8;
                                            32],
                                    ),
                                    pair: 0,
                                };
                                let program = ResolutionProgram::from_effects(vec![
                                    producer,
                                    Effect::new(PutCountersEffect::new(
                                        CounterType::Charge,
                                        charge,
                                        reference(),
                                    )),
                                    Effect::new(PutCountersEffect::new(
                                        CounterType::Lore,
                                        2,
                                        reference(),
                                    )),
                                    Effect::gain_life(Value::CountersOn(
                                        Box::new(reference()),
                                        if all { None } else { Some(CounterType::Charge) },
                                    )),
                                ])
                                .with_linked_exile_pair(pair);
                                let subject = game.create_object_from_definition(
                                    &CardDefinitionBuilder::new(
                                        CardId::new(),
                                        "Self-linked live-counter subject",
                                    )
                                    .card_types(vec![CardType::Artifact])
                                    .with_ability(Ability::triggered(
                                        Trigger::becomes_tapped(),
                                        program,
                                    ))
                                    .with_ability(Ability::activated(
                                        ironsmith::cost::TotalCost::free(),
                                        unrelated_program.clone(),
                                    ))
                                    .build(),
                                    holder,
                                    Zone::Battlefield,
                                );
                                if noise {
                                    let mut activation =
                                        StackEntry::ability(subject, holder, unrelated_program);
                                    activation.ability_index = Some(1);
                                    game.stack.push(activation);
                                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                                }
                                game.stack.push(StackEntry::ability(
                                    instruction,
                                    actor,
                                    vec![Effect::new(TapEffect::with_spec(
                                        ChooseSpec::SpecificObject(subject),
                                    ))],
                                ));
                                ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                                let mut queue = TriggerQueue::new();
                                ironsmith::put_triggers_on_stack(&mut game, &mut queue).unwrap();
                                assert_eq!(game.stack.len(), 1);
                                let acquisition = game
                                    .stack
                                    .last()
                                    .unwrap()
                                    .linked_exile_owner
                                    .clone()
                                    .expect("real printed self-linked trigger acquisition");
                                assert_eq!(acquisition.host, subject);
                                assert_eq!(acquisition.pair, pair);
                                let label = format!(
                                    "amount={amount} charge={charge} all={all} movement={movement} noise={noise} holder={holder:?} actor={actor:?}"
                                );
                                if let Err(error) =
                                    ironsmith::game_loop::resolve_stack_entry(&mut game)
                                {
                                    discrepancies.push(format!(
                                        "{label}: self-linked counter program refused{error:?}"
                                    ));
                                    cases += 1;
                                    continue;
                                }
                                for sid in &resources {
                                    let id = game.find_object_by_stable_id(*sid).unwrap();
                                    assert_eq!(game.object(id).unwrap().zone, Zone::Exile);
                                    assert_eq!(
                                        game.counter_count(id, CounterType::Charge),
                                        charge as u32
                                    );
                                    assert_eq!(game.counter_count(id, CounterType::Lore), 2);
                                }
                                assert_eq!(
                                    game.linked_exile_pair_members(&acquisition).unwrap().len(),
                                    amount
                                );
                                assert_eq!(
                                    game.get_exiled_with_source_links(subject).len(),
                                    amount + usize::from(noise)
                                );
                                let expected =
                                    20 + amount as i32 * (charge + if all { 2 } else { 0 });
                                if game.player(holder).unwrap().life != expected {
                                    discrepancies.push(format!("{label}: actual counters are current but reader life{}, required{expected}",game.player(holder).unwrap().life));
                                }
                                assert_eq!(game.player(other).unwrap().life, 20);
                                assert_eq!(game.object(foreign).unwrap().zone, Zone::Graveyard);
                                assert_eq!(
                                    game.object(
                                        game.find_object_by_stable_id(unrelated_stable).unwrap()
                                    )
                                    .unwrap()
                                    .zone,
                                    if noise { Zone::Exile } else { Zone::Graveyard }
                                );
                                game.validate_zone_consistency().unwrap();
                                cases += 1;
                            }
                        }
                    }
                }
            }
        }
    }
    assert_eq!(cases, 256);
    assert!(
        discrepancies.is_empty(),
        "CR608.2h: a linked counter question in the same resolution must use the cards current counters in Exile, rather than snapshots taken before the counters were placed: {discrepancies:#?}"
    );
}

#[test]
fn cr_608_2h_chosen_object_counter_reads_use_current_information_in_public_zones() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::decisions::context::SelectObjectsContext;
    use ironsmith::effects::{ChooseObjectsEffect, PutCountersEffect, TapEffect};
    use ironsmith::triggers::Trigger;
    use ironsmith::{
        Ability, CardId, CardType, ChoiceCount, ChooseSpec, CounterType, Effect, ObjectFilter,
        ObjectId, PowerToughness, StackEntry, TriggerQueue, Value, Zone,
    };
    struct ChooseAll {
        holder: PlayerId,
        expected: Vec<ObjectId>,
    }
    impl DecisionMaker for ChooseAll {
        fn decide_objects(&mut self, _: &GameState, ctx: &SelectObjectsContext) -> Vec<ObjectId> {
            assert_eq!(ctx.player, self.holder);
            let mut legal: Vec<_> = ctx
                .candidates
                .iter()
                .filter(|candidate| candidate.legal)
                .map(|candidate| candidate.id)
                .collect();
            let mut expected = self.expected.clone();
            legal.sort();
            expected.sort();
            assert_eq!(
                legal, expected,
                "actual selected-card menu must contain only the intended current resources"
            );
            legal
        }
    }
    let mut discrepancies = Vec::new();
    let mut cases = 0;
    for amount in 0usize..=3 {
        for charge in [1i32, 3] {
            for all in [false, true] {
                for zone in [Zone::Battlefield, Zone::Exile] {
                    for tagged in [false, true] {
                        for holder in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                            for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                                let mut game =
                                    GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                                let instruction = game.create_object_from_definition(
                                    &CardDefinitionBuilder::new(
                                        CardId::new(),
                                        "Chosen-object counter instruction",
                                    )
                                    .card_types(vec![CardType::Enchantment])
                                    .build(),
                                    actor,
                                    Zone::Battlefield,
                                );
                                let resource_def = CardDefinitionBuilder::new(
                                    CardId::new(),
                                    "Chosen live-counter resource",
                                )
                                .card_types(vec![CardType::Creature])
                                .power_toughness(PowerToughness::fixed(2, 3))
                                .build();
                                let mut resources = Vec::new();
                                for _ in 0..amount {
                                    resources.push(game.create_object_from_definition(
                                        &resource_def,
                                        holder,
                                        zone,
                                    ));
                                }
                                let other = PlayerId::from_index(1 - holder.index() as u8);
                                let foreign =
                                    game.create_object_from_definition(&resource_def, other, zone);
                                let filter = ObjectFilter::creature()
                                    .in_zone(zone)
                                    .owned_by(PlayerFilter::You);
                                let reference = if tagged {
                                    ChooseSpec::tagged("chosen_live_counter_cards")
                                } else {
                                    ChooseSpec::all(filter.clone())
                                };
                                let program = vec![
                                    Effect::new(
                                        ChooseObjectsEffect::new(
                                            filter,
                                            ChoiceCount::any_number(),
                                            PlayerFilter::You,
                                            "chosen_live_counter_cards",
                                        )
                                        .replace_tagged_objects(),
                                    ),
                                    Effect::new(PutCountersEffect::new(
                                        CounterType::Charge,
                                        charge,
                                        ChooseSpec::tagged("chosen_live_counter_cards"),
                                    )),
                                    Effect::new(PutCountersEffect::new(
                                        CounterType::Lore,
                                        2,
                                        ChooseSpec::tagged("chosen_live_counter_cards"),
                                    )),
                                    Effect::gain_life(Value::CountersOn(
                                        Box::new(reference),
                                        if all { None } else { Some(CounterType::Charge) },
                                    )),
                                ];
                                let subject = game.create_object_from_definition(
                                    &CardDefinitionBuilder::new(
                                        CardId::new(),
                                        "Chosen live-counter subject",
                                    )
                                    .card_types(vec![CardType::Artifact])
                                    .with_ability(Ability::triggered(
                                        Trigger::becomes_tapped(),
                                        program,
                                    ))
                                    .build(),
                                    holder,
                                    Zone::Battlefield,
                                );
                                game.stack.push(StackEntry::ability(
                                    instruction,
                                    actor,
                                    vec![Effect::new(TapEffect::with_spec(
                                        ChooseSpec::SpecificObject(subject),
                                    ))],
                                ));
                                ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                                let mut queue = TriggerQueue::new();
                                ironsmith::put_triggers_on_stack(&mut game, &mut queue).unwrap();
                                assert_eq!(game.stack.len(), 1);
                                let label = format!(
                                    "amount={amount} charge={charge} all={all} zone={zone:?} tagged={tagged} holder={holder:?} actor={actor:?}"
                                );
                                let mut dm = ChooseAll {
                                    holder,
                                    expected: resources.clone(),
                                };
                                if let Err(error) = ironsmith::game_loop::resolve_stack_entry_with(
                                    &mut game, &mut dm,
                                ) {
                                    discrepancies.push(format!(
                                        "{label}: chosen counter program refused{error:?}"
                                    ));
                                    cases += 1;
                                    continue;
                                }
                                for id in &resources {
                                    assert_eq!(game.object(*id).unwrap().zone, zone);
                                    assert_eq!(
                                        game.counter_count(*id, CounterType::Charge),
                                        charge as u32
                                    );
                                    assert_eq!(game.counter_count(*id, CounterType::Lore), 2);
                                }
                                let expected =
                                    20 + amount as i32 * (charge + if all { 2 } else { 0 });
                                if game.player(holder).unwrap().life != expected {
                                    discrepancies.push(format!("{label}: actual counters are current but reader life{}, required{expected}",game.player(holder).unwrap().life));
                                }
                                assert_eq!(game.player(other).unwrap().life, 20);
                                assert_eq!(game.object(foreign).unwrap().zone, zone);
                                assert_eq!(game.counter_count(foreign, CounterType::Charge), 0);
                                assert_eq!(game.counter_count(foreign, CounterType::Lore), 0);
                                game.validate_zone_consistency().unwrap();
                                cases += 1;
                            }
                        }
                    }
                }
            }
        }
    }
    assert_eq!(cases, 256);
    assert!(
        discrepancies.is_empty(),
        "CR608.2h: an ordinary tagged chosen object that stayed in its expected public zone must be read live after counter placement, just like the equivalent explicit collection reference: {discrepancies:#?}"
    );
}

fn check_unrelated_chosen_color_after_ability_change(mana_reader: bool) {
    use ironsmith::ability::ProtectionFrom;
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::continuous::EffectTarget;
    use ironsmith::cost::TotalCost;
    use ironsmith::decisions::context::ColorsContext;
    use ironsmith::effects::{
        AddManaOfChosenColorEffect, ApplyContinuousEffect, DealDamageEffect, MoveToZoneEffect,
        RuntimeModification,
    };
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, Color, ColorSet, Effect, StaticAbility, Until, Zone,
    };
    struct PickColor {
        color: Color,
        players: Vec<PlayerId>,
    }
    impl DecisionMaker for PickColor {
        fn decide_colors(&mut self, _: &GameState, ctx: &ColorsContext) -> Vec<Color> {
            self.players.push(ctx.player);
            vec![self.color]
        }
    }
    let mut failures = Vec::new();
    let mut checked = 0;
    for holder in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for color in [
            Color::White,
            Color::Blue,
            Color::Black,
            Color::Red,
            Color::Green,
        ] {
            for mode in 0..2 {
                let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                let reader = if mana_reader {
                    Ability::mana_with_effects(
                        TotalCost::free(),
                        vec![
                            Effect::new(AddManaOfChosenColorEffect::new(1, PlayerFilter::You)),
                            Effect::gain_life(2),
                        ],
                    )
                } else {
                    Ability::static_ability(StaticAbility::protection(ProtectionFrom::ChosenColor))
                };
                let chooser = Ability::static_ability(StaticAbility::choose_color_as_enters(
                    None,
                    "As this permanent enters, choose a color.".into(),
                ));
                let mut initial =
                    CardDefinitionBuilder::new(CardId::new(), "Original choice family")
                        .card_types(vec![CardType::Creature])
                        .power_toughness(ironsmith::PowerToughness::fixed(3, 12))
                        .with_ability(chooser.clone());
                // Mode0 exercises the reader whose own entry choice was actually made.
                if mode == 0 {
                    initial = initial.with_ability(reader.clone());
                }
                let initial = initial.with_ability(Ability::static_ability(StaticAbility::haste())).build();
                let card = game.create_object_from_definition(&initial, holder, Zone::Graveyard);
                let stable = game.object(card).unwrap().stable_id;
                let mut dm = PickColor {
                    color,
                    players: vec![],
                };
                MoveToZoneEffect::new(ChooseSpec::SpecificObject(card), Zone::Battlefield, false)
                    .execute(
                        &mut game,
                        &mut EffectContext::new_default(card, holder).with_decision_maker(&mut dm),
                    )
                    .unwrap();
                let subject = game.find_object_by_stable_id(stable).unwrap();
                assert_eq!(dm.players, vec![holder]);
                assert_eq!(game.chosen_color(subject), Some(color));
                if mode > 0 {
                    let modification = {
                        // The copied chooser never has an opportunity to run on this
                        // existing permanent. The old choice belongs to another ability.
                        let donor_def = CardDefinitionBuilder::new(
                            CardId::new(),
                            "Different linked choice family",
                        )
                        .card_types(vec![CardType::Creature])
                        .power_toughness(ironsmith::PowerToughness::fixed(3, 12))
                        .with_ability(chooser.clone())
                        .with_ability(reader.clone())
                        .with_ability(Ability::static_ability(StaticAbility::haste()))
                        .build();
                        let donor_card =
                            game.create_object_from_definition(&donor_def, holder, Zone::Graveyard);
                        let donor_stable = game.object(donor_card).unwrap().stable_id;
                        let donor_color = if color == Color::Blue {
                            Color::Red
                        } else {
                            Color::Blue
                        };
                        let mut donor_dm = PickColor {
                            color: donor_color,
                            players: vec![],
                        };
                        MoveToZoneEffect::new(
                            ChooseSpec::SpecificObject(donor_card),
                            Zone::Battlefield,
                            false,
                        )
                        .execute(
                            &mut game,
                            &mut EffectContext::new_default(donor_card, holder)
                                .with_decision_maker(&mut donor_dm),
                        )
                        .unwrap();
                        let donor = game.find_object_by_stable_id(donor_stable).unwrap();
                        assert_eq!(donor_dm.players, vec![holder]);
                        assert_eq!(game.chosen_color(donor), Some(donor_color));
                        RuntimeModification::CopyOf {
                            source: ChooseSpec::SpecificObject(donor),
                            preserve_source_abilities: false,
                            name_override: None,
                            name_override_surface: None,
                            add_supertypes: vec![],
                            copy_exception_surface: None,
                        }
                    };
                    game.stack.push(ironsmith::StackEntry::ability(
                        subject,
                        holder,
                        vec![Effect::new(ApplyContinuousEffect::new_runtime(
                            EffectTarget::Specific(subject),
                            modification,
                            Until::EndOfTurn,
                        ))],
                    ));
                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                    assert_eq!(game.object(subject).unwrap().zone, Zone::Battlefield);
                    // The rule constrains use of the old choice, not whether
                    // the engine keeps that information in its internal store.
                }
                if mana_reader {
                    let ability_index = 1;
                    ironsmith::special_actions::perform_activate_mana_ability(
                        &mut game,
                        holder,
                        subject,
                        ability_index,
                        &mut ironsmith::decision::SelectFirstDecisionMaker,
                    )
                    .unwrap();
                    assert_eq!(
                        game.player(holder).unwrap().life,
                        22,
                        "The independent gain-life instruction still resolves"
                    );
                    let pool = &game.player(holder).unwrap().mana_pool;
                    let actual = (
                        pool.white,
                        pool.blue,
                        pool.black,
                        pool.red,
                        pool.green,
                        pool.colorless,
                    );
                    let expected = if mode == 0 {
                        match color {
                            Color::White => (1, 0, 0, 0, 0, 0),
                            Color::Blue => (0, 1, 0, 0, 0, 0),
                            Color::Black => (0, 0, 1, 0, 0, 0),
                            Color::Red => (0, 0, 0, 1, 0, 0),
                            Color::Green => (0, 0, 0, 0, 1, 0),
                        }
                    } else {
                        (0, 0, 0, 0, 0, 0)
                    };
                    if actual != expected {
                        failures.push(format!("holder={holder:?} color={color:?} mode={mode}: mana {actual:?}, expected {expected:?}"));
                    }
                } else {
                    for (damage_color, colors) in [
                        (Color::White, ColorSet::WHITE),
                        (Color::Blue, ColorSet::BLUE),
                        (Color::Black, ColorSet::BLACK),
                        (Color::Red, ColorSet::RED),
                        (Color::Green, ColorSet::GREEN),
                    ] {
                        let damage_def =
                            CardDefinitionBuilder::new(CardId::new(), "Colored damage instruction")
                                .card_types(vec![CardType::Artifact])
                                .color_indicator(colors)
                                .build();
                        let source = game.create_object_from_definition(
                            &damage_def,
                            holder,
                            Zone::Battlefield,
                        );
                        let before = game.damage_on(subject);
                        DealDamageEffect::new(1, ChooseSpec::SpecificObject(subject))
                            .execute(&mut game, &mut EffectContext::new_default(source, holder))
                            .unwrap();
                        let actual = game.damage_on(subject) - before;
                        let expected = u32::from(mode != 0 || damage_color != color);
                        if actual != expected {
                            failures.push(format!("holder={holder:?} color={color:?} mode={mode} damage_color={damage_color:?}: damage {actual}, expected {expected}"));
                        }
                    }
                }
                assert!(game.stack.is_empty());
                assert_eq!(
                    game.player(PlayerId::from_index(1 - holder.index() as u8))
                        .unwrap()
                        .life,
                    20
                );
                checked += 1;
            }
        }
    }
    assert_eq!(checked, 20);
    assert!(
        failures.is_empty(),
        "CR 607.2d/607.5a: a copied reader cannot consume an unrelated old color choice; reader_mana={mana_reader}; {} mismatches in {checked} fixtures:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn cr_607_5a_copied_mana_reader_does_not_reuse_unrelated_entry_choice() {
    check_unrelated_chosen_color_after_ability_change(true);
}

#[test]
fn cr_607_5a_copied_protection_does_not_reuse_unrelated_entry_choice() {
    check_unrelated_chosen_color_after_ability_change(false);
}
fn check_created_or_put_collection_source_incarnation(tokens: bool) {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::{CreateTokenEffect, MoveToZoneEffect};
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, Effect, LegalAction, ObjectFilter, Phase,
        StackEntry, Value, Zone,
    };
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for holder in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
            for old_count in 0..4 {
                for new_count in 0..3 {
                    for blink in [false, true] {
                        let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                        game.turn.active_player = holder;
                        game.turn.priority_player = Some(holder);
                        game.turn.phase = Phase::FirstMain;
                        let resource_def =
                            CardDefinitionBuilder::new(CardId::new(), "Created-or-put resource")
                                .card_types(vec![CardType::Creature])
                                .power_toughness(ironsmith::PowerToughness::fixed(2, 3))
                                .build();
                        let producer = if tokens {
                            Effect::new(CreateTokenEffect::one(resource_def.clone()))
                        } else {
                            Effect::new(MoveToZoneEffect::new(
                                ChooseSpec::all(
                                    ObjectFilter::creature()
                                        .in_zone(Zone::Graveyard)
                                        .owned_by(PlayerFilter::You),
                                ),
                                Zone::Battlefield,
                                false,
                            ))
                        };
                        let mut linked = ObjectFilter::creature().in_zone(Zone::Battlefield);
                        linked.created_with_source = tokens;
                        linked.put_onto_battlefield_with_source = !tokens;
                        let definition = CardDefinitionBuilder::new(
                            CardId::new(),
                            "One producer and its collection reader",
                        )
                        .card_types(vec![CardType::Artifact])
                        .with_ability(Ability::activated(
                            ironsmith::cost::TotalCost::free(),
                            vec![producer],
                        ))
                        .with_ability(Ability::activated(
                            ironsmith::cost::TotalCost::free(),
                            vec![Effect::gain_life(Value::Count(linked))],
                        ))
                        .build();
                        let source = game.create_object_from_definition(
                            &definition,
                            holder,
                            Zone::Battlefield,
                        );
                        let stable = game.object(source).unwrap().stable_id;
                        let unrelated = game.create_object_from_definition(
                            &definition,
                            holder,
                            Zone::Battlefield,
                        );
                        let instruction = game.create_object_from_definition(
                            &CardDefinitionBuilder::new(CardId::new(), "Zone-change instruction")
                                .card_types(vec![CardType::Artifact])
                                .build(),
                            actor,
                            Zone::Battlefield,
                        );
                        let other = PlayerId::from_index(1 - holder.index() as u8);
                        let foreign = game.create_object_from_definition(
                            &resource_def,
                            other,
                            Zone::Graveyard,
                        );
                        let mut old_resources = Vec::new();
                        let mut new_resources = Vec::new();
                        let mut unrelated_resources = Vec::new();
                        // Real repeated activations of the same printed producer;
                        // no ownership/provenance record is inserted by the fixture.
                        for (host, amount, storage) in [
                            (source, old_count, &mut old_resources),
                            (unrelated, 2, &mut unrelated_resources),
                        ] {
                            for _ in 0..amount {
                                if !tokens {
                                    game.create_object_from_definition(
                                        &resource_def,
                                        holder,
                                        Zone::Graveyard,
                                    );
                                }
                                let before = game.battlefield.clone();
                                let action = LegalAction::ActivateAbility {
                                    source: host,
                                    ability_index: 0,
                                };
                                assert!(
                                    ironsmith::compute_legal_actions(&game, holder)
                                        .unwrap()
                                        .contains(&action)
                                );
                                cr_audit_complete_priority_action(&mut game, holder, action)
                                    .unwrap();
                                assert_eq!(game.stack.len(), 1);
                                assert_eq!(game.stack.last().unwrap().object_id, host);
                                ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                                let added: Vec<_> = game
                                    .battlefield
                                    .iter()
                                    .copied()
                                    .filter(|id| !before.contains(id))
                                    .collect();
                                assert_eq!(added.len(), 1);
                                storage.extend(added);
                            }
                        }
                        if blink {
                            for destination in [Zone::Hand, Zone::Battlefield] {
                                let current = game.find_object_by_stable_id(stable).unwrap();
                                game.stack.push(StackEntry::ability(
                                    instruction,
                                    actor,
                                    vec![Effect::new(MoveToZoneEffect::new(
                                        ChooseSpec::SpecificObject(current),
                                        destination,
                                        false,
                                    ))],
                                ));
                                ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                            }
                        }
                        let current = game.find_object_by_stable_id(stable).unwrap();
                        assert_eq!(game.object(current).unwrap().zone, Zone::Battlefield);
                        assert_eq!(current == source, !blink);
                        for _ in 0..new_count {
                            if !tokens {
                                game.create_object_from_definition(
                                    &resource_def,
                                    holder,
                                    Zone::Graveyard,
                                );
                            }
                            let before = game.battlefield.clone();
                            let action = LegalAction::ActivateAbility {
                                source: current,
                                ability_index: 0,
                            };
                            assert!(
                                ironsmith::compute_legal_actions(&game, holder)
                                    .unwrap()
                                    .contains(&action)
                            );
                            cr_audit_complete_priority_action(&mut game, holder, action).unwrap();
                            assert_eq!(game.stack.len(), 1);
                            ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                            let added: Vec<_> = game
                                .battlefield
                                .iter()
                                .copied()
                                .filter(|id| !before.contains(id))
                                .collect();
                            assert_eq!(added.len(), 1);
                            new_resources.extend(added);
                        }
                        let action = LegalAction::ActivateAbility {
                            source: current,
                            ability_index: 1,
                        };
                        assert!(
                            ironsmith::compute_legal_actions(&game, holder)
                                .unwrap()
                                .contains(&action)
                        );
                        cr_audit_complete_priority_action(&mut game, holder, action).unwrap();
                        assert_eq!(game.stack.len(), 1);
                        assert_eq!(game.stack.last().unwrap().object_id, current);
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        let expected = new_count + if blink { 0 } else { old_count };
                        let actual = game.player(holder).unwrap().life - 20;
                        if actual != expected {
                            discrepancies.push(format!("tokens={tokens} holder={holder:?} actor={actor:?} old={old_count} new={new_count} blink={blink}: reader gain{actual}, expected{expected}"));
                        }
                        for id in old_resources
                            .iter()
                            .chain(new_resources.iter())
                            .chain(unrelated_resources.iter())
                        {
                            let object = game.object(*id).unwrap();
                            assert_eq!(object.zone, Zone::Battlefield);
                            assert_eq!(object.owner, holder);
                            assert_eq!(game.current_controller(*id), Some(holder));
                            assert_eq!(object.kind == ironsmith::object::ObjectKind::Token, tokens);
                        }
                        assert_eq!(old_resources.len(), old_count as usize);
                        assert_eq!(new_resources.len(), new_count as usize);
                        assert_eq!(unrelated_resources.len(), 2);
                        assert_eq!(game.object(foreign).unwrap().zone, Zone::Graveyard);
                        assert_eq!(game.player(other).unwrap().life, 20);
                        assert!(game.stack.is_empty());
                        game.validate_zone_consistency().unwrap();
                        cases += 1;
                    }
                }
            }
        }
    }
    assert_eq!(cases, 96);
    assert!(
        discrepancies.is_empty(),
        "CR400.7/607.2c: a new source incarnation cannot inherit a former incarnation's created/put collection; {} mismatches in{cases} fixtures:\n{}",
        discrepancies.len(),
        discrepancies.join("\n")
    );
}

#[test]
fn cr_400_7_607_2c_returned_permanent_excludes_tokens_created_by_its_former_incarnation() {
    check_created_or_put_collection_source_incarnation(true);
}

#[test]
fn cr_400_7_607_2c_returned_permanent_excludes_cards_put_by_its_former_incarnation() {
    check_created_or_put_collection_source_incarnation(false);
}

#[test]
fn cr_400_7_607_2c_old_leaves_trigger_excludes_tokens_created_by_returned_incarnation() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::{CreateTokenEffect, MoveToZoneEffect};
    use ironsmith::triggers::{Trigger, TriggerQueue};
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, Effect, LegalAction, ObjectFilter, Phase,
        StackEntry, Value, Zone,
    };
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for holder in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
            for old_count in 0..4 {
                for new_count in 0..3 {
                    for destination in [Zone::Hand, Zone::Graveyard, Zone::Exile] {
                        let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                        game.turn.active_player = holder;
                        game.turn.priority_player = Some(holder);
                        game.turn.phase = Phase::FirstMain;
                        let token_def =
                            CardDefinitionBuilder::new(CardId::new(), "Waiting-source token")
                                .card_types(vec![CardType::Creature])
                                .power_toughness(ironsmith::PowerToughness::fixed(2, 3))
                                .build();
                        let linked = ObjectFilter {
                            created_with_source: true,
                            ..ObjectFilter::creature().in_zone(Zone::Battlefield)
                        };
                        let definition = CardDefinitionBuilder::new(
                            CardId::new(),
                            "Token producer with a linked leaves reader",
                        )
                        .card_types(vec![CardType::Artifact])
                        .with_ability(Ability::activated(
                            ironsmith::cost::TotalCost::free(),
                            vec![Effect::new(CreateTokenEffect::one(token_def))],
                        ))
                        .with_ability(Ability::triggered(
                            Trigger::this_leaves_battlefield(),
                            vec![Effect::gain_life(Value::Count(linked))],
                        ))
                        .build();
                        let source = game.create_object_from_definition(
                            &definition,
                            holder,
                            Zone::Battlefield,
                        );
                        let stable = game.object(source).unwrap().stable_id;
                        let unrelated = game.create_object_from_definition(
                            &definition,
                            holder,
                            Zone::Battlefield,
                        );
                        let instruction = game.create_object_from_definition(
                            &CardDefinitionBuilder::new(
                                CardId::new(),
                                "Instruction above waiting leaves reader",
                            )
                            .card_types(vec![CardType::Artifact])
                            .build(),
                            actor,
                            Zone::Battlefield,
                        );
                        let mut old_tokens = Vec::new();
                        let mut new_tokens = Vec::new();
                        for (host, amount) in [(source, old_count), (unrelated, 2)] {
                            for _ in 0..amount {
                                let before = game.battlefield.clone();
                                let action = LegalAction::ActivateAbility {
                                    source: host,
                                    ability_index: 0,
                                };
                                assert!(
                                    ironsmith::compute_legal_actions(&game, holder)
                                        .unwrap()
                                        .contains(&action)
                                );
                                cr_audit_complete_priority_action(&mut game, holder, action)
                                    .unwrap();
                                assert_eq!(game.stack.len(), 1);
                                ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                                let added: Vec<_> = game
                                    .battlefield
                                    .iter()
                                    .copied()
                                    .filter(|id| !before.contains(id))
                                    .collect();
                                assert_eq!(added.len(), 1);
                                if host == source {
                                    old_tokens.extend(added);
                                }
                            }
                        }
                        game.stack.push(StackEntry::ability(
                            instruction,
                            actor,
                            vec![Effect::new(MoveToZoneEffect::new(
                                ChooseSpec::SpecificObject(source),
                                destination,
                                false,
                            ))],
                        ));
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        let mut queue = TriggerQueue::new();
                        ironsmith::put_triggers_on_stack(&mut game, &mut queue).unwrap();
                        assert_eq!(
                            game.stack.len(),
                            1,
                            "The actual old-source leaves trigger must be waiting"
                        );
                        assert_eq!(game.stack.last().unwrap().object_id, source);
                        assert_eq!(
                            game.stack
                                .last()
                                .unwrap()
                                .source_snapshot
                                .as_ref()
                                .unwrap()
                                .stable_id,
                            stable
                        );
                        let outside = game.find_object_by_stable_id(stable).unwrap();
                        assert_eq!(game.object(outside).unwrap().zone, destination);
                        game.stack.push(StackEntry::ability(
                            instruction,
                            actor,
                            vec![Effect::new(MoveToZoneEffect::new(
                                ChooseSpec::SpecificObject(outside),
                                Zone::Battlefield,
                                false,
                            ))],
                        ));
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        let current = game.find_object_by_stable_id(stable).unwrap();
                        assert_ne!(source, current);
                        for _ in 0..new_count {
                            let before = game.battlefield.clone();
                            let action = LegalAction::ActivateAbility {
                                source: current,
                                ability_index: 0,
                            };
                            assert!(
                                ironsmith::compute_legal_actions(&game, holder)
                                    .unwrap()
                                    .contains(&action)
                            );
                            cr_audit_complete_priority_action(&mut game, holder, action).unwrap();
                            assert_eq!(
                                game.stack.len(),
                                2,
                                "New production is above the real old-source reader"
                            );
                            assert_eq!(game.stack.last().unwrap().object_id, current);
                            ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                            let added: Vec<_> = game
                                .battlefield
                                .iter()
                                .copied()
                                .filter(|id| !before.contains(id))
                                .collect();
                            assert_eq!(added.len(), 1);
                            new_tokens.extend(added);
                        }
                        assert_eq!(game.stack.len(), 1);
                        assert_eq!(game.stack.last().unwrap().object_id, source);
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        let actual = game.player(holder).unwrap().life - 20;
                        if actual != old_count {
                            discrepancies.push(format!("holder={holder:?} actor={actor:?} old={old_count} new={new_count} destination={destination:?}: old-source gain{actual}, expected{old_count}"));
                        }
                        assert_eq!(old_tokens.len(), old_count as usize);
                        assert_eq!(new_tokens.len(), new_count as usize);
                        for id in old_tokens.iter().chain(new_tokens.iter()) {
                            let object = game.object(*id).unwrap();
                            assert_eq!(object.kind, ironsmith::object::ObjectKind::Token);
                            assert_eq!(object.zone, Zone::Battlefield);
                            assert_eq!(object.owner, holder);
                            assert_eq!(game.current_controller(*id), Some(holder));
                        }
                        assert_eq!(
                            game.player(PlayerId::from_index(1 - holder.index() as u8))
                                .unwrap()
                                .life,
                            20
                        );
                        assert!(game.stack.is_empty());
                        game.validate_zone_consistency().unwrap();
                        cases += 1;
                    }
                }
            }
        }
    }
    assert_eq!(cases, 144);
    assert!(
        discrepancies.is_empty(),
        "CR400.7/607.2c: a waiting old-source leaves trigger cannot consume a returned incarnation's creations; {} mismatches in{cases} fixtures:\n{}",
        discrepancies.len(),
        discrepancies.join("\n")
    );
}

#[test]
fn cr_603_11_607_2h_same_effect_reveal_static_and_trigger_keep_their_link() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::continuous::{EffectTarget, Modification};
    use ironsmith::effects::{ApplyContinuousEffect, RevealFromHandEffect};
    use ironsmith::static_abilities::CompiledStaticAbility;
    use ironsmith::triggers::{Trigger, TriggerQueue};
    use ironsmith::{
        Ability, CardId, CardType, Effect, LegalAction, ObjectFilter, ObjectId, Phase, StackEntry,
        StaticAbility, Until, Zone,
    };
    struct RevealAnswer {
        accept: bool,
        offers: Vec<(PlayerId, Option<ObjectId>)>,
    }
    impl DecisionMaker for RevealAnswer {
        fn decide_boolean(&mut self, _: &GameState, ctx: &BooleanContext) -> bool {
            assert!(ctx.description.contains("reveal the first card"));
            assert!(ctx.can_accept);
            self.offers.push((ctx.player, ctx.source));
            self.accept
        }
    }
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for mode in 0..4 {
        for holder in [PlayerId::from_index(0), PlayerId::from_index(1)] {
            for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                for creature in [false, true] {
                    for accept in [false, true] {
                        for noise in [false, true] {
                            let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                            game.turn.active_player = holder;
                            game.turn.priority_player = Some(holder);
                            game.turn.phase = Phase::FirstMain;
                            let pair = ironsmith_core::LinkedExilePair {
                                definition: ironsmith_core::LinkedExileDefinition([223; 32]),
                                pair: 0,
                            };
                            let mut model =
                                CompiledStaticAbility::reveal_first_card_you_draw_each_turn(
                                    true, false,
                                );
                            let ironsmith_core::StaticAbilityPayload::RevealFirstCardYouDrawEachTurn {linked_reveal_pair,..}=&mut model.payload else {unreachable!()};
                            *linked_reveal_pair = Some(pair);
                            let revealer =
                                Ability::static_ability(StaticAbility::from_model(model));
                            let mut matcher = ironsmith::triggers::PlayerRevealsCardTrigger::new(
                                PlayerFilter::You, ObjectFilter::creature(), true,
                            );
                            matcher.first_draw_pair = Some(pair);
                            let reader = Ability::triggered(Trigger::new(matcher), vec![Effect::gain_life(3)]);
                            let unrelated = Ability::activated(
                                ironsmith::cost::TotalCost::free(),
                                vec![Effect::new(RevealFromHandEffect::new(1, None))],
                            );
                            let mut subject_def = CardDefinitionBuilder::new(
                                CardId::new(),
                                "Static reveal and its linked trigger",
                            )
                            .card_types(vec![CardType::Artifact])
                            .with_ability(unrelated.clone());
                            if mode == 0 {
                                subject_def = subject_def
                                    .with_ability(revealer.clone())
                                    .with_ability(reader.clone());
                            }
                            let subject = game.create_object_from_definition(
                                &subject_def.build(),
                                holder,
                                Zone::Battlefield,
                            );
                            let instruction = game.create_object_from_definition(
                                &CardDefinitionBuilder::new(
                                    CardId::new(),
                                    "Reveal pair granting instruction",
                                )
                                .card_types(vec![CardType::Artifact])
                                .build(),
                                actor,
                                Zone::Battlefield,
                            );
                            if mode > 0 {
                                let first = ApplyContinuousEffect::new(
                                    EffectTarget::Specific(subject),
                                    Modification::AddAbilityGeneric(revealer.clone()),
                                    Until::EndOfTurn,
                                );
                                if mode == 1 {
                                    game.stack.push(StackEntry::ability(
                                        instruction,
                                        actor,
                                        vec![Effect::new(first.with_additional_modification(
                                            Modification::AddAbilityGeneric(reader.clone()),
                                        ))],
                                    ));
                                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                                } else if mode == 2 {
                                    game.stack.push(StackEntry::ability(
                                        instruction,
                                        actor,
                                        vec![Effect::new(ApplyContinuousEffect::new(
                                            EffectTarget::Specific(subject),
                                            Modification::SetAbilities(vec![
                                                unrelated.clone(),
                                                revealer.clone(),
                                                reader.clone(),
                                            ]),
                                            Until::EndOfTurn,
                                        ))],
                                    ));
                                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                                } else {
                                    for modification in [
                                        Modification::AddAbilityGeneric(revealer.clone()),
                                        Modification::AddAbilityGeneric(reader.clone()),
                                    ] {
                                        game.stack.push(StackEntry::ability(
                                            instruction,
                                            actor,
                                            vec![Effect::new(ApplyContinuousEffect::new(
                                                EffectTarget::Specific(subject),
                                                modification,
                                                Until::EndOfTurn,
                                            ))],
                                        ));
                                        ironsmith::game_loop::resolve_stack_entry(&mut game)
                                            .unwrap();
                                    }
                                }
                            }
                            let grants = game.effect_store.continuous_effects.effects();
                            assert_eq!(
                                grants.len(),
                                if mode == 0 {
                                    0
                                } else if mode == 2 {
                                    1
                                } else {
                                    2
                                }
                            );
                            if mode == 1 {
                                assert!(grants[0].group.is_some());
                                assert_eq!(grants[0].group, grants[1].group);
                            } else {
                                assert!(grants.iter().all(|grant| grant.group.is_none()));
                            }
                            let mut card_def = CardDefinitionBuilder::new(
                                CardId::new(),
                                "Revealed physical resource",
                            )
                            .card_types(vec![if creature {
                                CardType::Creature
                            } else {
                                CardType::Artifact
                            }]);
                            if creature {
                                card_def = card_def
                                    .power_toughness(ironsmith::PowerToughness::fixed(2, 3));
                            }
                            let card_def = card_def.build();
                            game.create_object_from_definition(&card_def, holder, Zone::Hand);
                            for _ in 0..2 {
                                game.create_object_from_definition(
                                    &card_def,
                                    holder,
                                    Zone::Library,
                                );
                            }
                            if noise {
                                let action = LegalAction::ActivateAbility {
                                    source: subject,
                                    ability_index: 0,
                                };
                                assert!(
                                    ironsmith::compute_legal_actions(&game, holder)
                                        .unwrap()
                                        .contains(&action)
                                );
                                cr_audit_complete_priority_action(&mut game, holder, action)
                                    .unwrap();
                                ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                                let mut queue = TriggerQueue::new();
                                ironsmith::put_triggers_on_stack(&mut game, &mut queue).unwrap();
                                assert!(
                                    game.stack.is_empty(),
                                    "An unrelated ordinary reveal must not satisfy the first-draw link"
                                );
                            }
                            let mut dm = RevealAnswer {
                                accept,
                                offers: vec![],
                            };
                            game.stack.push(StackEntry::ability(
                                instruction,
                                holder,
                                vec![Effect::draw(1)],
                            ));
                            if let Err(error) =
                                ironsmith::game_loop::resolve_stack_entry_with(&mut game, &mut dm)
                            {
                                discrepancies.push(format!("mode={mode} holder={holder:?} actor={actor:?} creature={creature} accept={accept} noise={noise}: actual draw refused {error:?}"));
                                cases += 1;
                                continue;
                            }
                            assert_eq!(dm.offers, vec![(holder, Some(subject))]);
                            assert_eq!(game.player(holder).unwrap().hand.len(), 2);
                            let mut queue = TriggerQueue::new();
                            ironsmith::put_triggers_on_stack(&mut game, &mut queue).unwrap();
                            let expected = usize::from(accept && creature && mode != 3);
                            let actual = game.stack.len();
                            if actual != expected {
                                discrepancies.push(format!("mode={mode} holder={holder:?} actor={actor:?} creature={creature} accept={accept} noise={noise}: linked trigger count{actual}, expected{expected}"));
                            }
                            for _ in 0..actual {
                                ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                            }
                            if game.player(holder).unwrap().life != 20 + 3 * expected as i32 {
                                discrepancies.push(format!("mode={mode} holder={holder:?} actor={actor:?} creature={creature} accept={accept} noise={noise}: life{}, expected{}",game.player(holder).unwrap().life,20+3*expected as i32));
                            }
                            // A second actual draw in the turn has no reveal entitlement.
                            game.stack.push(StackEntry::ability(
                                instruction,
                                holder,
                                vec![Effect::draw(1)],
                            ));
                            ironsmith::game_loop::resolve_stack_entry_with(&mut game, &mut dm)
                                .unwrap();
                            assert_eq!(dm.offers.len(), 1);
                            assert_eq!(game.player(holder).unwrap().hand.len(), 3);
                            ironsmith::put_triggers_on_stack(&mut game, &mut queue).unwrap();
                            assert!(game.stack.is_empty());
                            assert_eq!(
                                game.player(PlayerId::from_index(1 - holder.index() as u8))
                                    .unwrap()
                                    .life,
                                20
                            );
                            game.validate_zone_consistency().unwrap();
                            cases += 1;
                        }
                    }
                }
            }
        }
    }
    assert_eq!(cases, 128);
    assert!(
        discrepancies.is_empty(),
        "CR603.11/607.2h/607.5: a static reveal and linked trigger granted by one effect must retain their shared acquisition; {} mismatch diagnostics in{cases} fixtures:\n{}",
        discrepancies.len(),
        discrepancies.join("\n")
    );
}
#[test]
fn cr_607_1d_created_emblem_reads_its_creators_exact_linked_exile_collection() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effect::EmblemDescription;
    use ironsmith::resolution::ResolutionProgram;
    use ironsmith::effects::{CreateEmblemEffect, ExileEffect, MoveToZoneEffect, TapEffect};
    use ironsmith::grant::{GrantSpec, Grantable};
    use ironsmith::triggers::{Trigger, TriggerQueue};
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, Effect, LegalAction, ManaCost, ObjectFilter, Phase,
        StackEntry, StaticAbility, Zone,
    };
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for marked in [false, true] {
        for holder in [PlayerId::from_index(0), PlayerId::from_index(1)] {
            for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                for amount in 0..4 {
                    for noise in [false, true] {
                        for departure in 0..3 {
                            let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                            game.turn.active_player = holder;
                            game.turn.priority_player = Some(holder);
                            game.turn.phase = Phase::FirstMain;
                            let pair = ironsmith_core::LinkedExilePair {
                                definition: ironsmith_core::LinkedExileDefinition([224; 32]),
                                pair: 0,
                            };
                            let mut grant = GrantSpec::new(
                                Grantable::PlayFrom,
                                ObjectFilter::tagged(ironsmith_core::tag::SOURCE_EXILED_TAG),
                                Zone::Exile,
                            );
                            if marked {
                                grant.requires_linked_exile_pair = true;
                                grant.linked_exile_pair = Some(pair);
                            }
                            let emblem = EmblemDescription::new(
                                "Creator-linked native emblem",
                                "You may play cards exiled with the creator.",
                            )
                            .with_ability(Ability::static_ability(StaticAbility::grants(grant)));
                            let create = ResolutionProgram::from_effects(vec![Effect::new(
                                CreateEmblemEffect::new(emblem),
                            )])
                            .with_linked_exile_pair(pair);
                            let producer = ResolutionProgram::from_effects(vec![Effect::new(
                                ExileEffect::all(
                                    ObjectFilter::artifact()
                                        .in_zone(Zone::Graveyard)
                                        .owned_by(PlayerFilter::You),
                                ),
                            )])
                            .with_linked_exile_pair(pair);
                            let definition = CardDefinitionBuilder::new(
                                CardId::new(),
                                "Creator of an exact linked emblem",
                            )
                            .card_types(vec![CardType::Artifact])
                            .with_ability(Ability::triggered(Trigger::becomes_tapped(), producer))
                            .with_ability(Ability::activated(
                                ironsmith::cost::TotalCost::free(),
                                create,
                            ))
                            .with_ability(Ability::activated(
                                ironsmith::cost::TotalCost::free(),
                                vec![Effect::new(ExileEffect::all(
                                    ObjectFilter::land()
                                        .in_zone(Zone::Graveyard)
                                        .owned_by(PlayerFilter::You),
                                ))],
                            ))
                            .build();
                            let source = game.create_object_from_definition(
                                &definition,
                                holder,
                                Zone::Battlefield,
                            );
                            let stable = game.object(source).unwrap().stable_id;
                            let instruction = game.create_object_from_definition(
                                &CardDefinitionBuilder::new(
                                    CardId::new(),
                                    "Emblem test instruction",
                                )
                                .card_types(vec![CardType::Artifact])
                                .build(),
                                actor,
                                Zone::Battlefield,
                            );
                            let resource_def = CardDefinitionBuilder::new(
                                CardId::new(),
                                "Zero-cost paired artifact",
                            )
                            .card_types(vec![CardType::Artifact])
                            .mana_cost(ManaCost::new())
                            .build();
                            let mut resources = Vec::new();
                            for _ in 0..amount {
                                let id = game.create_object_from_definition(
                                    &resource_def,
                                    holder,
                                    Zone::Graveyard,
                                );
                                resources.push(game.object(id).unwrap().stable_id);
                            }
                            let other = PlayerId::from_index(1 - holder.index() as u8);
                            let foreign = game.create_object_from_definition(
                                &resource_def,
                                other,
                                Zone::Graveyard,
                            );
                            let unrelated = game.create_object_from_definition(
                                &CardDefinitionBuilder::new(
                                    CardId::new(),
                                    "Unrelated legacy exile land",
                                )
                                .card_types(vec![CardType::Land])
                                .build(),
                                holder,
                                Zone::Graveyard,
                            );
                            let unrelated_stable = game.object(unrelated).unwrap().stable_id;
                            if noise {
                                let action = LegalAction::ActivateAbility {
                                    source,
                                    ability_index: 2,
                                };
                                assert!(
                                    ironsmith::compute_legal_actions(&game, holder)
                                        .unwrap()
                                        .contains(&action)
                                );
                                cr_audit_complete_priority_action(&mut game, holder, action)
                                    .unwrap();
                                ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                            }
                            game.stack.push(StackEntry::ability(
                                instruction,
                                actor,
                                vec![Effect::new(TapEffect::with_spec(
                                    ChooseSpec::SpecificObject(source),
                                ))],
                            ));
                            ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                            let mut queue = TriggerQueue::new();
                            ironsmith::put_triggers_on_stack(&mut game, &mut queue).unwrap();
                            assert_eq!(game.stack.len(), 1);
                            let owner = game
                                .stack
                                .last()
                                .unwrap()
                                .linked_exile_owner
                                .clone()
                                .expect("actual producer admission");
                            assert_eq!(owner.host, source);
                            assert_eq!(owner.pair, pair);
                            ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                            assert_eq!(
                                game.linked_exile_pair_members(&owner).unwrap().len(),
                                amount as usize
                            );
                            let action = LegalAction::ActivateAbility {
                                source,
                                ability_index: 1,
                            };
                            assert!(
                                ironsmith::compute_legal_actions(&game, holder)
                                    .unwrap()
                                    .contains(&action)
                            );
                            cr_audit_complete_priority_action(&mut game, holder, action).unwrap();
                            assert_eq!(
                                game.stack.last().unwrap().linked_exile_owner.as_ref(),
                                Some(&owner)
                            );
                            ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                            let emblems: Vec<_> = game
                                .command_zone
                                .iter()
                                .copied()
                                .filter(|id| {
                                    game.object(*id).unwrap().kind
                                        == ironsmith::object::ObjectKind::Emblem
                                })
                                .collect();
                            assert_eq!(emblems.len(), 1);
                            let emblem = emblems[0];
                            assert_eq!(game.object(emblem).unwrap().owner, holder);
                            assert!(
                                game.object(emblem)
                                    .unwrap()
                                    .abilities
                                    .iter()
                                    .all(|ability| ability.functions_in(&Zone::Command))
                            );
                            if departure > 0 {
                                game.stack.push(StackEntry::ability(
                                    instruction,
                                    actor,
                                    vec![Effect::new(MoveToZoneEffect::new(
                                        ChooseSpec::SpecificObject(source),
                                        Zone::Hand,
                                        false,
                                    ))],
                                ));
                                ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                                if departure == 2 {
                                    let outside = game.find_object_by_stable_id(stable).unwrap();
                                    game.stack.push(StackEntry::ability(
                                        instruction,
                                        actor,
                                        vec![Effect::new(MoveToZoneEffect::new(
                                            ChooseSpec::SpecificObject(outside),
                                            Zone::Battlefield,
                                            false,
                                        ))],
                                    ));
                                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                                    let returned = game.find_object_by_stable_id(stable).unwrap();
                                    assert_ne!(returned, source);
                                    let new_resource = game.create_object_from_definition(
                                        &resource_def,
                                        holder,
                                        Zone::Graveyard,
                                    );
                                    let new_stable = game.object(new_resource).unwrap().stable_id;
                                    game.stack.push(StackEntry::ability(
                                        instruction,
                                        actor,
                                        vec![Effect::new(TapEffect::with_spec(
                                            ChooseSpec::SpecificObject(returned),
                                        ))],
                                    ));
                                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                                    ironsmith::put_triggers_on_stack(&mut game, &mut queue)
                                        .unwrap();
                                    assert_eq!(game.stack.len(), 1);
                                    let new_owner = game
                                        .stack
                                        .last()
                                        .unwrap()
                                        .linked_exile_owner
                                        .clone()
                                        .unwrap();
                                    assert_ne!(new_owner, owner);
                                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                                    assert_eq!(
                                        game.object(
                                            game.find_object_by_stable_id(new_stable).unwrap()
                                        )
                                        .unwrap()
                                        .zone,
                                        Zone::Exile
                                    );
                                }
                            }
                            let label = format!(
                                "marked={marked} holder={holder:?} actor={actor:?} amount={amount} noise={noise} departure={departure}"
                            );
                            let actions = match ironsmith::compute_legal_actions(&game, holder) {
                                Ok(actions) => actions,
                                Err(error) => {
                                    discrepancies.push(format!(
                                        "{label}: legal play computation refused{error:?}"
                                    ));
                                    cases += 1;
                                    continue;
                                }
                            };
                            let playable: std::collections::HashSet<_> = actions
                                .iter()
                                .filter_map(|action| match action {
                                    LegalAction::CastSpell { spell_id, from_zone: Zone::Exile, .. } => Some(*spell_id),
                                    LegalAction::PlayLand { land_id } if game.object(*land_id).is_some_and(|object| object.zone == Zone::Exile) => Some(*land_id),
                                    _ => None,
                                })
                                .collect();
                            let ids: Vec<_> = resources
                                .iter()
                                .map(|stable| game.find_object_by_stable_id(*stable).unwrap())
                                .collect();
                            let mut expected: std::collections::HashSet<_> =
                                ids.iter().copied().collect();
                            let unrelated_current =
                                game.find_object_by_stable_id(unrelated_stable).unwrap();
                            // Legacy unmarked control explicitly requests the raw alias pool.
                            if !marked && noise {
                                expected.insert(unrelated_current);
                            }
                            if playable != expected {
                                discrepancies.push(format!(
                                    "{label}: actual legal plays{playable:?}, expected{expected:?}"
                                ));
                            }
                            let mut played = 0;
                            if let Some(action)=actions.iter().find(|action|matches!(action,LegalAction::CastSpell {spell_id,..} if ids.contains(spell_id))).cloned() {
                                let before=game.battlefield.clone();
                                if let Err(error) = cr_audit_complete_priority_action(&mut game,holder,action) {
                                    discrepancies.push(format!("{label}: offered emblem play refused {error}"));
                                    cases += 1;
                                    continue;
                                }
                                assert_eq!(game.stack.len(),1);
                                if let Err(error) = ironsmith::game_loop::resolve_stack_entry(&mut game) {
                                    discrepancies.push(format!("{label}: emblem-authorized spell refused resolution {error:?}"));
                                    cases += 1;
                                    continue;
                                }
                                assert_eq!(game.battlefield.len(),before.len()+1);
                                played = 1;
                            }
                            assert_eq!(game.object(foreign).unwrap().zone, Zone::Graveyard);
                            assert_eq!(game.player(holder).unwrap().life, 20);
                            assert_eq!(game.player(other).unwrap().life, 20);
                            assert_eq!(
                                game.linked_exile_pair_members(&owner).unwrap().len(),
                                amount as usize - played
                            );
                            assert!(game.stack.is_empty());
                            game.validate_zone_consistency().unwrap();
                            cases += 1;
                        }
                    }
                }
            }
        }
    }
    assert_eq!(cases, 192);
    assert!(
        discrepancies.is_empty(),
        "CR607.1d: an actual created emblem must bind its creator's exact linked collection; {} mismatches in{cases} fixtures:\n{}",
        discrepancies.len(),
        discrepancies.join("\n")
    );
}

#[test]
fn cr_114_1_2_3_4_5_emblem_creation_uses_each_recipient_and_abilities_function_in_command() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effect::EmblemDescription;
    use ironsmith::effects::{
        CreateEmblemEffect, ForPlayersEffect, GainControlEffect, MoveToZoneEffect,
    };
    use ironsmith::triggers::{Trigger, TriggerQueue};
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, Effect, LegalAction, ObjectKind, Phase, StackEntry,
        Until, Zone,
    };
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for owner in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for actor in [PlayerId::from_index(0), PlayerId::from_index(1)] {
            for each in [false, true] {
                for depart in [false, true] {
                    for gainer in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                        let mut game = GameState::new(vec!["Alice".into(), "Bob".into()], 20);
                        game.turn.active_player = actor;
                        game.turn.priority_player = Some(actor);
                        game.turn.phase = Phase::FirstMain;
                        let emblem = EmblemDescription::new(
                            "Native emblem display label",
                            "Whenever you gain life, draw a card.",
                        )
                        .with_ability(Ability::triggered(
                            Trigger::you_gain_life(),
                            vec![Effect::draw(1)],
                        ));
                        let create = Effect::new(CreateEmblemEffect::new(emblem));
                        let create = if each {
                            Effect::new(ForPlayersEffect::new(PlayerFilter::Any, vec![create]))
                        } else {
                            create
                        };
                        let source = game.create_object_from_definition(
                            &CardDefinitionBuilder::new(
                                CardId::new(),
                                "Actual emblem-creating permanent",
                            )
                            .card_types(vec![CardType::Artifact])
                            .with_ability(Ability::activated(
                                ironsmith::cost::TotalCost::free(),
                                vec![create],
                            ))
                            .build(),
                            owner,
                            Zone::Battlefield,
                        );
                        let instruction = game.create_object_from_definition(
                            &CardDefinitionBuilder::new(
                                CardId::new(),
                                "Actual life-event instruction",
                            )
                            .card_types(vec![CardType::Artifact])
                            .with_ability(Ability::activated(
                                ironsmith::cost::TotalCost::free(),
                                vec![Effect::gain_life_player(
                                    1,
                                    ChooseSpec::Player(PlayerFilter::Specific(gainer)),
                                )],
                            ))
                            .build(),
                            actor,
                            Zone::Battlefield,
                        );
                        let library_card =
                            CardDefinitionBuilder::new(CardId::new(), "Emblem draw resource")
                                .card_types(vec![CardType::Instant])
                                .build();
                        for player in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                            for _ in 0..2 {
                                game.create_object_from_definition(
                                    &library_card,
                                    player,
                                    Zone::Library,
                                );
                            }
                        }
                        if owner != actor {
                            game.stack.push(StackEntry::ability(
                                instruction,
                                actor,
                                vec![Effect::new(GainControlEffect::new(
                                    ChooseSpec::SpecificObject(source),
                                    Until::Forever,
                                ))],
                            ));
                            ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        }
                        assert_eq!(game.object(source).unwrap().owner, owner);
                        assert_eq!(game.current_controller(source), Some(actor));
                        let action = LegalAction::ActivateAbility {
                            source,
                            ability_index: 0,
                        };
                        assert!(
                            ironsmith::compute_legal_actions(&game, actor)
                                .unwrap()
                                .contains(&action)
                        );
                        cr_audit_complete_priority_action(&mut game, actor, action).unwrap();
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        let emblems: Vec<_> = game
                            .command_zone
                            .iter()
                            .copied()
                            .filter(|id| game.object(*id).unwrap().kind == ObjectKind::Emblem)
                            .collect();
                        assert_eq!(emblems.len(), if each { 2 } else { 1 });
                        let mut recipients = Vec::new();
                        for id in &emblems {
                            let object = game.object(*id).unwrap();
                            recipients.push(object.owner);
                            assert_eq!(object.zone, Zone::Command);
                            assert_eq!(game.current_controller(*id), Some(object.owner));
                            assert!(object.card.is_none());
                            assert!(!object.is_permanent());
                            assert!(
                                object.card_types.is_empty()
                                    && object.supertypes.is_empty()
                                    && object.subtypes.is_empty()
                            );
                            assert!(object.mana_cost.is_none());
                            assert!(
                                object.base_power.is_none()
                                    && object.base_toughness.is_none()
                                    && object.base_loyalty.is_none()
                                    && object.base_defense.is_none()
                            );
                            assert!(game.current_colors(*id).unwrap().is_empty());
                            assert_eq!(object.abilities.len(), 1);
                            assert!(object.abilities[0].functions_in(&Zone::Command));
                            assert!(!game.battlefield.contains(id));
                        }
                        recipients.sort();
                        let mut required = if each {
                            vec![PlayerId::from_index(0), PlayerId::from_index(1)]
                        } else {
                            vec![actor]
                        };
                        required.sort();
                        assert_eq!(recipients, required);
                        if depart {
                            game.stack.push(StackEntry::ability(
                                instruction,
                                actor,
                                vec![Effect::new(MoveToZoneEffect::new(
                                    ChooseSpec::SpecificObject(source),
                                    Zone::Hand,
                                    false,
                                ))],
                            ));
                            ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        }
                        let action = LegalAction::ActivateAbility {
                            source: instruction,
                            ability_index: 0,
                        };
                        assert!(
                            ironsmith::compute_legal_actions(&game, actor)
                                .unwrap()
                                .contains(&action)
                        );
                        cr_audit_complete_priority_action(&mut game, actor, action).unwrap();
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        for player in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                            assert_eq!(
                                game.player(player).unwrap().life,
                                20 + i32::from(player == gainer)
                            );
                        }
                        let mut queue = TriggerQueue::new();
                        ironsmith::put_triggers_on_stack(&mut game, &mut queue).unwrap();
                        let expected = usize::from(each || gainer == actor);
                        let actual = game.stack.len();
                        let label = format!(
                            "owner={owner:?} actor={actor:?} each={each} depart={depart} gainer={gainer:?}"
                        );
                        if actual != expected {
                            discrepancies.push(format!(
                                "{label}: Command-zone trigger count{actual}, expected{expected}"
                            ));
                        }
                        for entry in &game.stack {
                            assert!(emblems.contains(&entry.object_id));
                        }
                        for _ in 0..actual {
                            ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        }
                        for player in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                            let expected_draw = if player == gainer { expected } else { 0 };
                            let actual_draw = game.player(player).unwrap().hand.len();
                            // A departed creator card is an additional hand card
                            // belonging to its original owner, not an emblem draw.
                            let creator_card = usize::from(depart && player == owner);
                            if actual_draw != expected_draw + creator_card {
                                discrepancies.push(format!("{label}: player{player:?} hand{actual_draw}, expected{} (draw{expected_draw}+creator{creator_card})",expected_draw+creator_card));
                            }
                        }
                        assert_eq!(
                            game.command_zone
                                .iter()
                                .filter(|id| emblems.contains(id))
                                .count(),
                            emblems.len()
                        );
                        assert!(game.stack.is_empty());
                        game.validate_zone_consistency().unwrap();
                        cases += 1;
                    }
                }
            }
        }
    }
    assert_eq!(cases, 32);
    assert!(
        discrepancies.is_empty(),
        "CR114.1-5: real emblem recipients and command-zone abilities must remain independent of the creator; {} mismatches in{cases} fixtures:\n{}",
        discrepancies.len(),
        discrepancies.join("\n")
    );
}
fn check_stack_target_predicates_after_player_departure(mode: usize) {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::LoseTheGameEffect;
    use ironsmith::triggers::TriggerQueue;
    use ironsmith::{
        CardId, CardType, ChooseSpec, Effect, LegalAction, ManaCost, ObjectFilter, Phase,
        StackEntry, Target, Value, Zone,
    };
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for caster in [PlayerId::from_index(0), PlayerId::from_index(2)] {
        for victim in [PlayerId::from_index(1), PlayerId::from_index(3)] {
            for card_type in [CardType::Instant, CardType::Sorcery] {
                for departed in [false, true] {
                    let mut game =
                        GameState::new(vec!["A".into(), "B".into(), "C".into(), "D".into()], 20);
                    game.turn.active_player = caster;
                    game.turn.priority_player = Some(caster);
                    game.turn.phase = Phase::FirstMain;
                    let target =
                        ChooseSpec::target(ChooseSpec::Player(PlayerFilter::Specific(victim)));
                    let definition = CardDefinitionBuilder::new(
                        CardId::new(),
                        "A genuinely targeted waiting spell",
                    )
                    .card_types(vec![card_type])
                    .mana_cost(ManaCost::new())
                    .with_spell_effect(vec![Effect::gain_life_player(1, target)])
                    .build();
                    let card = game.create_object_from_definition(&definition, caster, Zone::Hand);
                    let instruction = game.create_object_from_definition(
                        &CardDefinitionBuilder::new(
                            CardId::new(),
                            "Target-query and player-loss instruction",
                        )
                        .card_types(vec![CardType::Artifact])
                        .build(),
                        caster,
                        Zone::Battlefield,
                    );
                    let action=ironsmith::compute_legal_actions(&game,caster).unwrap().into_iter().find(|action|matches!(action,LegalAction::CastSpell {spell_id,..} if *spell_id==card)).expect("zero-cost targeted spell must be legally castable");
                    cr_audit_complete_priority_action(&mut game, caster, action).unwrap();
                    assert_eq!(game.stack.len(), 1);
                    let spell = game.stack.last().unwrap().object_id;
                    assert_eq!(game.object(spell).unwrap().zone, Zone::Stack);
                    assert_eq!(game.stack.last().unwrap().controller, caster);
                    assert_eq!(
                        game.stack.last().unwrap().targets,
                        vec![Target::Player(victim)],
                        "The cast must actually choose the sole eligible player; no target vector is injected"
                    );
                    if departed {
                        game.stack.push(StackEntry::ability(
                            instruction,
                            caster,
                            vec![Effect::new(LoseTheGameEffect::new(PlayerFilter::Specific(
                                victim,
                            )))],
                        ));
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        let mut queue = TriggerQueue::new();
                        ironsmith::game_loop::check_and_apply_sbas(&mut game, &mut queue).unwrap();
                        assert!(
                            game.player(victim).unwrap().has_lost
                                && game.player(victim).unwrap().has_left_game
                        );
                    }
                    assert_eq!(game.player(victim).unwrap().is_in_game(), !departed);
                    assert!(game.player(caster).unwrap().is_in_game());
                    assert_eq!(game.players_in_game(), if departed { 3 } else { 4 });
                    assert_eq!(game.stack.len(), 1);
                    assert_eq!(game.stack.last().unwrap().object_id, spell);
                    assert_eq!(
                        game.stack.last().unwrap().targets,
                        vec![Target::Player(victim)]
                    );
                    let mut queries = Vec::new();
                    if mode == 0 {
                        queries.push((
                            "targets any player",
                            ObjectFilter::spell().targeting(Some(PlayerFilter::Any), None),
                            i32::from(!departed),
                        ));
                        queries.push((
                            "targets that player",
                            ObjectFilter::spell()
                                .targeting(Some(PlayerFilter::Specific(victim)), None),
                            i32::from(!departed),
                        ));
                    } else if mode == 1 {
                        queries.push((
                            "targets only that player",
                            ObjectFilter::spell()
                                .targeting_only_player(PlayerFilter::Specific(victim)),
                            i32::from(!departed),
                        ));
                    }
                    // CR115.9a counts the original chosen occurrences, including
                    // now-illegal player references; it must not be erased.
                    queries.push((
                        "one originally chosen target",
                        ObjectFilter::spell().target_count_exact(1),
                        1,
                    ));
                    for (query, filter, expected) in queries {
                        let before = game.player(caster).unwrap().life;
                        game.stack.push(StackEntry::ability(
                            instruction,
                            caster,
                            vec![Effect::gain_life(Value::Count(filter))],
                        ));
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        let actual = game.player(caster).unwrap().life - before;
                        if actual != expected {
                            discrepancies.push(format!("mode={mode} caster={caster:?} victim={victim:?} card_type={card_type:?} departed={departed} query={query}: resolved count{actual}, expected{expected}"));
                        }
                        assert_eq!(game.stack.len(), 1);
                        assert_eq!(game.stack.last().unwrap().object_id, spell);
                        assert_eq!(
                            game.stack.last().unwrap().targets,
                            vec![Target::Player(victim)]
                        );
                    }
                    if !departed {
                        assert_eq!(game.player(victim).unwrap().life, 20);
                    }
                    game.validate_zone_consistency().unwrap();
                    cases += 1;
                }
            }
        }
    }
    assert_eq!(cases, 16);
    assert!(
        discrepancies.is_empty(),
        "CR115.9a/b/c: live targeting predicates must ignore departed players while original target counts remain; {} mismatches in{cases} fixtures:\n{}",
        discrepancies.len(),
        discrepancies.join("\n")
    );
}

#[test]
fn cr_115_9b_targeting_predicates_ignore_players_who_left_the_game() {
    check_stack_target_predicates_after_player_departure(0);
}

#[test]
fn cr_115_9c_only_target_predicates_ignore_a_single_departed_player() {
    check_stack_target_predicates_after_player_departure(1);
}

#[test]
fn cr_115_9a_target_count_retains_chosen_occurrences_after_player_departure() {
    check_stack_target_predicates_after_player_departure(2);
}
fn check_ability_target_predicates_after_player_departure(mode: usize) {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::{CounterEffect, LoseTheGameEffect, TapEffect};
    use ironsmith::triggers::{Trigger, TriggerQueue};
    use ironsmith::{
        Ability, AbilityKind, CardId, CardType, ChooseSpec, Effect, LegalAction, ObjectFilter,
        Phase, StackEntry, Target, Zone,
    };
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for caster in [PlayerId::from_index(0), PlayerId::from_index(2)] {
        for victim in [PlayerId::from_index(1), PlayerId::from_index(3)] {
            for triggered in [false, true] {
                for departed in [false, true] {
                    let mut game =
                        GameState::new(vec!["A".into(), "B".into(), "C".into(), "D".into()], 20);
                    game.turn.active_player = caster;
                    game.turn.priority_player = Some(caster);
                    game.turn.phase = Phase::FirstMain;
                    let player_target =
                        ChooseSpec::target(ChooseSpec::Player(PlayerFilter::Specific(victim)));
                    let effects = vec![Effect::gain_life_player(1, player_target.clone())];
                    let mut producer = if triggered {
                        Ability::triggered(Trigger::becomes_tapped(), effects)
                    } else {
                        Ability::activated(ironsmith::cost::TotalCost::free(), effects)
                    };
                    // Native declaration of an authored target requirement, not
                    // a supplied chosen target or runtime admission record.
                    match &mut producer.kind {
                        AbilityKind::Activated(ability) => ability.choices = vec![player_target],
                        AbilityKind::Triggered(ability) => ability.choices = vec![player_target],
                        _ => unreachable!(),
                    }
                    let filter = match mode {
                        0 => ObjectFilter::ability()
                            .targeting(Some(PlayerFilter::Specific(victim)), None),
                        1 => ObjectFilter::ability()
                            .targeting_only_player(PlayerFilter::Specific(victim)),
                        _ => ObjectFilter::ability().target_count_exact(1),
                    };
                    let counter_target = ChooseSpec::target(ChooseSpec::Object(filter));
                    let mut counter = Ability::activated(
                        ironsmith::cost::TotalCost::free(),
                        vec![Effect::new(CounterEffect::new(counter_target.clone()))],
                    );
                    let AbilityKind::Activated(counter_ability) = &mut counter.kind else {
                        unreachable!()
                    };
                    counter_ability.choices = vec![counter_target.clone()];
                    let source = game.create_object_from_definition(
                        &CardDefinitionBuilder::new(
                            CardId::new(),
                            "Actual producer and predicate-constrained counter",
                        )
                        .card_types(vec![CardType::Artifact])
                        .with_ability(producer)
                        .with_ability(counter)
                        .build(),
                        caster,
                        Zone::Battlefield,
                    );
                    let instruction = game.create_object_from_definition(
                        &CardDefinitionBuilder::new(
                            CardId::new(),
                            "Actual ability-query loss instruction",
                        )
                        .card_types(vec![CardType::Artifact])
                        .build(),
                        caster,
                        Zone::Battlefield,
                    );
                    if triggered {
                        game.stack.push(StackEntry::ability(
                            instruction,
                            caster,
                            vec![Effect::new(TapEffect::with_spec(
                                ChooseSpec::SpecificObject(source),
                            ))],
                        ));
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        assert!(game.stack.is_empty());
                        let mut queue = TriggerQueue::new();
                        ironsmith::put_triggers_on_stack(&mut game, &mut queue).unwrap();
                    } else {
                        let action = LegalAction::ActivateAbility {
                            source,
                            ability_index: 0,
                        };
                        assert!(
                            ironsmith::compute_legal_actions(&game, caster)
                                .unwrap()
                                .contains(&action)
                        );
                        cr_audit_complete_priority_action(&mut game, caster, action).unwrap();
                    }
                    assert_eq!(game.stack.len(), 1);
                    let waiting = game.stack.last().unwrap().target_id();
                    assert!(game.stack.last().unwrap().ability_id.is_some());
                    assert_ne!(waiting, source);
                    assert_eq!(game.stack.last().unwrap().object_id, source);
                    assert_eq!(
                        game.stack.last().unwrap().targets,
                        vec![Target::Player(victim)]
                    );
                    if departed {
                        game.stack.push(StackEntry::ability(
                            instruction,
                            caster,
                            vec![Effect::new(LoseTheGameEffect::new(PlayerFilter::Specific(
                                victim,
                            )))],
                        ));
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        let mut queue = TriggerQueue::new();
                        ironsmith::game_loop::check_and_apply_sbas(&mut game, &mut queue).unwrap();
                        assert!(
                            game.player(victim).unwrap().has_lost
                                && game.player(victim).unwrap().has_left_game
                        );
                    }
                    assert_eq!(game.player(victim).unwrap().is_in_game(), !departed);
                    assert_eq!(game.stack.len(), 1);
                    assert_eq!(game.stack.last().unwrap().target_id(), waiting);
                    assert_eq!(
                        game.stack.last().unwrap().targets,
                        vec![Target::Player(victim)]
                    );
                    let legal = ironsmith::game_loop::compute_legal_targets(
                        &game,
                        &counter_target,
                        caster,
                        Some(source),
                    );
                    let expected = !departed || mode == 2;
                    let required = if expected {
                        vec![Target::Object(waiting)]
                    } else {
                        vec![]
                    };
                    let label = format!(
                        "mode={mode} caster={caster:?} victim={victim:?} triggered={triggered} departed={departed}"
                    );
                    if legal != required {
                        discrepancies.push(format!(
                            "{label}: actual ability targets{legal:?}, expected{required:?}"
                        ));
                    }
                    let action = LegalAction::ActivateAbility {
                        source,
                        ability_index: 1,
                    };
                    let offered = ironsmith::compute_legal_actions(&game, caster)
                        .unwrap()
                        .contains(&action);
                    if offered != expected {
                        discrepancies.push(format!("{label}: predicate-constrained counter offered{offered}, expected{expected}"));
                    }
                    if expected && offered {
                        cr_audit_complete_priority_action(&mut game, caster, action).unwrap();
                        assert_eq!(game.stack.len(), 2);
                        assert_eq!(
                            game.stack.last().unwrap().targets,
                            vec![Target::Object(waiting)]
                        );
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        assert!(
                            game.stack.is_empty(),
                            "Actual control counter must remove the ability, not its permanent source"
                        );
                        assert_eq!(game.object(source).unwrap().zone, Zone::Battlefield);
                    }
                    for player in &game.players {
                        if player.is_in_game() {
                            assert_eq!(player.life, 20);
                        }
                    }
                    game.validate_zone_consistency().unwrap();
                    cases += 1;
                }
            }
        }
    }
    assert_eq!(cases, 16);
    assert!(
        discrepancies.is_empty(),
        "CR115.9a/b/c: actual ability-target predicates must ignore departed players but retain original occurrence counts; {} mismatches in{cases} fixtures:\n{}",
        discrepancies.len(),
        discrepancies.join("\n")
    );
}

#[test]
fn cr_115_9b_ability_targeting_predicates_ignore_departed_players() {
    check_ability_target_predicates_after_player_departure(0);
}

#[test]
fn cr_115_9c_ability_only_target_predicates_ignore_departed_players() {
    check_ability_target_predicates_after_player_departure(1);
}

#[test]
fn cr_115_9a_ability_original_target_count_survives_player_departure() {
    check_ability_target_predicates_after_player_departure(2);
}
fn cr_audit_complete_priority_action_with_dm<D: DecisionMaker>(
    game: &mut GameState,
    player: PlayerId,
    action: ironsmith::LegalAction,
    dm: &mut D,
    queue: &mut ironsmith::triggers::TriggerQueue,
) -> Result<(), String> {
    use ironsmith::{PriorityLoopState, PriorityResponse};
    let requested_method = match &action {
        ironsmith::LegalAction::CastSpell { casting_method, .. } => Some(casting_method.clone()),
        _ => None,
    };
    let mut state = PriorityLoopState::new(game.players_in_game());
    assert_eq!(game.turn.priority_player, Some(player));
    let mut result = ironsmith::game_loop::apply_priority_response_with_dm(
        game,
        queue,
        &mut state,
        &PriorityResponse::PriorityAction(action),
        dm,
    );
    for _ in 0..16 {
        if result.is_err()
            || (state.pending_cast.is_none()
                && state.pending_method_selection.is_none()
                && state.pending_activation.is_none())
        {
            break;
        }
        if let Some(pending) = &state.pending_method_selection {
            let index = pending
                .available_methods
                .iter()
                .position(|choice| Some(&choice.method) == requested_method.as_ref())
                .ok_or_else(|| {
                    "requested casting method lost during method selection".to_string()
                })?;
            result = ironsmith::game_loop::apply_priority_response_with_dm(
                game,
                queue,
                &mut state,
                &PriorityResponse::CastingMethodChoice(index),
                dm,
            );
        } else {
            let context = match &result {
                Ok(ironsmith::decision::GameProgress::NeedsDecisionCtx(context)) => context.clone(),
                other => return Err(format!("pending native action has no decision: {other:?}")),
            };
            result = ironsmith::game_loop::apply_decision_context_with_dm(
                game, queue, &mut state, &context, dm,
            );
        }
    }
    result.map_err(|error| format!("{error:?}"))?;
    if state.pending_cast.is_some()
        || state.pending_method_selection.is_some()
        || state.pending_activation.is_some()
    {
        return Err("native action exceeded decision bound".into());
    }
    Ok(())
}


#[test]
fn cr_115_3_115_9a_c_source_only_predicate_accepts_repeated_selection_of_its_source() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::decisions::context::TargetsContext;
    use ironsmith::effects::PutCountersEffect;
    use ironsmith::triggers::TriggerQueue;
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, CounterType, Effect, LegalAction, ManaCost,
        ObjectFilter, ObjectId, Phase, Target, Value, Zone,
    };
    struct ChooseCreature {
        source: ObjectId,
        other: ObjectId,
        split: bool,
        requirements: usize,
        issues: Vec<String>,
    }
    impl DecisionMaker for ChooseCreature {
        fn decide_targets(&mut self, _: &GameState, ctx: &TargetsContext) -> Vec<Target> {
            let mut selected = Vec::new();
            self.requirements += ctx.requirements.len();
            for requirement in &ctx.requirements {
                if requirement.min_targets != 1 || requirement.max_targets != Some(1) {
                    self.issues.push(format!(
                        "unexpected target requirement {}..{:?}",
                        requirement.min_targets, requirement.max_targets
                    ));
                }
                let wanted = if self.split
                    && requirement
                        .legal_targets
                        .contains(&Target::Object(self.other))
                {
                    Target::Object(self.other)
                } else {
                    Target::Object(self.source)
                };
                if requirement.legal_targets.contains(&wanted) {
                    selected.push(wanted);
                } else {
                    self.issues.push(format!(
                        "required choice{wanted:?} absent from{:?}",
                        requirement.legal_targets
                    ));
                    if let Some(fallback) = requirement.legal_targets.first() {
                        selected.push(*fallback);
                    }
                }
            }
            selected
        }
    }
    // Compile the real wording. A hand-authored literal target_count(1)
    // would test bad fixture data and survive a compiler-only fix.
    let observer_definition=ironsmith_compiler_runtime::compile_to_runtime_definition(
        "Only-source observer",
        "Mana cost: {0}\nType: Creature — Wizard\nPower/Toughness: 2/8\nWhenever you cast an instant or sorcery spell, if that spell targets only this creature, you gain 1 life.",
        false,
    ).expect("strict production compiler/runtime bridge must accept the observer");
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for caster in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for card_type in [CardType::Instant, CardType::Sorcery] {
            for pattern in 0..4 {
                let mut game = GameState::new(vec!["A".into(), "B".into()], 20);
                game.turn.active_player = caster;
                game.turn.priority_player = Some(caster);
                game.turn.phase = Phase::FirstMain;
                let source = game.create_object_from_definition(
                    &observer_definition,
                    caster,
                    Zone::Battlefield,
                );
                let other = game.create_object_from_definition(
                    &CardDefinitionBuilder::new(CardId::new(), "Other eligible creature")
                        .card_types(vec![CardType::Creature])
                        .power_toughness(ironsmith::PowerToughness::fixed(2, 8))
                        .build(),
                    caster,
                    Zone::Battlefield,
                );
                let filters = vec![
                    ObjectFilter::spell().targeting_only_object(ObjectFilter::specific(source)),
                    ObjectFilter::spell().target_count_exact(1),
                    ObjectFilter::spell().target_count_exact(2),
                    ObjectFilter::spell().target_count_exact(0),
                ];
                let mut query_def = CardDefinitionBuilder::new(
                    CardId::new(),
                    "Independent original-target and identity-only controls",
                )
                .card_types(vec![CardType::Artifact]);
                for filter in filters {
                    query_def = query_def.with_ability(Ability::activated(
                        ironsmith::cost::TotalCost::free(),
                        vec![Effect::gain_life(Value::Count(filter))],
                    ));
                }
                let query_source = game.create_object_from_definition(
                    &query_def.build(),
                    caster,
                    Zone::Battlefield,
                );
                let any = ChooseSpec::target(ChooseSpec::Object(ObjectFilter::creature()));
                let this = ChooseSpec::target(ChooseSpec::Object(ObjectFilter::specific(source)));
                let effects = match pattern {
                    0 => vec![Effect::gain_life(1)],
                    1 => vec![Effect::new(PutCountersEffect::new(
                        CounterType::Charge,
                        1,
                        this,
                    ))],
                    _ => vec![
                        Effect::new(PutCountersEffect::new(CounterType::Charge, 1, any)),
                        Effect::new(PutCountersEffect::new(CounterType::Charge, 1, this)),
                    ],
                };
                let card = game.create_object_from_definition(
                    &CardDefinitionBuilder::new(
                        CardId::new(),
                        "Independent target words for a source-only query",
                    )
                    .card_types(vec![card_type])
                    .mana_cost(ManaCost::new())
                    .with_spell_effect(effects)
                    .build(),
                    caster,
                    Zone::Hand,
                );
                let stable = game.object(card).unwrap().stable_id;
                let label = format!("caster={caster:?} card_type={card_type:?} pattern={pattern}");
                let Some(action)=ironsmith::compute_legal_actions(&game,caster).unwrap().into_iter().find(|action|matches!(action,LegalAction::CastSpell {spell_id,..} if *spell_id==card)) else {
                    discrepancies.push(format!("{label}: valid authored cast missing from legal actions"));cases+=1;continue;
                };
                let mut dm = ChooseCreature {
                    source,
                    other,
                    split: pattern == 3,
                    requirements: 0,
                    issues: vec![],
                };
                let mut queue = TriggerQueue::new();
                if let Err(error) = cr_audit_complete_priority_action_with_dm(
                    &mut game, caster, action, &mut dm, &mut queue,
                ) {
                    discrepancies.push(format!(
                        "{label}: native cast rejected{error}; menu issues{:?}",
                        dm.issues
                    ));
                    cases += 1;
                    continue;
                }
                let spell = game.find_object_by_stable_id(stable).unwrap();
                assert_eq!(game.object(spell).unwrap().zone, Zone::Stack);
                let entry = game
                    .stack
                    .iter()
                    .find(|entry| entry.object_id == spell)
                    .unwrap();
                let mut chosen = entry.targets.clone();
                let mut expected_chosen = match pattern {
                    0 => vec![],
                    1 => vec![Target::Object(source)],
                    2 => vec![Target::Object(source), Target::Object(source)],
                    _ => vec![Target::Object(other), Target::Object(source)],
                };
                chosen.sort_by_key(|target| format!("{target:?}"));
                expected_chosen.sort_by_key(|target| format!("{target:?}"));
                if chosen != expected_chosen
                    || dm.requirements != expected_chosen.len()
                    || !dm.issues.is_empty()
                {
                    discrepancies.push(format!("{label}: actual declaration{chosen:?}, expected{expected_chosen:?}; requirements{}, issues{:?}",dm.requirements,dm.issues));
                    cases += 1;
                    continue;
                }
                ironsmith::put_triggers_on_stack(&mut game, &mut queue).unwrap();
                let expected_trigger = usize::from(pattern == 1 || pattern == 2);
                let actual_triggers = game
                    .stack
                    .iter()
                    .filter(|entry| entry.object_id == source)
                    .count();
                assert_eq!(game.stack.len(), 1 + actual_triggers);
                if actual_triggers != expected_trigger {
                    discrepancies.push(format!("{label}: production compiled trigger count{actual_triggers}, expected{expected_trigger}"));
                }
                let before = game.player(caster).unwrap().life;
                for _ in 0..actual_triggers {
                    assert_eq!(game.stack.last().unwrap().object_id, source);
                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                }
                let actual_gain = game.player(caster).unwrap().life - before;
                if actual_gain != expected_trigger as i32 {
                    discrepancies.push(format!("{label}: production compiled trigger gain{actual_gain}, expected{expected_trigger}"));
                }
                assert_eq!(game.stack.len(), 1);
                assert_eq!(game.stack.last().unwrap().object_id, spell);
                let expected = [
                    pattern == 1 || pattern == 2,
                    pattern == 1,
                    pattern == 2 || pattern == 3,
                    pattern == 0,
                ];
                for (index, wanted) in expected.into_iter().enumerate() {
                    let before = game.player(caster).unwrap().life;
                    let action = LegalAction::ActivateAbility {
                        source: query_source,
                        ability_index: index,
                    };
                    if !ironsmith::compute_legal_actions(&game, caster)
                        .unwrap()
                        .contains(&action)
                    {
                        discrepancies.push(format!(
                            "{label}: valid query activation{index} not offered"
                        ));
                        continue;
                    }
                    cr_audit_complete_priority_action(&mut game, caster, action).unwrap();
                    assert_eq!(game.stack.len(), 2);
                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                    let actual = game.player(caster).unwrap().life - before;
                    if actual != i32::from(wanted) {
                        discrepancies.push(format!(
                            "{label}: independent query{index} gain{actual}, expected{}",
                            i32::from(wanted)
                        ));
                    }
                    assert_eq!(game.stack.len(), 1);
                    assert_eq!(game.stack.last().unwrap().object_id, spell);
                    assert_eq!(
                        game.stack.last().unwrap().targets.len(),
                        expected_chosen.len()
                    );
                }
                assert_eq!(game.counter_count(source, CounterType::Charge), 0);
                assert_eq!(game.counter_count(other, CounterType::Charge), 0);
                assert_eq!(
                    game.player(PlayerId::from_index(1 - caster.index() as u8))
                        .unwrap()
                        .life,
                    20
                );
                game.validate_zone_consistency().unwrap();
                cases += 1;
            }
        }
    }
    assert_eq!(cases, 16);
    assert!(
        discrepancies.is_empty(),
        "CR115.3/115.9a/c: production source-only predicates count distinct targets while literal target counts retain each chosen occurrence; {} mismatches in{cases} fixtures:\n{}",
        discrepancies.len(),
        discrepancies.join("\n")
    );
}


#[test]
fn cr_115_9c_single_other_creature_accepts_repeated_targets_from_either_caster() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::decisions::context::TargetsContext;
    use ironsmith::effects::PutCountersEffect;
    use ironsmith::triggers::TriggerQueue;
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, CounterType, Effect, LegalAction, ManaCost,
        ObjectFilter, ObjectId, Phase, Target, Value, Zone,
    };
    struct ChooseCreature {
        source: ObjectId,
        other: ObjectId,
        observer: ObjectId,
        self_only: bool,
        split: bool,
        requirements: usize,
        issues: Vec<String>,
    }
    impl DecisionMaker for ChooseCreature {
        fn decide_targets(&mut self, _: &GameState, ctx: &TargetsContext) -> Vec<Target> {
            let mut selected = Vec::new();
            self.requirements += ctx.requirements.len();
            for requirement in &ctx.requirements {
                if requirement.min_targets != 1 || requirement.max_targets != Some(1) {
                    self.issues.push(format!(
                        "unexpected target requirement {}..{:?}",
                        requirement.min_targets, requirement.max_targets
                    ));
                }
                let wanted = if self.self_only { Target::Object(self.observer) } else if self.split
                    && requirement
                        .legal_targets
                        .contains(&Target::Object(self.other))
                {
                    Target::Object(self.other)
                } else {
                    Target::Object(self.source)
                };
                if requirement.legal_targets.contains(&wanted) {
                    selected.push(wanted);
                } else {
                    self.issues.push(format!(
                        "required choice{wanted:?} absent from{:?}",
                        requirement.legal_targets
                    ));
                    if let Some(fallback) = requirement.legal_targets.first() {
                        selected.push(*fallback);
                    }
                }
            }
            selected
        }
    }
    // Compile the real wording. A hand-authored literal target_count(1)
    // would test bad fixture data and survive a compiler-only fix.
    let observer_definition=ironsmith_compiler_runtime::compile_to_runtime_definition(
        "Single-other observer",
        "Mana cost: {0}\nType: Creature — Wizard\nPower/Toughness: 2/8\nWhenever a player casts a spell that targets only a single creature other than this creature, you gain 1 life.",
        false,
    ).expect("strict production compiler/runtime bridge must accept the observer");
    let mut cases = 0;
    let mut discrepancies = Vec::new();
    for caster in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for observer_owner in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for card_type in [CardType::Instant, CardType::Sorcery] {
            for pattern in 0..5 {
                let mut game = GameState::new(vec!["A".into(), "B".into()], 20);
                game.turn.active_player = caster;
                game.turn.priority_player = Some(caster);
                game.turn.phase = Phase::FirstMain;
                let observer = game.create_object_from_definition(
                    &observer_definition,
                    observer_owner,
                    Zone::Battlefield,
                );
                let source = game.create_object_from_definition(
                    &CardDefinitionBuilder::new(CardId::new(), "Eligible single target")
                        .card_types(vec![CardType::Creature])
                        .power_toughness(ironsmith::PowerToughness::fixed(2, 8))
                        .build(),
                    caster,
                    Zone::Battlefield,
                );
                let other = game.create_object_from_definition(
                    &CardDefinitionBuilder::new(CardId::new(), "Other eligible creature")
                        .card_types(vec![CardType::Creature])
                        .power_toughness(ironsmith::PowerToughness::fixed(2, 8))
                        .build(),
                    caster,
                    Zone::Battlefield,
                );
                let filters = vec![
                    ObjectFilter::spell().targeting_only_object(ObjectFilter::specific(source)),
                    ObjectFilter::spell().target_count_exact(1),
                    ObjectFilter::spell().target_count_exact(2),
                    ObjectFilter::spell().target_count_exact(0),
                ];
                let mut query_def = CardDefinitionBuilder::new(
                    CardId::new(),
                    "Independent original-target and identity-only controls",
                )
                .card_types(vec![CardType::Artifact]);
                for filter in filters {
                    query_def = query_def.with_ability(Ability::activated(
                        ironsmith::cost::TotalCost::free(),
                        vec![Effect::gain_life(Value::Count(filter))],
                    ));
                }
                let query_source = game.create_object_from_definition(
                    &query_def.build(),
                    caster,
                    Zone::Battlefield,
                );
                let any = ChooseSpec::target(ChooseSpec::Object(ObjectFilter::creature()));
                let this = ChooseSpec::target(ChooseSpec::Object(ObjectFilter::specific(source)));
                let effects = match pattern {
                    0 => vec![Effect::gain_life(1)],
                    1 => vec![Effect::new(PutCountersEffect::new(
                        CounterType::Charge,
                        1,
                        this,
                    ))],
                    4 => vec![Effect::new(PutCountersEffect::new(CounterType::Charge, 1,
                        ChooseSpec::target(ChooseSpec::Object(ObjectFilter::specific(observer)))))],
                    _ => vec![
                        Effect::new(PutCountersEffect::new(CounterType::Charge, 1, any)),
                        Effect::new(PutCountersEffect::new(CounterType::Charge, 1, this)),
                    ],
                };
                let card = game.create_object_from_definition(
                    &CardDefinitionBuilder::new(
                        CardId::new(),
                        "Independent target words for a source-only query",
                    )
                    .card_types(vec![card_type])
                    .mana_cost(ManaCost::new())
                    .with_spell_effect(effects)
                    .build(),
                    caster,
                    Zone::Hand,
                );
                let stable = game.object(card).unwrap().stable_id;
                let label = format!("caster={caster:?} observer_owner={observer_owner:?} card_type={card_type:?} pattern={pattern}");
                let Some(action)=ironsmith::compute_legal_actions(&game,caster).unwrap().into_iter().find(|action|matches!(action,LegalAction::CastSpell {spell_id,..} if *spell_id==card)) else {
                    discrepancies.push(format!("{label}: valid authored cast missing from legal actions"));cases+=1;continue;
                };
                let mut dm = ChooseCreature {
                    source,
                    other,
                    observer,
                    self_only: pattern == 4,
                    split: pattern == 3,
                    requirements: 0,
                    issues: vec![],
                };
                let mut queue = TriggerQueue::new();
                if let Err(error) = cr_audit_complete_priority_action_with_dm(
                    &mut game, caster, action, &mut dm, &mut queue,
                ) {
                    discrepancies.push(format!(
                        "{label}: native cast rejected{error}; menu issues{:?}",
                        dm.issues
                    ));
                    cases += 1;
                    continue;
                }
                let spell = game.find_object_by_stable_id(stable).unwrap();
                assert_eq!(game.object(spell).unwrap().zone, Zone::Stack);
                let entry = game
                    .stack
                    .iter()
                    .find(|entry| entry.object_id == spell)
                    .unwrap();
                let mut chosen = entry.targets.clone();
                let mut expected_chosen = match pattern {
                    0 => vec![],
                    1 => vec![Target::Object(source)],
                    2 => vec![Target::Object(source), Target::Object(source)],
                    3 => vec![Target::Object(other), Target::Object(source)],
                    _ => vec![Target::Object(observer)],
                };
                chosen.sort_by_key(|target| format!("{target:?}"));
                expected_chosen.sort_by_key(|target| format!("{target:?}"));
                if chosen != expected_chosen
                    || dm.requirements != expected_chosen.len()
                    || !dm.issues.is_empty()
                {
                    discrepancies.push(format!("{label}: actual declaration{chosen:?}, expected{expected_chosen:?}; requirements{}, issues{:?}",dm.requirements,dm.issues));
                    cases += 1;
                    continue;
                }
                ironsmith::put_triggers_on_stack(&mut game, &mut queue).unwrap();
                let expected_trigger = usize::from(pattern == 1 || pattern == 2);
                let actual_triggers = game
                    .stack
                    .iter()
                    .filter(|entry| entry.object_id == observer)
                    .count();
                assert_eq!(game.stack.len(), 1 + actual_triggers);
                if actual_triggers != expected_trigger {
                    discrepancies.push(format!("{label}: production compiled trigger count{actual_triggers}, expected{expected_trigger}"));
                }
                let before = game.player(observer_owner).unwrap().life;
                for _ in 0..actual_triggers {
                    assert_eq!(game.stack.last().unwrap().object_id, observer);
                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                }
                let actual_gain = game.player(observer_owner).unwrap().life - before;
                if actual_gain != expected_trigger as i32 {
                    discrepancies.push(format!("{label}: production compiled trigger gain{actual_gain}, expected{expected_trigger}"));
                }
                assert_eq!(game.stack.len(), 1);
                assert_eq!(game.stack.last().unwrap().object_id, spell);
                let expected = [
                    pattern == 1 || pattern == 2,
                    pattern == 1 || pattern == 4,
                    pattern == 2 || pattern == 3,
                    pattern == 0,
                ];
                for (index, wanted) in expected.into_iter().enumerate() {
                    let before = game.player(caster).unwrap().life;
                    let action = LegalAction::ActivateAbility {
                        source: query_source,
                        ability_index: index,
                    };
                    if !ironsmith::compute_legal_actions(&game, caster)
                        .unwrap()
                        .contains(&action)
                    {
                        discrepancies.push(format!(
                            "{label}: valid query activation{index} not offered"
                        ));
                        continue;
                    }
                    cr_audit_complete_priority_action(&mut game, caster, action).unwrap();
                    assert_eq!(game.stack.len(), 2);
                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                    let actual = game.player(caster).unwrap().life - before;
                    if actual != i32::from(wanted) {
                        discrepancies.push(format!(
                            "{label}: independent query{index} gain{actual}, expected{}",
                            i32::from(wanted)
                        ));
                    }
                    assert_eq!(game.stack.len(), 1);
                    assert_eq!(game.stack.last().unwrap().object_id, spell);
                    assert_eq!(
                        game.stack.last().unwrap().targets.len(),
                        expected_chosen.len()
                    );
                }
                assert_eq!(game.counter_count(source, CounterType::Charge), 0);
                assert_eq!(game.counter_count(other, CounterType::Charge), 0);
                assert_eq!(
                    game.player(PlayerId::from_index(1 - caster.index() as u8))
                        .unwrap()
                        .life,
                    20 + if observer_owner != caster { actual_gain } else { 0 }
                );
                assert_eq!(game.counter_count(observer, CounterType::Charge), 0);
                game.validate_zone_consistency().unwrap();
                cases += 1;
            }
        }
    }
    }
    assert_eq!(cases, 40);
    assert!(
        discrepancies.is_empty(),
        "CR115.9c: production single-other-creature trigger counts distinct entities, with either caster and either observer controller; {} mismatches in{cases} fixtures:\n{}",
        discrepancies.len(),
        discrepancies.join("\n")
    );
}

#[test]
fn cr_115_7a_change_all_targets_is_atomic_when_one_slot_has_no_alternative() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::decisions::context::TargetsContext;
    use ironsmith::effects::{PutCountersEffect, RetargetStackObjectEffect};
    use ironsmith::triggers::TriggerQueue;
    use ironsmith::{Ability, CardId, CardType, ChooseSpec, CounterType, Effect, LegalAction,
        ManaCost, ObjectFilter, ObjectId, Phase, Target, Zone};
    struct SelectSlots { wanted: [ObjectId;2], old: [ObjectId;2], decisions: usize, issues: Vec<String> }
    impl DecisionMaker for SelectSlots {
        fn decide_targets(&mut self, _: &GameState, ctx: &TargetsContext)->Vec<Target> {
            self.decisions+=1;
            if ctx.requirements.len()!=2 { self.issues.push(format!("requirements{}",ctx.requirements.len())); }
            ctx.requirements.iter().enumerate().map(|(i,req)|{
                if req.min_targets!=1 || req.max_targets!=Some(1) { self.issues.push("non-single slot".into()); }
                let wanted=Target::Object(self.wanted[i]);let old=Target::Object(self.old[i]);
                if req.legal_targets.contains(&wanted) { wanted }
                else if req.legal_targets.contains(&old) { old }
                else { self.issues.push(format!("no intended choice in{:?}",req.legal_targets));req.legal_targets[0] }
            }).collect()
        }
    }
    let mut discrepancies=Vec::new();let mut cases=0;
    for caster in [PlayerId::from_index(0),PlayerId::from_index(1)] {
        for card_type in [CardType::Instant,CardType::Sorcery] {
            for pattern in 0..3 {
                for choose_new in [false,true] {
                    let mut game=GameState::new(vec!["A".into(),"B".into()],20);
                    game.turn.active_player=caster;game.turn.priority_player=Some(caster);game.turn.phase=Phase::FirstMain;
                    let creature=CardDefinitionBuilder::new(CardId::new(),"Retarget candidate")
                        .card_types(vec![CardType::Creature]).power_toughness(ironsmith::PowerToughness::fixed(2,8)).build();
                    let ids:Vec<_>=(0..4).map(|_|game.create_object_from_definition(&creature,caster,Zone::Battlefield)).collect();
                    let [a,b,c,d]:[ObjectId;4]=ids.clone().try_into().unwrap();
                    let first=if pattern==1 { ObjectFilter {any_of:vec![ObjectFilter::specific(a),ObjectFilter::specific(c)],..ObjectFilter::default()} } else {ObjectFilter::specific(a)};
                    let second=if pattern==2 {ObjectFilter::specific(b)} else {ObjectFilter {any_of:vec![ObjectFilter::specific(b),ObjectFilter::specific(d)],..ObjectFilter::default()}};
                    let spell=game.create_object_from_definition(&CardDefinitionBuilder::new(CardId::new(),"Two independent target requirements")
                        .card_types(vec![card_type]).mana_cost(ManaCost::new()).with_spell_effect(vec![
                            Effect::new(PutCountersEffect::new(CounterType::Charge,1,ChooseSpec::target(ChooseSpec::Object(first)))),
                            Effect::new(PutCountersEffect::new(CounterType::Charge,1,ChooseSpec::target(ChooseSpec::Object(second))))]).build(),caster,Zone::Hand);
                    let stable=game.object(spell).unwrap().stable_id;
                    let action=ironsmith::compute_legal_actions(&game,caster).unwrap().into_iter()
                        .find(|action|matches!(action,LegalAction::CastSpell{spell_id,..} if *spell_id==spell)).expect("native cast must be offered");
                    let mut initial=SelectSlots{wanted:[a,b],old:[a,b],decisions:0,issues:vec![]};let mut queue=TriggerQueue::new();
                    cr_audit_complete_priority_action_with_dm(&mut game,caster,action,&mut initial,&mut queue).unwrap();
                    ironsmith::put_triggers_on_stack(&mut game,&mut queue).unwrap();
                    assert_eq!(initial.decisions,1);assert!(initial.issues.is_empty(),"{:?}",initial.issues);
                    let spell=game.find_object_by_stable_id(stable).unwrap();assert_eq!(game.stack.len(),1);
                    assert_eq!(game.stack[0].object_id,spell);assert_eq!(game.stack[0].targets,vec![Target::Object(a),Target::Object(b)]);
                    assert_eq!(game.stack[0].target_assignments.len(),2);
                    let effect=RetargetStackObjectEffect::new(ChooseSpec::SpecificObject(spell));
                    let effect=if choose_new {effect} else {effect.require_change()};
                    let reader=game.create_object_from_definition(&CardDefinitionBuilder::new(CardId::new(),"Native retarget instruction")
                        .card_types(vec![CardType::Artifact]).with_ability(Ability::activated(ironsmith::cost::TotalCost::free(),vec![Effect::new(effect)])).build(),caster,Zone::Battlefield);
                    let action=LegalAction::ActivateAbility{source:reader,ability_index:0};
                    assert!(ironsmith::compute_legal_actions(&game,caster).unwrap().contains(&action));
                    cr_audit_complete_priority_action(&mut game,caster,action).unwrap();assert_eq!(game.stack.len(),2);
                    let mut retarget=SelectSlots{wanted:[c,d],old:[a,b],decisions:0,issues:vec![]};
                    ironsmith::game_loop::resolve_stack_entry_with(&mut game,&mut retarget).unwrap();
                    assert!(retarget.issues.is_empty(),"{:?}",retarget.issues);assert_eq!(retarget.decisions,usize::from(pattern!=2));
                    assert_eq!(game.stack.len(),1);assert_eq!(game.stack[0].object_id,spell);
                    let expected=match (pattern,choose_new) {(1,_)=>[c,d],(0,true)=>[a,d],_=>[a,b]};
                    let wanted=expected.map(Target::Object).to_vec();
                    let label=format!("caster={caster:?} type={card_type:?} pattern={pattern} choose_new={choose_new}");
                    if game.stack[0].targets!=wanted {discrepancies.push(format!("{label}: actual targets{:?}, expected{wanted:?}",game.stack[0].targets));}
                    assert_eq!(game.stack[0].targets.len(),2);assert_eq!(game.stack[0].target_assignments.len(),2);
                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();assert!(game.stack.is_empty());
                    let counts:Vec<_>=ids.iter().map(|id|game.counter_count(*id,CounterType::Charge)).collect();
                    let expected_counts:Vec<_>=ids.iter().map(|id|u32::from(expected.contains(id))).collect();
                    if counts!=expected_counts {discrepancies.push(format!("{label}: resolved counters{counts:?}, expected{expected_counts:?}"));}
                    assert_eq!(game.object(game.find_object_by_stable_id(stable).unwrap()).unwrap().zone,Zone::Graveyard);
                    for player in [PlayerId::from_index(0),PlayerId::from_index(1)] {assert_eq!(game.player(player).unwrap().life,20);}
                    game.validate_zone_consistency().unwrap();cases+=1;
                }
            }
        }
    }
    assert_eq!(cases,24);
    assert!(discrepancies.is_empty(),"CR115.7a: change all targets must change every target or none; choose-new-targets may retain some; {} mismatches in{cases} fixtures:\n{}",discrepancies.len(),discrepancies.join("\n"));
}

#[test]
fn cr_115_9c_native_only_target_queries_require_one_distinct_entity() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::decisions::context::TargetsContext;
    use ironsmith::effects::PutCountersEffect;
    use ironsmith::triggers::TriggerQueue;
    use ironsmith::{Ability,CardId,CardType,ChooseSpec,CounterType,Effect,LegalAction,ManaCost,ObjectFilter,Phase,Target,Value,Zone};
    struct SingletonChoices { requirements:usize, wanted:Vec<Target> }
    impl DecisionMaker for SingletonChoices {
        fn decide_targets(&mut self,_:&GameState,ctx:&TargetsContext)->Vec<Target>{
            let start=self.requirements;self.requirements+=ctx.requirements.len();
            ctx.requirements.iter().enumerate().map(|(index,req)|{assert_eq!((req.min_targets,req.max_targets),(1,Some(1)));let wanted=self.wanted[start+index];assert!(req.legal_targets.contains(&wanted));wanted}).collect()
        }
    }
    let mut cases=0;let mut discrepancies=vec![];
    for caster in [PlayerId::from_index(0),PlayerId::from_index(1)] {
        let other_player=PlayerId::from_index(1-caster.index()as u8);
        for card_type in [CardType::Instant,CardType::Sorcery] {
            for pattern in 0..8 {
                let mut game=GameState::new(vec!["A".into(),"B".into()],20);
                game.turn.active_player=caster;game.turn.priority_player=Some(caster);game.turn.phase=Phase::FirstMain;
                let creature=CardDefinitionBuilder::new(CardId::new(),"Only-target quality candidate")
                    .card_types(vec![CardType::Creature]).power_toughness(ironsmith::PowerToughness::fixed(2,8)).build();
                let a=game.create_object_from_definition(&creature,caster,Zone::Battlefield);
                let b=game.create_object_from_definition(&creature,caster,Zone::Battlefield);
                let targets=match pattern {
                    0=>vec![],1=>vec![Target::Object(a)],2=>vec![Target::Object(a),Target::Object(a)],
                    3=>vec![Target::Object(a),Target::Object(b)],4=>vec![Target::Player(caster)],
                    5=>vec![Target::Player(caster),Target::Player(caster)],
                    6=>vec![Target::Player(caster),Target::Player(other_player)],
                    _=>vec![Target::Object(a),Target::Player(caster)],
                };
                // Broad first and specific second selectors are independent target
                // requirements. Identical native selectors denote a reused target
                // reference and can coalesce; that is not this fixture's subject.
                let effects=if targets.is_empty(){vec![Effect::gain_life(1)]}else{targets.iter().enumerate().map(|(index,target)|match target{
                    Target::Object(id)=>Effect::new(PutCountersEffect::new(CounterType::Charge,1,ChooseSpec::target(ChooseSpec::Object(if index==0 && matches!(pattern,2|3){ObjectFilter::creature()}else{ObjectFilter::specific(*id)})))),
                    Target::Player(id)=>Effect::gain_life_player(1,ChooseSpec::target(ChooseSpec::Player(if index==0 && matches!(pattern,5|6){PlayerFilter::Any}else{PlayerFilter::Specific(*id)}))),
                }).collect()};
                let card=game.create_object_from_definition(&CardDefinitionBuilder::new(CardId::new(),"Independent target-word occurrence probe")
                    .card_types(vec![card_type]).mana_cost(ManaCost::new()).with_spell_effect(effects).build(),caster,Zone::Hand);
                let stable=game.object(card).unwrap().stable_id;
                let filters=[
                    ObjectFilter::spell().targeting_only_object(ObjectFilter::creature()),
                    ObjectFilter::spell().targeting_only_player(PlayerFilter::Any),
                    ObjectFilter::spell().targeting_only(Some(PlayerFilter::Any),Some(ObjectFilter::creature())),
                    ObjectFilter::spell().target_count_exact(2),
                    ObjectFilter::spell().targeting(None,Some(ObjectFilter::creature())),
                    ObjectFilter::spell().targeting(Some(PlayerFilter::Any),None),
                ];
                let mut definition=CardDefinitionBuilder::new(CardId::new(),"Native only-target quality and literal-count queries").card_types(vec![CardType::Artifact]);
                for filter in filters {definition=definition.with_ability(Ability::activated(ironsmith::cost::TotalCost::free(),vec![Effect::gain_life(Value::Count(filter))]));}
                let query=game.create_object_from_definition(&definition.build(),caster,Zone::Battlefield);
                let action=ironsmith::compute_legal_actions(&game,caster).unwrap().into_iter().find(|action|matches!(action,LegalAction::CastSpell{spell_id,..}if *spell_id==card)).expect("authored cast must be legal");
                let mut dm=SingletonChoices{requirements:0,wanted:targets.clone()};let mut queue=TriggerQueue::new();
                cr_audit_complete_priority_action_with_dm(&mut game,caster,action,&mut dm,&mut queue).unwrap();
                ironsmith::put_triggers_on_stack(&mut game,&mut queue).unwrap();
                let spell=game.find_object_by_stable_id(stable).unwrap();assert_eq!(game.stack.len(),1);assert_eq!(game.stack[0].object_id,spell);
                let mut chosen=game.stack[0].targets.clone();let mut wanted=targets.clone();chosen.sort_by_key(|x|format!("{x:?}"));wanted.sort_by_key(|x|format!("{x:?}"));assert_eq!(chosen,wanted);assert_eq!(dm.requirements,targets.len());
                let expected=[matches!(pattern,1|2),matches!(pattern,4|5),matches!(pattern,1|2|4|5),matches!(pattern,2|3|5|6|7),matches!(pattern,1|2|3|7),matches!(pattern,4|5|6|7)];
                for(index,wanted)in expected.into_iter().enumerate(){
                    let action=LegalAction::ActivateAbility{source:query,ability_index:index};assert!(ironsmith::compute_legal_actions(&game,caster).unwrap().contains(&action));
                    let before=game.player(caster).unwrap().life;cr_audit_complete_priority_action(&mut game,caster,action).unwrap();assert_eq!(game.stack.len(),2);
                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();let gain=game.player(caster).unwrap().life-before;
                    if gain!=i32::from(wanted){discrepancies.push(format!("caster={caster:?} type={card_type:?} pattern={pattern} query={index}: gain{gain}, expected{}",i32::from(wanted)));}
                    assert_eq!(game.stack.len(),1);assert_eq!(game.stack[0].object_id,spell);assert_eq!(game.stack[0].targets.len(),targets.len());
                }
                assert_eq!(game.counter_count(a,CounterType::Charge),0);assert_eq!(game.counter_count(b,CounterType::Charge),0);
                assert_eq!(game.player(other_player).unwrap().life,20);game.validate_zone_consistency().unwrap();cases+=1;
            }
        }
    }
    assert_eq!(cases,32);assert!(discrepancies.is_empty(),"CR115.9c: native targets-only quality queries require one distinct entity, not merely all targets matching a quality; {} mismatches in{cases} fixtures:\n{}",discrepancies.len(),discrepancies.join("\n"));
}

#[test]
fn cr_115_3_one_target_word_requires_two_distinct_eligible_creatures() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::decisions::context::TargetsContext;
    use ironsmith::effects::PutCountersEffect;
    use ironsmith::triggers::TriggerQueue;
    use ironsmith::{CardId,CardType,ChoiceCount,ChooseSpec,CounterType,Effect,LegalAction,ManaCost,ObjectFilter,Phase,Target,Zone};
    struct TwoChoices{decisions:usize}
    impl DecisionMaker for TwoChoices{
        fn decide_targets(&mut self,_:&GameState,ctx:&TargetsContext)->Vec<Target>{
            self.decisions+=1;assert_eq!(ctx.requirements.len(),1);let req=&ctx.requirements[0];assert_eq!((req.min_targets,req.max_targets),(2,Some(2)));
            assert!(req.legal_targets.len()>=2);assert_ne!(req.legal_targets[0],req.legal_targets[1]);req.legal_targets[..2].to_vec()
        }
    }
    let mut cases=0;let mut discrepancies=vec![];
    for caster in [PlayerId::from_index(0),PlayerId::from_index(1)] {
        for card_type in [CardType::Instant,CardType::Sorcery] {
            for available in 0..4 {
                let mut game=GameState::new(vec!["A".into(),"B".into()],20);game.turn.active_player=caster;game.turn.priority_player=Some(caster);game.turn.phase=Phase::FirstMain;
                let creature=CardDefinitionBuilder::new(CardId::new(),"Distinct eligibility candidate").card_types(vec![CardType::Creature]).power_toughness(ironsmith::PowerToughness::fixed(2,8)).build();
                let candidates:Vec<_>=(0..available).map(|_|game.create_object_from_definition(&creature,caster,Zone::Battlefield)).collect();
                let spec=ChooseSpec::target(ChooseSpec::Object(ObjectFilter::creature()));
                let card=game.create_object_from_definition(&CardDefinitionBuilder::new(CardId::new(),"One target word with two recipients").card_types(vec![card_type]).mana_cost(ManaCost::new()).with_spell_effect(vec![Effect::new(PutCountersEffect::new(CounterType::Charge,1,spec).with_target_count(ChoiceCount::exactly(2)))]).build(),caster,Zone::Hand);
                let stable=game.object(card).unwrap().stable_id;let action=ironsmith::compute_legal_actions(&game,caster).unwrap().into_iter().find(|action|matches!(action,LegalAction::CastSpell{spell_id,..}if *spell_id==card));
                let label=format!("caster={caster:?} type={card_type:?} available={available}");
                if action.is_some()!=(available>=2){discrepancies.push(format!("{label}: cast offered{}, expected{}",action.is_some(),available>=2));cases+=1;continue;}
                if let Some(action)=action{
                    let mut dm=TwoChoices{decisions:0};let mut queue=TriggerQueue::new();cr_audit_complete_priority_action_with_dm(&mut game,caster,action,&mut dm,&mut queue).unwrap();ironsmith::put_triggers_on_stack(&mut game,&mut queue).unwrap();assert_eq!(dm.decisions,1);
                    let spell=game.find_object_by_stable_id(stable).unwrap();assert_eq!(game.stack.len(),1);assert_eq!(game.stack[0].object_id,spell);assert_eq!(game.stack[0].target_assignments.len(),1);
                    let chosen=game.stack[0].targets.clone();assert_eq!(chosen.len(),2);assert_ne!(chosen[0],chosen[1]);assert!(chosen.iter().all(|x|matches!(x,Target::Object(id)if candidates.contains(id))));
                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();assert!(game.stack.is_empty());
                    for id in &candidates{assert_eq!(game.counter_count(*id,CounterType::Charge),u32::from(chosen.contains(&Target::Object(*id))));}
                    assert_eq!(game.object(game.find_object_by_stable_id(stable).unwrap()).unwrap().zone,Zone::Graveyard);
                }else{assert_eq!(game.object(card).unwrap().zone,Zone::Hand);assert!(game.stack.is_empty());}
                for player in [PlayerId::from_index(0),PlayerId::from_index(1)]{assert_eq!(game.player(player).unwrap().life,20);}
                game.validate_zone_consistency().unwrap();cases+=1;
            }
        }
    }
    assert_eq!(cases,16);assert!(discrepancies.is_empty(),"CR115.3: a single target word cannot fill a two-target requirement by reusing one eligible object; {} mismatches in{cases} fixtures:\n{}",discrepancies.len(),discrepancies.join("\n"));
}

#[test]
fn cr_115_9c_activated_and_triggered_only_queries_require_one_distinct_entity() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::decisions::context::TargetsContext;
    use ironsmith::effects::{PutCountersEffect,TapEffect};
    use ironsmith::triggers::{Trigger,TriggerQueue};
    use ironsmith::{Ability,AbilityKind,CardId,CardType,ChooseSpec,CounterType,Effect,LegalAction,ObjectFilter,Phase,Target,Value,Zone};
    struct SingletonChoices { requirements:usize, wanted:Vec<Target> }
    impl DecisionMaker for SingletonChoices {
        fn decide_targets(&mut self,_:&GameState,ctx:&TargetsContext)->Vec<Target>{
            let start=self.requirements;self.requirements+=ctx.requirements.len();
            ctx.requirements.iter().enumerate().map(|(index,req)|{assert_eq!((req.min_targets,req.max_targets),(1,Some(1)));let wanted=self.wanted[start+index];assert!(req.legal_targets.contains(&wanted));wanted}).collect()
        }
    }
    let mut cases=0;let mut discrepancies=vec![];
    for caster in [PlayerId::from_index(0),PlayerId::from_index(1)] {
        let other_player=PlayerId::from_index(1-caster.index()as u8);
        for triggered in [false,true] {
            for pattern in 0..8 {
                let mut game=GameState::new(vec!["A".into(),"B".into()],20);
                game.turn.active_player=caster;game.turn.priority_player=Some(caster);game.turn.phase=Phase::FirstMain;
                let creature=CardDefinitionBuilder::new(CardId::new(),"Only-target quality candidate")
                    .card_types(vec![CardType::Creature]).power_toughness(ironsmith::PowerToughness::fixed(2,8)).build();
                let a=game.create_object_from_definition(&creature,caster,Zone::Battlefield);
                let b=game.create_object_from_definition(&creature,caster,Zone::Battlefield);
                let targets=match pattern {
                    0=>vec![],1=>vec![Target::Object(a)],2=>vec![Target::Object(a),Target::Object(a)],
                    3=>vec![Target::Object(a),Target::Object(b)],4=>vec![Target::Player(caster)],
                    5=>vec![Target::Player(caster),Target::Player(caster)],
                    6=>vec![Target::Player(caster),Target::Player(other_player)],
                    _=>vec![Target::Object(a),Target::Player(caster)],
                };
                // Broad first and specific second selectors are independent target
                // requirements. Identical native selectors denote a reused target
                // reference and can coalesce; that is not this fixture's subject.
                let effects=if targets.is_empty(){vec![Effect::gain_life(1)]}else{targets.iter().enumerate().map(|(index,target)|match target{
                    Target::Object(id)=>Effect::new(PutCountersEffect::new(CounterType::Charge,1,ChooseSpec::target(ChooseSpec::Object(if index==0 && matches!(pattern,2|3){ObjectFilter::creature()}else{ObjectFilter::specific(*id)})))),
                    Target::Player(id)=>Effect::gain_life_player(1,ChooseSpec::target(ChooseSpec::Player(if index==0 && matches!(pattern,5|6){PlayerFilter::Any}else{PlayerFilter::Specific(*id)}))),
                }).collect()};
                let choices=effects.iter().filter_map(|effect|effect.0.get_target_spec().filter(|spec|spec.is_target()).cloned()).collect();
                let mut producer=if triggered {Ability::triggered(Trigger::becomes_tapped(),effects)}else{Ability::activated(ironsmith::cost::TotalCost::free(),effects)};
                match &mut producer.kind {AbilityKind::Activated(ability)=>ability.choices=choices,AbilityKind::Triggered(ability)=>ability.choices=choices,_=>unreachable!()}
                let subject=game.create_object_from_definition(&CardDefinitionBuilder::new(CardId::new(),"Real targeted ability producer").card_types(vec![CardType::Artifact]).with_ability(producer).build(),caster,Zone::Battlefield);
                let filters=[
                    ObjectFilter::ability().targeting_only_object(ObjectFilter::creature()),
                    ObjectFilter::ability().targeting_only_player(PlayerFilter::Any),
                    ObjectFilter::ability().targeting_only(Some(PlayerFilter::Any),Some(ObjectFilter::creature())),
                    ObjectFilter::ability().target_count_exact(2),
                    ObjectFilter::ability().targeting(None,Some(ObjectFilter::creature())),
                    ObjectFilter::ability().targeting(Some(PlayerFilter::Any),None),
                ];
                let mut definition=CardDefinitionBuilder::new(CardId::new(),"Native only-target quality and literal-count queries").card_types(vec![CardType::Artifact]);
                for filter in filters {definition=definition.with_ability(Ability::activated(ironsmith::cost::TotalCost::free(),vec![Effect::gain_life(Value::Count(filter))]));}
                definition=definition.with_ability(Ability::activated(ironsmith::cost::TotalCost::free(),vec![Effect::new(TapEffect::with_spec(ChooseSpec::SpecificObject(subject)))]));
                let query=game.create_object_from_definition(&definition.build(),caster,Zone::Battlefield);
                let mut dm=SingletonChoices{requirements:0,wanted:targets.clone()};let mut queue=TriggerQueue::new();
                let action=if triggered {LegalAction::ActivateAbility{source:query,ability_index:6}}else{LegalAction::ActivateAbility{source:subject,ability_index:0}};
                assert!(ironsmith::compute_legal_actions(&game,caster).unwrap().contains(&action));
                cr_audit_complete_priority_action_with_dm(&mut game,caster,action,&mut dm,&mut queue).unwrap();
                if triggered {assert_eq!(dm.requirements,0);assert_eq!(game.stack.len(),1);ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();assert!(game.stack.is_empty());assert!(game.is_tapped(subject));}
                ironsmith::game_loop::put_triggers_on_stack_with_dm(&mut game,&mut queue,&mut dm).unwrap();
                assert_eq!(game.stack.len(),1);assert_eq!(game.stack[0].object_id,subject);assert!(game.stack[0].is_ability);assert_eq!(game.stack[0].triggering_event.is_some(),triggered);
                let ability_id=game.stack[0].target_id();assert_ne!(ability_id,subject);assert_eq!(game.stack[0].ability_id,Some(ability_id));assert_eq!(game.object(subject).unwrap().zone,Zone::Battlefield);
                let mut chosen=game.stack[0].targets.clone();let mut wanted=targets.clone();chosen.sort_by_key(|x|format!("{x:?}"));wanted.sort_by_key(|x|format!("{x:?}"));assert_eq!(chosen,wanted);assert_eq!(dm.requirements,targets.len());
                let expected=[matches!(pattern,1|2),matches!(pattern,4|5),matches!(pattern,1|2|4|5),matches!(pattern,2|3|5|6|7),matches!(pattern,1|2|3|7),matches!(pattern,4|5|6|7)];
                for(index,wanted)in expected.into_iter().enumerate(){
                    let action=LegalAction::ActivateAbility{source:query,ability_index:index};assert!(ironsmith::compute_legal_actions(&game,caster).unwrap().contains(&action));
                    let before=game.player(caster).unwrap().life;cr_audit_complete_priority_action(&mut game,caster,action).unwrap();assert_eq!(game.stack.len(),2);
                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();let gain=game.player(caster).unwrap().life-before;
                    if gain!=i32::from(wanted){discrepancies.push(format!("caster={caster:?} triggered={triggered} pattern={pattern} query={index}: gain{gain}, expected{}",i32::from(wanted)));}
                    assert_eq!(game.stack.len(),1);assert_eq!(game.stack[0].object_id,subject);assert_eq!(game.stack[0].targets.len(),targets.len());assert_eq!(game.stack[0].target_id(),ability_id);
                }
                assert_eq!(game.counter_count(a,CounterType::Charge),0);assert_eq!(game.counter_count(b,CounterType::Charge),0);
                assert_eq!(game.player(other_player).unwrap().life,20);game.validate_zone_consistency().unwrap();cases+=1;
            }
        }
    }
    assert_eq!(cases,32);assert!(discrepancies.is_empty(),"CR115.9c: actual activated/triggered ability subjects require one distinct entity for targets-only queries; {} mismatches in{cases} fixtures:\n{}",discrepancies.len(),discrepancies.join("\n"));
}


#[test]
fn cr_113_1c_115_9b_numeric_queries_distinguish_two_abilities_from_one_source() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::decisions::context::TargetsContext;
    use ironsmith::effects::{CounterEffect, PutCountersEffect};
    use ironsmith::triggers::TriggerQueue;
    use ironsmith::{
        Ability, AbilityKind, CardId, CardType, ChooseSpec, CounterType, Effect, LegalAction,
        ObjectFilter, ObjectId, Phase, Target, Value, Zone,
    };
    struct ExactTarget {
        wanted: Target,
        decisions: usize,
    }
    impl DecisionMaker for ExactTarget {
        fn decide_targets(&mut self, _: &GameState, ctx: &TargetsContext) -> Vec<Target> {
            self.decisions += 1;
            assert_eq!(ctx.requirements.len(), 1);
            let req = &ctx.requirements[0];
            assert_eq!((req.min_targets, req.max_targets), (1, Some(1)));
            assert_eq!(req.legal_targets, vec![self.wanted]);
            vec![self.wanted]
        }
    }
    let mut discrepancies = vec![];
    let mut cases = 0;
    for caster in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for shared_source in [false, true] {
            for reverse in [false, true] {
                let mut game = GameState::new(vec!["A".into(), "B".into()], 20);
                game.turn.active_player = caster;
                game.turn.priority_player = Some(caster);
                game.turn.phase = Phase::FirstMain;
                let creature = game.create_object_from_definition(
                    &CardDefinitionBuilder::new(CardId::new(), "Creature target")
                        .card_types(vec![CardType::Creature])
                        .power_toughness(ironsmith::PowerToughness::fixed(2, 8))
                        .build(),
                    caster,
                    Zone::Battlefield,
                );
                let specs = [
                    ChooseSpec::target(ChooseSpec::Object(ObjectFilter::specific(creature))),
                    ChooseSpec::target(ChooseSpec::Player(PlayerFilter::Specific(caster))),
                ];
                let mut creature_ability = Ability::activated(
                    ironsmith::cost::TotalCost::free(),
                    vec![Effect::new(PutCountersEffect::new(
                        CounterType::Charge,
                        1,
                        specs[0].clone(),
                    ))],
                );
                let mut player_ability = Ability::activated(
                    ironsmith::cost::TotalCost::free(),
                    vec![Effect::gain_life_player(1, specs[1].clone())],
                );
                for (index, ability) in [&mut creature_ability, &mut player_ability]
                    .into_iter()
                    .enumerate()
                {
                    let AbilityKind::Activated(activated) = &mut ability.kind else {
                        unreachable!()
                    };
                    activated.choices = vec![specs[index].clone()];
                }
                let mut builder =
                    CardDefinitionBuilder::new(CardId::new(), "First ability producer")
                        .card_types(vec![CardType::Artifact])
                        .with_ability(creature_ability);
                if shared_source {
                    builder = builder.with_ability(player_ability.clone());
                }
                let first =
                    game.create_object_from_definition(&builder.build(), caster, Zone::Battlefield);
                let second = if shared_source {
                    first
                } else {
                    game.create_object_from_definition(
                        &CardDefinitionBuilder::new(CardId::new(), "Second ability producer")
                            .card_types(vec![CardType::Artifact])
                            .with_ability(player_ability)
                            .build(),
                        caster,
                        Zone::Battlefield,
                    )
                };
                let sources = [first, second];
                let indices = [0, usize::from(shared_source)];
                let chosen = [Target::Object(creature), Target::Player(caster)];
                let mut identities: [Option<ObjectId>; 2] = [None, None];
                let mut queue = TriggerQueue::new();
                for role in if reverse { [1, 0] } else { [0, 1] } {
                    let action = LegalAction::ActivateAbility {
                        source: sources[role],
                        ability_index: indices[role],
                    };
                    assert!(
                        ironsmith::compute_legal_actions(&game, caster)
                            .unwrap()
                            .contains(&action)
                    );
                    let mut dm = ExactTarget {
                        wanted: chosen[role],
                        decisions: 0,
                    };
                    cr_audit_complete_priority_action_with_dm(
                        &mut game, caster, action, &mut dm, &mut queue,
                    )
                    .unwrap();
                    ironsmith::put_triggers_on_stack(&mut game, &mut queue).unwrap();
                    assert_eq!(dm.decisions, 1);
                    let entry = game.stack.last().unwrap();
                    assert!(entry.is_ability);
                    assert_eq!(entry.object_id, sources[role]);
                    assert_eq!(entry.targets, vec![chosen[role]]);
                    assert_ne!(entry.target_id(), sources[role]);
                    identities[role] = Some(entry.target_id());
                }
                let [creature_id, player_id] = identities.map(Option::unwrap);
                assert_ne!(creature_id, player_id);
                assert_eq!(game.stack.len(), 2);
                let creature_filter =
                    ObjectFilter::ability().targeting(None, Some(ObjectFilter::creature()));
                let player_filter =
                    ObjectFilter::ability().targeting(Some(PlayerFilter::Any), None);
                let filters = [
                    creature_filter.clone(),
                    player_filter.clone(),
                    ObjectFilter::ability(),
                    ObjectFilter::ability().target_count_exact(1),
                    ObjectFilter::ability().target_count_exact(2),
                ];
                let mut reader = CardDefinitionBuilder::new(
                    CardId::new(),
                    "Actual numeric stack query and identity counters",
                )
                .card_types(vec![CardType::Artifact]);
                for filter in filters {
                    reader = reader.with_ability(Ability::activated(
                        ironsmith::cost::TotalCost::free(),
                        vec![Effect::gain_life(Value::Count(filter))],
                    ));
                }
                for filter in [creature_filter, player_filter] {
                    let spec = ChooseSpec::target(ChooseSpec::Object(filter));
                    let mut ability = Ability::activated(
                        ironsmith::cost::TotalCost::free(),
                        vec![Effect::new(CounterEffect::new(spec.clone()))],
                    );
                    let AbilityKind::Activated(activated) = &mut ability.kind else {
                        unreachable!()
                    };
                    activated.choices = vec![spec];
                    reader = reader.with_ability(ability);
                }
                let reader =
                    game.create_object_from_definition(&reader.build(), caster, Zone::Battlefield);
                for phase in 0..2 {
                    let expected = if phase == 0 {
                        [1, 1, 2, 2, 0]
                    } else {
                        [0, 1, 1, 1, 0]
                    };
                    let expected_stack = if phase == 0 { 2 } else { 1 };
                    for (index, wanted) in expected.into_iter().enumerate() {
                        let action = LegalAction::ActivateAbility {
                            source: reader,
                            ability_index: index,
                        };
                        assert!(
                            ironsmith::compute_legal_actions(&game, caster)
                                .unwrap()
                                .contains(&action)
                        );
                        let before = game.player(caster).unwrap().life;
                        cr_audit_complete_priority_action(&mut game, caster, action).unwrap();
                        assert_eq!(game.stack.len(), expected_stack + 1);
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        let gain = game.player(caster).unwrap().life - before;
                        if gain != wanted {
                            discrepancies.push(format!("caster={caster:?} shared={shared_source} reverse={reverse} phase={phase} query={index}: gain{gain}, expected{wanted}"));
                        }
                        assert_eq!(game.stack.len(), expected_stack);
                        assert!(game.stack.iter().any(|entry| entry.target_id() == player_id
                            && entry.targets == vec![Target::Player(caster)]));
                        assert_eq!(
                            game.stack
                                .iter()
                                .any(|entry| entry.target_id() == creature_id),
                            phase == 0
                        );
                    }
                    let wanted = if phase == 0 { creature_id } else { player_id };
                    let action = LegalAction::ActivateAbility {
                        source: reader,
                        ability_index: 5 + phase,
                    };
                    assert!(
                        ironsmith::compute_legal_actions(&game, caster)
                            .unwrap()
                            .contains(&action)
                    );
                    let mut dm = ExactTarget {
                        wanted: Target::Object(wanted),
                        decisions: 0,
                    };
                    cr_audit_complete_priority_action_with_dm(
                        &mut game, caster, action, &mut dm, &mut queue,
                    )
                    .unwrap();
                    assert_eq!(dm.decisions, 1);
                    assert_eq!(
                        game.stack.last().unwrap().targets,
                        vec![Target::Object(wanted)]
                    );
                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                    assert_eq!(game.stack.len(), expected_stack - 1);
                    assert!(!game.stack.iter().any(|entry| entry.target_id() == wanted));
                    for source in sources {
                        assert_eq!(game.object(source).unwrap().zone, Zone::Battlefield);
                    }
                }
                assert!(game.stack.is_empty());
                assert_eq!(game.counter_count(creature, CounterType::Charge), 0);
                assert_eq!(
                    game.player(PlayerId::from_index(1 - caster.index() as u8))
                        .unwrap()
                        .life,
                    20
                );
                game.validate_zone_consistency().unwrap();
                cases += 1;
            }
        }
    }
    assert_eq!(cases, 8);
    assert!(
        discrepancies.is_empty(),
        "CR113.1c/115.9b: numeric target queries must evaluate each real stack ability separately even when source IDs coincide; {} mismatches in{cases} fixtures:\n{}",
        discrepancies.len(),
        discrepancies.join("\n")
    );
}

#[test]
fn cr_115_6_608_2b_optional_zero_targets_still_resolve_untargeted_instructions() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::decisions::context::TargetsContext;
    use ironsmith::effects::PutCountersEffect;
    use ironsmith::triggers::TriggerQueue;
    use ironsmith::{
        Ability, CardId, CardType, ChoiceCount, ChooseSpec, CounterType, Effect, LegalAction,
        ManaCost, ObjectFilter, Phase, Target, Value, Zone,
    };
    struct OptionalChoices {
        wanted: usize,
        seen: usize,
    }
    impl DecisionMaker for OptionalChoices {
        fn decide_targets(&mut self, _: &GameState, ctx: &TargetsContext) -> Vec<Target> {
            self.seen += 1;
            assert_eq!(ctx.requirements.len(), 1);
            let req = &ctx.requirements[0];
            assert_eq!(req.min_targets, 0);
            assert!(req.max_targets.is_some_and(|n| n <= 2));
            assert!(req.legal_targets.len() >= self.wanted);
            req.legal_targets[..self.wanted].to_vec()
        }
    }
    let mut cases = 0;
    let mut discrepancies = vec![];
    for caster in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for card_type in [CardType::Instant, CardType::Sorcery] {
            for available in 0..3 {
                for chosen_count in 0..=available {
                    let mut game = GameState::new(vec!["A".into(), "B".into()], 20);
                    game.turn.active_player = caster;
                    game.turn.priority_player = Some(caster);
                    game.turn.phase = Phase::FirstMain;
                    let creature =
                        CardDefinitionBuilder::new(CardId::new(), "Optional target candidate")
                            .card_types(vec![CardType::Creature])
                            .power_toughness(ironsmith::PowerToughness::fixed(2, 8))
                            .build();
                    let candidates: Vec<_> = (0..available)
                        .map(|_| {
                            game.create_object_from_definition(&creature, caster, Zone::Battlefield)
                        })
                        .collect();
                    let spec = ChooseSpec::target(ChooseSpec::Object(ObjectFilter::creature()));
                    let card = game.create_object_from_definition(
                        &CardDefinitionBuilder::new(
                            CardId::new(),
                            "Up to two targets and an untargeted instruction",
                        )
                        .card_types(vec![card_type])
                        .mana_cost(ManaCost::new())
                        .with_spell_effect(vec![
                            Effect::new(
                                PutCountersEffect::new(CounterType::Charge, 1, spec)
                                    .with_target_count(ChoiceCount::up_to(2)),
                            ),
                            Effect::gain_life(2),
                        ])
                        .build(),
                        caster,
                        Zone::Hand,
                    );
                    let stable = game.object(card).unwrap().stable_id;
                    let action=ironsmith::compute_legal_actions(&game,caster).unwrap().into_iter().find(|action|matches!(action,LegalAction::CastSpell{spell_id,..}if *spell_id==card)).expect("optional zero-target casting remains legal even without candidates");
                    let mut dm = OptionalChoices {
                        wanted: chosen_count,
                        seen: 0,
                    };
                    let mut queue = TriggerQueue::new();
                    cr_audit_complete_priority_action_with_dm(
                        &mut game, caster, action, &mut dm, &mut queue,
                    )
                    .unwrap();
                    ironsmith::put_triggers_on_stack(&mut game, &mut queue).unwrap();
                    if available > 0 {
                        assert_eq!(dm.seen, 1);
                    }
                    let spell = game.find_object_by_stable_id(stable).unwrap();
                    assert_eq!(game.stack.len(), 1);
                    assert_eq!(game.stack[0].object_id, spell);
                    let chosen = game.stack[0].targets.clone();
                    assert_eq!(chosen.len(), chosen_count);
                    let unique: std::collections::HashSet<_> = chosen.iter().collect();
                    assert_eq!(unique.len(), chosen_count);
                    assert!(chosen.iter().all(
                        |target| matches!(target,Target::Object(id)if candidates.contains(id))
                    ));
                    let filters = [
                        ObjectFilter::spell().target_count_exact(0),
                        ObjectFilter::spell().target_count_exact(1),
                        ObjectFilter::spell().target_count_exact(2),
                        ObjectFilter::spell().targeting(None, Some(ObjectFilter::creature())),
                    ];
                    let mut reader = CardDefinitionBuilder::new(
                        CardId::new(),
                        "Optional target announcement readers",
                    )
                    .card_types(vec![CardType::Artifact]);
                    for filter in filters {
                        reader = reader.with_ability(Ability::activated(
                            ironsmith::cost::TotalCost::free(),
                            vec![Effect::gain_life(Value::Count(filter))],
                        ));
                    }
                    let reader = game.create_object_from_definition(
                        &reader.build(),
                        caster,
                        Zone::Battlefield,
                    );
                    let expected = [
                        chosen_count == 0,
                        chosen_count == 1,
                        chosen_count == 2,
                        chosen_count > 0,
                    ];
                    let label = format!(
                        "caster={caster:?} type={card_type:?} available={available} chosen={chosen_count}"
                    );
                    for (index, wanted) in expected.into_iter().enumerate() {
                        let before = game.player(caster).unwrap().life;
                        let action = LegalAction::ActivateAbility {
                            source: reader,
                            ability_index: index,
                        };
                        assert!(
                            ironsmith::compute_legal_actions(&game, caster)
                                .unwrap()
                                .contains(&action)
                        );
                        cr_audit_complete_priority_action(&mut game, caster, action).unwrap();
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        let gain = game.player(caster).unwrap().life - before;
                        if gain != i32::from(wanted) {
                            discrepancies.push(format!(
                                "{label} query={index}: gain{gain}, expected{}",
                                i32::from(wanted)
                            ));
                        }
                        assert_eq!(game.stack.len(), 1);
                        assert_eq!(game.stack[0].targets, chosen);
                    }
                    let before = game.player(caster).unwrap().life;
                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                    let gain = game.player(caster).unwrap().life - before;
                    if gain != 2 {
                        discrepancies.push(format!(
                            "{label}: independent resolving life gain{gain}, expected2"
                        ));
                    }
                    for id in candidates {
                        let count = game.counter_count(id, CounterType::Charge);
                        let expected = u32::from(chosen.contains(&Target::Object(id)));
                        if count != expected {
                            discrepancies.push(format!(
                                "{label}: recipient{id:?} counters{count}, expected{expected}"
                            ));
                        }
                    }
                    assert!(game.stack.is_empty());
                    assert_eq!(
                        game.object(game.find_object_by_stable_id(stable).unwrap())
                            .unwrap()
                            .zone,
                        Zone::Graveyard
                    );
                    assert_eq!(
                        game.player(PlayerId::from_index(1 - caster.index() as u8))
                            .unwrap()
                            .life,
                        20
                    );
                    game.validate_zone_consistency().unwrap();
                    cases += 1;
                }
            }
        }
    }
    assert_eq!(cases, 24);
    assert!(
        discrepancies.is_empty(),
        "CR115.6/608.2b: declaring an optional target requirement and choosing zero is legal and does not prevent untargeted instructions from resolving; {} mismatches in{cases} fixtures:\n{}",
        discrepancies.len(),
        discrepancies.join("\n")
    );
}

#[test]
fn cr_115_1_115_10_you_each_and_target_player_keep_distinct_targeting_semantics() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::decisions::context::TargetsContext;
    use ironsmith::effects::TapEffect;
    use ironsmith::triggers::TriggerQueue;
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, Effect, LegalAction, ObjectFilter, Phase, Target,
        Value, Zone,
    };
    struct PlayerChoices {
        wanted: PlayerId,
        requirements: usize,
    }
    impl DecisionMaker for PlayerChoices {
        fn decide_targets(&mut self, _: &GameState, ctx: &TargetsContext) -> Vec<Target> {
            self.requirements += ctx.requirements.len();
            ctx.requirements
                .iter()
                .map(|req| {
                    assert_eq!((req.min_targets, req.max_targets), (1, Some(1)));
                    let target = Target::Player(self.wanted);
                    assert!(req.legal_targets.contains(&target));
                    target
                })
                .collect()
        }
    }
    let mut discrepancies = vec![];
    let mut cases = 0;
    for origin in 0..4 {
        for profile in 0..4 {
            let sentence = match profile {
                0 => "You gain 2 life.",
                1 => "Each player gains 2 life.",
                _ => "Target player gains 2 life.",
            };
            let text = match origin {
                0 => format!("Mana cost: {{0}}\nType: Instant\n{sentence}"),
                1 => format!("Mana cost: {{0}}\nType: Sorcery\n{sentence}"),
                2 => format!("Mana cost: {{0}}\nType: Artifact\n{{0}}: {sentence}"),
                _ => {
                    let mut lower = sentence.to_owned();
                    lower.replace_range(..1, &sentence[..1].to_ascii_lowercase());
                    format!(
                        "Mana cost: {{0}}\nType: Artifact\nWhenever this artifact becomes tapped, {lower}"
                    )
                }
            };
            let definition = ironsmith_compiler_runtime::compile_to_runtime_definition(
                &format!("Life wording origin{origin} profile{profile}"),
                &text,
                false,
            )
            .expect("strict compiler must accept these basic life instructions");
            for caster in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                let other = PlayerId::from_index(1 - caster.index() as u8);
                let wanted = if profile == 3 { other } else { caster };
                let mut game = GameState::new(vec!["A".into(), "B".into()], 20);
                game.turn.active_player = caster;
                game.turn.priority_player = Some(caster);
                game.turn.phase = Phase::FirstMain;
                let subject = game.create_object_from_definition(
                    &definition,
                    caster,
                    if origin < 2 {
                        Zone::Hand
                    } else {
                        Zone::Battlefield
                    },
                );
                let stable = game.object(subject).unwrap().stable_id;
                let base = if origin < 2 {
                    ObjectFilter::spell()
                } else {
                    ObjectFilter::ability()
                };
                let filters = [
                    base.clone().target_count_exact(0),
                    base.clone().target_count_exact(1),
                    base.targeting(Some(PlayerFilter::Any), None),
                ];
                let mut reader =
                    CardDefinitionBuilder::new(CardId::new(), "Target classification readers")
                        .card_types(vec![CardType::Artifact]);
                for filter in filters {
                    reader = reader.with_ability(Ability::activated(
                        ironsmith::cost::TotalCost::free(),
                        vec![Effect::gain_life(Value::Count(filter))],
                    ));
                }
                if origin == 3 {
                    reader = reader.with_ability(Ability::activated(
                        ironsmith::cost::TotalCost::free(),
                        vec![Effect::new(TapEffect::with_spec(
                            ChooseSpec::SpecificObject(subject),
                        ))],
                    ));
                }
                let reader =
                    game.create_object_from_definition(&reader.build(), caster, Zone::Battlefield);
                let label = format!("origin={origin} profile={profile} caster={caster:?}");
                let action = if origin < 2 {
                    ironsmith::compute_legal_actions(&game,caster).unwrap().into_iter().find(|action|matches!(action,LegalAction::CastSpell{spell_id,..}if *spell_id==subject)).expect("compiled zero-cost life spell must be castable")
                } else {
                    LegalAction::ActivateAbility {
                        source: if origin == 3 { reader } else { subject },
                        ability_index: if origin == 3 { 3 } else { 0 },
                    }
                };
                assert!(
                    ironsmith::compute_legal_actions(&game, caster)
                        .unwrap()
                        .contains(&action)
                );
                let mut dm = PlayerChoices {
                    wanted,
                    requirements: 0,
                };
                let mut queue = TriggerQueue::new();
                cr_audit_complete_priority_action_with_dm(
                    &mut game, caster, action, &mut dm, &mut queue,
                )
                .unwrap();
                if origin == 3 {
                    assert_eq!(dm.requirements, 0);
                    assert_eq!(game.stack.len(), 1);
                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                    assert!(game.stack.is_empty());
                    assert!(game.is_tapped(subject));
                }
                ironsmith::game_loop::put_triggers_on_stack_with_dm(&mut game, &mut queue, &mut dm)
                    .unwrap();
                if game.stack.len() != 1 {
                    discrepancies.push(format!(
                        "{label}: waiting entries{}, expected1",
                        game.stack.len()
                    ));
                    cases += 1;
                    continue;
                }
                let source = game.find_object_by_stable_id(stable).unwrap();
                assert_eq!(game.stack[0].object_id, source);
                assert_eq!(game.stack[0].is_ability, origin >= 2);
                assert_eq!(game.stack[0].triggering_event.is_some(), origin == 3);
                let identity = game.stack[0].target_id();
                if origin >= 2 {
                    assert_ne!(identity, source);
                    assert_eq!(game.object(source).unwrap().zone, Zone::Battlefield);
                } else {
                    assert_eq!(identity, source);
                    assert_eq!(game.object(source).unwrap().zone, Zone::Stack);
                }
                let actual_targets = game.stack[0].targets.clone();
                let expected_targets = if profile >= 2 {
                    vec![Target::Player(wanted)]
                } else {
                    vec![]
                };
                if actual_targets != expected_targets {
                    discrepancies.push(format!(
                        "{label}: actual targets{actual_targets:?}, expected{expected_targets:?}"
                    ));
                }
                if dm.requirements != usize::from(profile >= 2) {
                    discrepancies.push(format!(
                        "{label}: target requirements{}, expected{}",
                        dm.requirements,
                        usize::from(profile >= 2)
                    ));
                }
                let expected = [profile < 2, profile >= 2, profile >= 2];
                for (index, wanted) in expected.into_iter().enumerate() {
                    let before = game.player(caster).unwrap().life;
                    let action = LegalAction::ActivateAbility {
                        source: reader,
                        ability_index: index,
                    };
                    assert!(
                        ironsmith::compute_legal_actions(&game, caster)
                            .unwrap()
                            .contains(&action)
                    );
                    cr_audit_complete_priority_action(&mut game, caster, action).unwrap();
                    assert_eq!(game.stack.len(), 2);
                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                    let gain = game.player(caster).unwrap().life - before;
                    if gain != i32::from(wanted) {
                        discrepancies.push(format!(
                            "{label} query={index}: gain{gain}, expected{}",
                            i32::from(wanted)
                        ));
                    }
                    assert_eq!(game.stack.len(), 1);
                    assert_eq!(game.stack[0].target_id(), identity);
                    assert_eq!(game.stack[0].targets, actual_targets);
                }
                let before = [
                    game.player(caster).unwrap().life,
                    game.player(other).unwrap().life,
                ];
                ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                let gains = [
                    game.player(caster).unwrap().life - before[0],
                    game.player(other).unwrap().life - before[1],
                ];
                let expected_gains = match profile {
                    0 | 2 => [2, 0],
                    1 => [2, 2],
                    _ => [0, 2],
                };
                if gains != expected_gains {
                    discrepancies.push(format!(
                        "{label}: resolving life gains{gains:?}, expected{expected_gains:?}"
                    ));
                }
                assert!(game.stack.is_empty());
                if origin < 2 {
                    assert_eq!(
                        game.object(game.find_object_by_stable_id(stable).unwrap())
                            .unwrap()
                            .zone,
                        Zone::Graveyard
                    );
                } else {
                    assert_eq!(game.object(source).unwrap().zone, Zone::Battlefield);
                }
                game.validate_zone_consistency().unwrap();
                cases += 1;
            }
        }
    }
    assert_eq!(cases, 32);
    assert!(
        discrepancies.is_empty(),
        "CR115.1/115.10: production you/each wording affects players without targeting, while target-player wording announces a real target across spell/activated/triggered origins; {} mismatches in{cases} fixtures:\n{}",
        discrepancies.len(),
        discrepancies.join("\n")
    );
}

#[test]
fn cr_101_3_115_10_untargeted_sacrifice_choices_wait_for_resolution_and_ignore_shroud() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::decisions::context::{SelectObjectsContext, TargetsContext};
    use ironsmith::triggers::TriggerQueue;
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, Effect, LegalAction, ObjectFilter, ObjectId, Phase,
        StaticAbility, Target, Value, Zone,
    };
    struct Choices {
        actor: PlayerId,
        wanted: Option<ObjectId>,
        target_requirements: usize,
        object_decisions: usize,
        issues: Vec<String>,
    }
    impl DecisionMaker for Choices {
        fn decide_targets(&mut self, _: &GameState, ctx: &TargetsContext) -> Vec<Target> {
            self.target_requirements += ctx.requirements.len();
            ctx.requirements
                .iter()
                .filter_map(|req| {
                    let wanted = Target::Player(self.actor);
                    if req.legal_targets.contains(&wanted) {
                        Some(wanted)
                    } else {
                        self.issues
                            .push(format!("unexpected target menu{:?}", req.legal_targets));
                        req.legal_targets.first().copied()
                    }
                })
                .collect()
        }
        fn decide_objects(&mut self, _: &GameState, ctx: &SelectObjectsContext) -> Vec<ObjectId> {
            self.object_decisions += 1;
            if ctx.player != self.actor {
                self.issues.push(format!(
                    "object chooser{:?}, expected{:?}",
                    ctx.player, self.actor
                ));
            }
            if let Some(wanted) = self.wanted {
                if ctx.candidates.iter().any(|c| c.id == wanted && c.legal) {
                    vec![wanted]
                } else {
                    self.issues.push(format!(
                        "shrouded sacrifice candidate{wanted:?} missing from actual legal menu"
                    ));
                    ctx.candidates
                        .iter()
                        .filter(|c| c.legal)
                        .take(1)
                        .map(|c| c.id)
                        .collect()
                }
            } else {
                vec![]
            }
        }
    }
    let mut cases = 0;
    let mut discrepancies = vec![];
    for instant in [false, true] {
        for profile in 0..3 {
            let sentence = if profile == 0 {
                "Sacrifice a creature. You gain 2 life."
            } else {
                "Target player sacrifices a creature. You gain 2 life."
            };
            let kind = if instant { "Instant" } else { "Sorcery" };
            let definition = ironsmith_compiler_runtime::compile_to_runtime_definition(
                &format!("Instruction survey {kind} profile{profile}"),
                &format!("Mana cost: {{0}}\nType: {kind}\n{sentence}"),
                false,
            )
            .expect("strict compiler must accept sacrifice and independent life instructions");
            for caster in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                let other = PlayerId::from_index(1 - caster.index() as u8);
                let actor = if profile == 2 { other } else { caster };
                for present in [false, true] {
                    let mut game = GameState::new(vec!["A".into(), "B".into()], 20);
                    game.turn.active_player = caster;
                    game.turn.priority_player = Some(caster);
                    game.turn.phase = Phase::FirstMain;
                    let mut creatures = vec![];
                    let mut wanted = None;
                    if present {
                        for owner in [caster, other] {
                            for shroud in [false, true] {
                                let mut d = CardDefinitionBuilder::new(
                                    CardId::new(),
                                    "Resolution sacrifice candidate",
                                )
                                .card_types(vec![CardType::Creature])
                                .power_toughness(ironsmith::PowerToughness::fixed(2, 8));
                                if shroud {
                                    d = d.with_ability(Ability::static_ability(
                                        StaticAbility::shroud(),
                                    ));
                                }
                                let id = game.create_object_from_definition(
                                    &d.build(),
                                    owner,
                                    Zone::Battlefield,
                                );
                                let stable = game.object(id).unwrap().stable_id;
                                if owner == actor && shroud {
                                    wanted = Some(id);
                                }
                                creatures.push((id, stable, shroud));
                            }
                        }
                    }
                    let card = game.create_object_from_definition(&definition, caster, Zone::Hand);
                    let stable = game.object(card).unwrap().stable_id;
                    let label = format!(
                        "instant={instant} profile={profile} caster={caster:?} present={present}"
                    );
                    let action=ironsmith::compute_legal_actions(&game,caster).unwrap().into_iter().find(|action|matches!(action,LegalAction::CastSpell{spell_id,..}if *spell_id==card));
                    let Some(action) = action else {
                        discrepancies.push(format!(
                            "{label}: a legal zero-cost instruction spell is not offered"
                        ));
                        cases += 1;
                        continue;
                    };
                    let mut dm = Choices {
                        actor,
                        wanted,
                        target_requirements: 0,
                        object_decisions: 0,
                        issues: vec![],
                    };
                    let mut queue = TriggerQueue::new();
                    if let Err(error) = cr_audit_complete_priority_action_with_dm(
                        &mut game, caster, action, &mut dm, &mut queue,
                    ) {
                        discrepancies.push(format!("{label}: native cast rejected{error}"));
                        cases += 1;
                        continue;
                    }
                    ironsmith::put_triggers_on_stack(&mut game, &mut queue).unwrap();
                    assert_eq!(game.stack.len(), 1);
                    let spell = game.find_object_by_stable_id(stable).unwrap();
                    assert_eq!(game.stack[0].object_id, spell);
                    // Prove shroud is active for the targeted control before
                    // the untargeted sacrifice asks for a resolution choice.
                    let legal = ironsmith::targeting::compute_legal_targets(
                        &game,
                        &ChooseSpec::target(ChooseSpec::Object(ObjectFilter::creature())),
                        caster,
                        Some(spell),
                    );
                    for (id, _, shroud) in &creatures {
                        assert_eq!(legal.contains(&Target::Object(*id)), !*shroud);
                    }

                    if dm.object_decisions != 0 {
                        discrepancies.push(format!(
                            "{label}: object choices already requested during casting{}",
                            dm.object_decisions
                        ));
                    }
                    let expected_targets = if profile == 0 {
                        vec![]
                    } else {
                        vec![Target::Player(actor)]
                    };
                    let selected = game.stack[0].targets.clone();
                    if selected != expected_targets {
                        discrepancies.push(format!(
                            "{label}: announced targets{selected:?}, expected{expected_targets:?}"
                        ));
                    }
                    if dm.target_requirements != usize::from(profile != 0) {
                        discrepancies.push(format!(
                            "{label}: target requirements{}, expected{}",
                            dm.target_requirements,
                            usize::from(profile != 0)
                        ));
                    }
                    let filters = [
                        ObjectFilter::spell().target_count_exact(0),
                        ObjectFilter::spell().target_count_exact(1),
                        ObjectFilter::spell().targeting(Some(PlayerFilter::Any), None),
                        ObjectFilter::spell().targeting(None, Some(ObjectFilter::creature())),
                    ];
                    let expected = [profile == 0, profile != 0, profile != 0, false];
                    let mut reader = CardDefinitionBuilder::new(
                        CardId::new(),
                        "Resolution choice classification reader",
                    )
                    .card_types(vec![CardType::Artifact]);
                    for filter in filters {
                        reader = reader.with_ability(Ability::activated(
                            ironsmith::cost::TotalCost::free(),
                            vec![Effect::gain_life(Value::Count(filter))],
                        ));
                    }
                    let reader = game.create_object_from_definition(
                        &reader.build(),
                        caster,
                        Zone::Battlefield,
                    );
                    for (index, wanted) in expected.into_iter().enumerate() {
                        let before = game.player(caster).unwrap().life;
                        let action = LegalAction::ActivateAbility {
                            source: reader,
                            ability_index: index,
                        };
                        assert!(
                            ironsmith::compute_legal_actions(&game, caster)
                                .unwrap()
                                .contains(&action)
                        );
                        cr_audit_complete_priority_action(&mut game, caster, action).unwrap();
                        ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                        let gain = game.player(caster).unwrap().life - before;
                        if gain != i32::from(wanted) {
                            discrepancies.push(format!(
                                "{label} query={index}: gain{gain}, expected{}",
                                i32::from(wanted)
                            ));
                        }
                        assert_eq!(game.stack.len(), 1);
                        assert_eq!(game.stack[0].targets, selected);
                    }
                    let before = [
                        game.player(caster).unwrap().life,
                        game.player(other).unwrap().life,
                    ];
                    let result = ironsmith::game_loop::resolve_stack_entry_with(&mut game, &mut dm);
                    if let Err(error) = result {
                        discrepancies
                            .push(format!("{label}: instruction resolution rejected{error:?}"));
                        cases += 1;
                        continue;
                    }
                    if dm.target_requirements != usize::from(profile != 0) {
                        discrepancies.push(format!(
                            "{label}: target choices were requested again during resolution"
                        ));
                    }
                    if present && dm.object_decisions == 0 {
                        discrepancies.push(format!(
                            "{label}: no resolution-time creature choice was requested"
                        ));
                    }
                    for issue in &dm.issues {
                        discrepancies.push(format!("{label}: {issue}"));
                    }
                    let gains = [
                        game.player(caster).unwrap().life - before[0],
                        game.player(other).unwrap().life - before[1],
                    ];
                    if gains != [2, 0] {
                        discrepancies.push(format!(
                            "{label}: independent you-life gains{gains:?}, expected[2,0]"
                        ));
                    }
                    for (id, stable, _) in creatures {
                        let current = game.find_object_by_stable_id(stable).unwrap();
                        let zone = game.object(current).unwrap().zone;
                        let expected = if Some(id) == wanted {
                            Zone::Graveyard
                        } else {
                            Zone::Battlefield
                        };
                        if zone != expected {
                            discrepancies.push(format!(
                                "{label}: creature{id:?} ended in{zone:?}, expected{expected:?}"
                            ));
                        }
                    }
                    assert!(game.stack.is_empty());
                    assert_eq!(
                        game.object(game.find_object_by_stable_id(stable).unwrap())
                            .unwrap()
                            .zone,
                        Zone::Graveyard
                    );
                    game.validate_zone_consistency().unwrap();
                    cases += 1;
                }
            }
        }
    }
    assert_eq!(cases, 24);
    assert!(
        discrepancies.is_empty(),
        "CR101.3/115.10: untargeted sacrifice choices occur at resolution, may choose shrouded creatures, and an impossible sacrifice does not cancel a later independent instruction; {} mismatches in{cases} fixtures:\n{}",
        discrepancies.len(),
        discrepancies.join("\n")
    );
}

#[test]
fn cr_113_1c_113_7a_numeric_queries_keep_abilities_after_their_sources_leave() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::effects::MoveToZoneEffect;
    use ironsmith::{
        Ability, CardId, CardType, ChooseSpec, Effect, LegalAction, ObjectFilter, Phase, Value,
        Zone,
    };
    let mut cases = 0;
    let mut discrepancies = vec![];
    for caster in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for departed in [false, true] {
            let mut game = GameState::new(vec!["A".into(), "B".into()], 20);
            game.turn.active_player = caster;
            game.turn.priority_player = Some(caster);
            game.turn.phase = Phase::FirstMain;
            let source = game.create_object_from_definition(
                &CardDefinitionBuilder::new(CardId::new(), "Source-independent pending ability")
                    .card_types(vec![CardType::Artifact])
                    .with_ability(Ability::activated(
                        ironsmith::cost::TotalCost::free(),
                        vec![Effect::gain_life(1)],
                    ))
                    .build(),
                caster,
                Zone::Battlefield,
            );
            let stable = game.object(source).unwrap().stable_id;
            let mut reader =
                CardDefinitionBuilder::new(CardId::new(), "Source departure and numeric readers")
                    .card_types(vec![CardType::Artifact]);
            for filter in [
                ObjectFilter::ability(),
                ObjectFilter::ability().target_count_exact(0),
            ] {
                reader = reader.with_ability(Ability::activated(
                    ironsmith::cost::TotalCost::free(),
                    vec![Effect::gain_life(Value::Count(filter))],
                ));
            }
            reader = reader.with_ability(Ability::activated(
                ironsmith::cost::TotalCost::free(),
                vec![Effect::new(MoveToZoneEffect::new(
                    ChooseSpec::SpecificObject(source),
                    Zone::Exile,
                    false,
                ))],
            ));
            let reader =
                game.create_object_from_definition(&reader.build(), caster, Zone::Battlefield);
            let action = LegalAction::ActivateAbility {
                source,
                ability_index: 0,
            };
            assert!(
                ironsmith::compute_legal_actions(&game, caster)
                    .unwrap()
                    .contains(&action)
            );
            cr_audit_complete_priority_action(&mut game, caster, action).unwrap();
            assert_eq!(game.stack.len(), 1);
            assert!(game.stack[0].is_ability);
            assert!(game.stack[0].targets.is_empty());
            let identity = game.stack[0].target_id();
            assert_ne!(identity, source);
            if departed {
                let action = LegalAction::ActivateAbility {
                    source: reader,
                    ability_index: 2,
                };
                assert!(
                    ironsmith::compute_legal_actions(&game, caster)
                        .unwrap()
                        .contains(&action)
                );
                cr_audit_complete_priority_action(&mut game, caster, action).unwrap();
                assert_eq!(game.stack.len(), 2);
                ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
            }
            let current = game.find_object_by_stable_id(stable).unwrap();
            assert_eq!(
                game.object(current).unwrap().zone,
                if departed {
                    Zone::Exile
                } else {
                    Zone::Battlefield
                }
            );
            assert_eq!(game.stack.len(), 1);
            assert_eq!(game.stack[0].target_id(), identity);
            assert!(game.stack[0].targets.is_empty());
            let old_live_lookup = game.object(source).is_some();
            for index in 0..2 {
                let before = game.player(caster).unwrap().life;
                let action = LegalAction::ActivateAbility {
                    source: reader,
                    ability_index: index,
                };
                assert!(
                    ironsmith::compute_legal_actions(&game, caster)
                        .unwrap()
                        .contains(&action)
                );
                cr_audit_complete_priority_action(&mut game, caster, action).unwrap();
                assert_eq!(game.stack.len(), 2);
                ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                let gain = game.player(caster).unwrap().life - before;
                if gain != 1 {
                    discrepancies.push(format!("caster={caster:?} departed={departed} old_live_lookup={old_live_lookup} query={index}: gain{gain}, expected1"));
                }
                assert_eq!(game.stack.len(), 1);
                assert_eq!(game.stack[0].target_id(), identity);
                assert!(game.stack[0].is_ability);
                assert!(game.stack[0].targets.is_empty());
            }
            let before = game.player(caster).unwrap().life;
            ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
            let gain = game.player(caster).unwrap().life - before;
            if gain != 1 {
                discrepancies.push(format!("caster={caster:?} departed={departed}: original source-independent ability gain{gain}, expected1"));
            }
            assert!(game.stack.is_empty());
            assert_eq!(
                game.player(PlayerId::from_index(1 - caster.index() as u8))
                    .unwrap()
                    .life,
                20
            );
            assert_eq!(
                game.object(game.find_object_by_stable_id(stable).unwrap())
                    .unwrap()
                    .zone,
                if departed {
                    Zone::Exile
                } else {
                    Zone::Battlefield
                }
            );
            game.validate_zone_consistency().unwrap();
            cases += 1;
        }
    }
    assert_eq!(cases, 4);
    assert!(
        discrepancies.is_empty(),
        "CR113.1c/113.7a: an actual pending ability remains a countable stack object after its physical source leaves; {} mismatches in{cases} fixtures:\n{}",
        discrepancies.len(),
        discrepancies.join("\n")
    );
}

#[test]
fn cr_115_1b_702_5a_aura_spell_targets_but_attached_aura_ignores_shroud() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::continuous::{EffectTarget, Modification};
    use ironsmith::decisions::context::TargetsContext;
    use ironsmith::effects::ApplyContinuousEffect;
    use ironsmith::object::AttachmentTarget;
    use ironsmith::triggers::TriggerQueue;
    use ironsmith::{
        Ability, CardId, CardType, Effect, LegalAction, ObjectId, Phase, StaticAbility, Target,
        Until, Zone,
    };
    struct SelectHost {
        host: ObjectId,
        forbidden: ObjectId,
        decisions: usize,
    }
    impl DecisionMaker for SelectHost {
        fn decide_targets(&mut self, _: &GameState, ctx: &TargetsContext) -> Vec<Target> {
            self.decisions += 1;
            assert_eq!(ctx.requirements.len(), 1);
            let r = &ctx.requirements[0];
            assert_eq!((r.min_targets, r.max_targets), (1, Some(1)));
            assert!(r.legal_targets.contains(&Target::Object(self.host)));
            assert!(!r.legal_targets.contains(&Target::Object(self.forbidden)));
            vec![Target::Object(self.host)]
        }
    }
    let definition=ironsmith_compiler_runtime::compile_to_runtime_definition("Aura target audit", "Mana cost: {0}\nType: Enchantment — Aura\nEnchant creature\nEnchanted creature gets +1/+1.",false).expect("strict compiler must accept enchant creature Aura");
    let mut cases = 0;
    let mut discrepancies = vec![];
    for caster in [PlayerId::from_index(0), PlayerId::from_index(1)] {
        for host_controller in [PlayerId::from_index(0), PlayerId::from_index(1)] {
            let mut game = GameState::new(vec!["A".into(), "B".into()], 20);
            game.turn.active_player = caster;
            game.turn.priority_player = Some(caster);
            game.turn.phase = Phase::FirstMain;
            let creature = CardDefinitionBuilder::new(CardId::new(), "Aura host")
                .card_types(vec![CardType::Creature])
                .power_toughness(ironsmith::PowerToughness::fixed(2, 8))
                .build();
            let host =
                game.create_object_from_definition(&creature, host_controller, Zone::Battlefield);
            let forbidden = game.create_object_from_definition(
                &CardDefinitionBuilder::new(CardId::new(), "Shrouded host")
                    .card_types(vec![CardType::Creature])
                    .power_toughness(ironsmith::PowerToughness::fixed(2, 8))
                    .with_ability(Ability::static_ability(StaticAbility::shroud()))
                    .build(),
                host_controller,
                Zone::Battlefield,
            );
            let aura = game.create_object_from_definition(&definition, caster, Zone::Hand);
            let stable = game.object(aura).unwrap().stable_id;
            let helper = game.create_object_from_definition(
                &CardDefinitionBuilder::new(CardId::new(), "Aura legality changes")
                    .card_types(vec![CardType::Artifact])
                    .with_ability(Ability::activated(
                        ironsmith::cost::TotalCost::free(),
                        vec![Effect::new(ApplyContinuousEffect::new(
                            EffectTarget::Specific(host),
                            Modification::AddAbility(StaticAbility::shroud()),
                            Until::EndOfTurn,
                        ))],
                    ))
                    .with_ability(Ability::activated(
                        ironsmith::cost::TotalCost::free(),
                        vec![Effect::new(ApplyContinuousEffect::new(
                            EffectTarget::Specific(host),
                            Modification::SetCardTypes(vec![CardType::Artifact]),
                            Until::EndOfTurn,
                        ))],
                    ))
                    .build(),
                caster,
                Zone::Battlefield,
            );
            let action = ironsmith::compute_legal_actions(&game, caster)
                .unwrap()
                .into_iter()
                .find(|a| matches!(a,LegalAction::CastSpell{spell_id,..}if *spell_id==aura))
                .expect("Aura has legal unshrouded host");
            let mut dm = SelectHost {
                host,
                forbidden,
                decisions: 0,
            };
            let mut queue = TriggerQueue::new();
            cr_audit_complete_priority_action_with_dm(
                &mut game, caster, action, &mut dm, &mut queue,
            )
            .unwrap();
            assert_eq!(dm.decisions, 1);
            assert_eq!(game.stack.len(), 1);
            assert_eq!(game.stack[0].targets, vec![Target::Object(host)]);
            ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
            let aura = game.find_object_by_stable_id(stable).unwrap();
            assert_eq!(game.object(aura).unwrap().zone, Zone::Battlefield);
            assert_eq!(
                game.object(aura).unwrap().attached_to,
                Some(AttachmentTarget::Object(host))
            );
            assert_eq!(
                (game.current_power(host), game.current_toughness(host)),
                (Some(3), Some(9)),
                "compiled attached Aura supplies its static bonus"
            );
            for phase in 0..2 {
                let action = LegalAction::ActivateAbility {
                    source: helper,
                    ability_index: phase,
                };
                assert!(
                    ironsmith::compute_legal_actions(&game, caster)
                        .unwrap()
                        .contains(&action)
                );
                cr_audit_complete_priority_action_with_dm(
                    &mut game, caster, action, &mut dm, &mut queue,
                )
                .unwrap();
                assert_eq!(dm.decisions, 1);
                assert!(game.stack.last().unwrap().targets.is_empty());
                ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                ironsmith::rules::state_based::apply_state_based_actions(&mut game).unwrap();
                let current = game.find_object_by_stable_id(stable).unwrap();
                let zone = game.object(current).unwrap().zone;
                if phase == 0 {
                    assert_eq!(
                        (game.current_power(host), game.current_toughness(host)),
                        (Some(3), Some(9)),
                        "shroud does not disable the existing attached Aura bonus"
                    );
                    if zone != Zone::Battlefield
                        || game.object(current).unwrap().attached_to
                            != Some(AttachmentTarget::Object(host))
                    {
                        discrepancies.push(format!("caster={caster:?} host_controller={host_controller:?}: granting shroud dislodged Aura"));
                    }
                } else if zone != Zone::Graveyard {
                    discrepancies.push(format!("caster={caster:?} host_controller={host_controller:?}: enchant creature Aura survived host type loss"));
                }
            }
            game.validate_zone_consistency().unwrap();
            cases += 1;
        }
    }
    assert_eq!(cases, 4);
    assert!(
        discrepancies.is_empty(),
        "CR115.1b/702.5a: Aura spell target selection and ongoing enchant legality differ: {}",
        discrepancies.join("\n")
    );
}

#[test]
fn cr_702_5c_multiple_enchant_abilities_intersect_on_one_aura_target() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::decisions::context::TargetsContext;
    use ironsmith::triggers::TriggerQueue;
    use ironsmith::{CardId, CardType, LegalAction, ObjectId, Phase, Target, Zone};
    struct IntersectChoice {
        wanted: ObjectId,
        rejected: Vec<ObjectId>,
        issues: Vec<String>,
        decisions: usize,
    }
    impl DecisionMaker for IntersectChoice {
        fn decide_targets(&mut self, _: &GameState, ctx: &TargetsContext) -> Vec<Target> {
            self.decisions += 1;
            if ctx.requirements.len() != 1 {
                self.issues
                    .push(format!("requirements{}, expected1", ctx.requirements.len()));
            }
            ctx.requirements
                .iter()
                .map(|r| {
                    assert_eq!((r.min_targets, r.max_targets), (1, Some(1)));
                    assert!(r.legal_targets.contains(&Target::Object(self.wanted)));
                    for id in &self.rejected {
                        if r.legal_targets.contains(&Target::Object(*id)) {
                            self.issues
                                .push(format!("out-of-intersection candidate{id:?}"));
                        }
                    }
                    Target::Object(self.wanted)
                })
                .collect()
        }
    }
    let mut discrepancies = vec![];
    let mut cases = 0;
    for reverse in [false, true] {
        let lines = if reverse {
            "Enchant permanent you control\nEnchant creature"
        } else {
            "Enchant creature\nEnchant permanent you control"
        };
        let definition = ironsmith_compiler_runtime::compile_to_runtime_definition(
            "Multiple enchant audit",
            &format!("Mana cost: {{0}}\nType: Enchantment — Aura\n{lines}"),
            false,
        )
        .expect("strict compiler must accept both enchant abilities");
        for caster in [PlayerId::from_index(0), PlayerId::from_index(1)] {
            for intersection_exists in [false, true] {
                let other = PlayerId::from_index(1 - caster.index() as u8);
                let mut game = GameState::new(vec!["A".into(), "B".into()], 20);
                game.turn.active_player = caster;
                game.turn.priority_player = Some(caster);
                game.turn.phase = Phase::FirstMain;
                let mut rejected = vec![];
                let mut wanted = None;
                for controller in [caster, other] {
                    for creature in [false, true] {
                        if controller == caster && creature && !intersection_exists {
                            continue;
                        }
                        let builder = CardDefinitionBuilder::new(
                            CardId::new(),
                            "Enchant intersection candidate",
                        )
                        .card_types(vec![if creature {
                            CardType::Creature
                        } else {
                            CardType::Artifact
                        }]);
                        let d = if creature {
                            builder
                                .power_toughness(ironsmith::PowerToughness::fixed(2, 8))
                                .build()
                        } else {
                            builder.build()
                        };
                        let id =
                            game.create_object_from_definition(&d, controller, Zone::Battlefield);
                        if controller == caster && creature {
                            wanted = Some(id);
                        } else {
                            rejected.push(id);
                        }
                    }
                }
                let aura = game.create_object_from_definition(&definition, caster, Zone::Hand);
                let stable = game.object(aura).unwrap().stable_id;
                let action = ironsmith::compute_legal_actions(&game, caster)
                    .unwrap()
                    .into_iter()
                    .find(|a| matches!(a,LegalAction::CastSpell{spell_id,..}if *spell_id==aura));
                let label = format!(
                    "caster={caster:?} reverse={reverse} intersection={intersection_exists}"
                );
                if action.is_some() != intersection_exists {
                    discrepancies.push(format!(
                        "{label}: castable{}, expected{intersection_exists}",
                        action.is_some()
                    ));
                }
                if let (Some(action), Some(wanted)) = (action, wanted) {
                    let mut dm = IntersectChoice {
                        wanted,
                        rejected,
                        issues: vec![],
                        decisions: 0,
                    };
                    let mut queue = TriggerQueue::new();
                    cr_audit_complete_priority_action_with_dm(
                        &mut game, caster, action, &mut dm, &mut queue,
                    )
                    .unwrap();
                    assert_eq!(dm.decisions, 1);
                    for issue in dm.issues {
                        discrepancies.push(format!("{label}: {issue}"));
                    }
                    assert_eq!(game.stack.len(), 1);
                    if game.stack[0].targets != vec![Target::Object(wanted)] {
                        discrepancies.push(format!(
                            "{label}: stack targets{:?}, expected one host",
                            game.stack[0].targets
                        ));
                    }
                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                    let current = game.find_object_by_stable_id(stable).unwrap();
                    assert_eq!(game.object(current).unwrap().zone, Zone::Battlefield);
                    assert_eq!(
                        game.object(current).unwrap().attached_to,
                        Some(ironsmith::object::AttachmentTarget::Object(wanted))
                    );
                }
                game.validate_zone_consistency().unwrap();
                cases += 1;
            }
        }
    }
    assert_eq!(cases, 8);
    assert!(
        discrepancies.is_empty(),
        "CR702.5c: all enchant abilities constrain the same Aura target: {}",
        discrepancies.join("\n")
    );
}

#[test]
fn cr_702_5c_every_enchant_instance_still_restricts_the_attached_aura() {
    use ironsmith::cards::builders::CardDefinitionBuilder;
    use ironsmith::continuous::{EffectTarget, Modification};
    use ironsmith::decisions::context::TargetsContext;
    use ironsmith::effects::ApplyContinuousEffect;
    use ironsmith::triggers::TriggerQueue;
    use ironsmith::{
        Ability, CardId, CardType, Effect, LegalAction, ManaCost, ObjectFilter, ObjectId, Phase,
        StaticAbility, Subtype, Target, Until, Zone,
    };
    struct HostChoice(ObjectId);
    impl DecisionMaker for HostChoice {
        fn decide_targets(&mut self, _: &GameState, ctx: &TargetsContext) -> Vec<Target> {
            ctx.requirements
                .iter()
                .map(|r| {
                    assert_eq!((r.min_targets, r.max_targets), (1, Some(1)));
                    assert!(r.legal_targets.contains(&Target::Object(self.0)));
                    Target::Object(self.0)
                })
                .collect()
        }
    }
    let mut cases = 0;
    let mut discrepancies = vec![];
    for native in [false, true] {
        for reverse in [false, true] {
            let filters = if reverse {
                [
                    ObjectFilter::permanent().you_control(),
                    ObjectFilter::creature(),
                ]
            } else {
                [
                    ObjectFilter::creature(),
                    ObjectFilter::permanent().you_control(),
                ]
            };
            let definition = if native {
                CardDefinitionBuilder::new(CardId::new(), "Native two enchant instances")
                    .card_types(vec![CardType::Enchantment])
                    .subtypes(vec![Subtype::Aura])
                    .mana_cost(ManaCost::new())
                    .enchants(filters[0].clone())
                    .with_ability(Ability::static_ability(StaticAbility::enchant(
                        filters[0].clone().into(),
                    )))
                    .with_ability(Ability::static_ability(StaticAbility::enchant(
                        filters[1].clone().into(),
                    )))
                    .build()
            } else {
                let lines = if reverse {
                    "Enchant permanent you control\nEnchant creature"
                } else {
                    "Enchant creature\nEnchant permanent you control"
                };
                ironsmith_compiler_runtime::compile_to_runtime_definition(
                    "Compiled two ongoing enchant restrictions",
                    &format!("Mana cost: {{0}}\nType: Enchantment — Aura\n{lines}"),
                    false,
                )
                .expect("strict compiler must accept two enchant instances")
            };
            for caster in [PlayerId::from_index(0), PlayerId::from_index(1)] {
                for lose_creature in [false, true] {
                    let other = PlayerId::from_index(1 - caster.index() as u8);
                    let mut game = GameState::new(vec!["A".into(), "B".into()], 20);
                    game.turn.active_player = caster;
                    game.turn.priority_player = Some(caster);
                    game.turn.phase = Phase::FirstMain;
                    let host = game.create_object_from_definition(
                        &CardDefinitionBuilder::new(
                            CardId::new(),
                            "Both enchant restrictions initially legal",
                        )
                        .card_types(vec![CardType::Creature])
                        .power_toughness(ironsmith::PowerToughness::fixed(2, 8))
                        .build(),
                        caster,
                        Zone::Battlefield,
                    );
                    let aura = game.create_object_from_definition(&definition, caster, Zone::Hand);
                    let stable = game.object(aura).unwrap().stable_id;
                    let modification = if lose_creature {
                        Modification::SetCardTypes(vec![CardType::Artifact])
                    } else {
                        Modification::ChangeController(other)
                    };
                    let helper = game.create_object_from_definition(
                        &CardDefinitionBuilder::new(
                            CardId::new(),
                            "Invalidate exactly one enchant restriction",
                        )
                        .card_types(vec![CardType::Artifact])
                        .with_ability(Ability::activated(
                            ironsmith::cost::TotalCost::free(),
                            vec![Effect::new(ApplyContinuousEffect::new(
                                EffectTarget::Specific(host),
                                modification,
                                Until::EndOfTurn,
                            ))],
                        ))
                        .build(),
                        caster,
                        Zone::Battlefield,
                    );
                    let action = ironsmith::compute_legal_actions(&game, caster)
                        .unwrap()
                        .into_iter()
                        .find(|a| matches!(a,LegalAction::CastSpell{spell_id,..}if *spell_id==aura))
                        .expect("host initially satisfies every enchant restriction");
                    let mut queue = TriggerQueue::new();
                    let mut dm = HostChoice(host);
                    cr_audit_complete_priority_action_with_dm(
                        &mut game, caster, action, &mut dm, &mut queue,
                    )
                    .unwrap();
                    // Target cardinality is covered by CR-192's separate cast-time regression.
                    // Here every actual selected occurrence names the same legal intersection host.
                    assert!(
                        game.stack
                            .last()
                            .unwrap()
                            .targets
                            .iter()
                            .all(|t| *t == Target::Object(host))
                    );
                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                    let aura = game.find_object_by_stable_id(stable).unwrap();
                    assert_eq!(game.object(aura).unwrap().zone, Zone::Battlefield);
                    assert_eq!(
                        game.object(aura).unwrap().attached_to,
                        Some(ironsmith::object::AttachmentTarget::Object(host))
                    );
                    let label = format!(
                        "native={native} reverse={reverse} caster={caster:?} lose_creature={lose_creature}"
                    );
                    let enchant_count = game
                        .current_characteristics(aura)
                        .unwrap()
                        .static_abilities
                        .iter()
                        .filter(|a| a.enchant_filter().is_some())
                        .count();
                    if enchant_count != 2 {
                        discrepancies.push(format!(
                            "{label}: retained{enchant_count} enchant abilities, expected2"
                        ));
                    }
                    if native {
                        assert_eq!(
                            enchant_count, 2,
                            "native fixture must truly contain both enchant abilities"
                        );
                    }
                    cr_audit_complete_priority_action_with_dm(
                        &mut game,
                        caster,
                        LegalAction::ActivateAbility {
                            source: helper,
                            ability_index: 0,
                        },
                        &mut dm,
                        &mut queue,
                    )
                    .unwrap();
                    assert!(game.stack.last().unwrap().targets.is_empty());
                    ironsmith::game_loop::resolve_stack_entry(&mut game).unwrap();
                    assert_eq!(game.current_is_creature(host), !lose_creature);
                    assert_eq!(
                        game.current_controller(host),
                        Some(if lose_creature { caster } else { other })
                    );
                    ironsmith::rules::state_based::apply_state_based_actions(&mut game).unwrap();
                    let aura = game.find_object_by_stable_id(stable).unwrap();
                    if game.object(aura).unwrap().zone != Zone::Graveyard {
                        discrepancies.push(format!(
                            "{label}: Aura stayed attached after one enchant restriction failed"
                        ));
                    } else {
                        assert_eq!(game.object(aura).unwrap().owner, caster);
                    }
                    game.validate_zone_consistency().unwrap();
                    cases += 1;
                }
            }
        }
    }
    assert_eq!(cases, 16);
    assert!(
        discrepancies.is_empty(),
        "CR702.5c/303.4c: each enchant instance restricts the same Aura continuously: {}",
        discrepancies.join("\n")
    );
}

